INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Harbour Grand Hong Kong');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '香港港島海逸君綽酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'No. 23 Oil Street, North Point, Eastern District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '828');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>The Harbour Grand Hong Kong is an icon of fine luxury hospitality that enjoys an excellent location near the city’s fashionable Sogo shopping area in Causeway Bay. The property is conveniently situated within walking distance of Hong Kong''s extensive Mass Transit Railway (MTR) system, sitting by the Fortress Hill Station and Hong Hum Station.</p><p>Located at the heart of Hong Kong Island, each of the hotel''s rooms enjoys unobstructed views of Victoria Harbor. Discerning guests can choose luxury rooms with Jacuzzis and terraces. Suites with fully-equipped kitchens cater to guests planning longer stays, while all rooms enjoy Internet access.</p><p>Three restaurants in splendid settings with bay window views of the surrounding landscapes serve Chinese, Western and Japanese cuisines. A coffee lounge is located on-site.</p><p>Fully equipped meeting rooms and a business center are available to guests to conduct any business related activities and events.</p><p>To ensure a relaxing and pleasurable stay to all guests, quality massage, spa and sauna facilities are available as well as an outdoor swimming pool. For those keeping to a tight exercise schedule, a fully equipped gym is also on-site, where guests can break a sweat whilst taking in incomparable views of Hong Kong.</p><p>According to Hong Kong Governments new law, Product Eco-responsibility (Amendment) Bill 2023, effective from 22nd April 2024, hotels are not allowed to provide disposable toiletries and in-room plastic bottled water to guests for free but can be provided upon request at a charge.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc45372b-192b-6c5b-298d-f447631ace80', 344950, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc45372b-192b-6c5b-298d-f447631ace80', 344950, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5b3eea11-4778-eaf7-16a6-7c40034e9a5b', 344950, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5b3eea11-4778-eaf7-16a6-7c40034e9a5b', 344950, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Children between 0 and 11 years old can stay for free if no extra bed is needed.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1cda8510-3504-ca07-ba1b-0b0c8171a983', 344950, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1cda8510-3504-ca07-ba1b-0b0c8171a983', 344950, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('707ba667-1427-6eb9-7d7a-2004906e100f', 344950, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('707ba667-1427-6eb9-7d7a-2004906e100f', 344950, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Asian</p><p>Opening hours: [Mon - Sun] 07:00-10:30 Open</p><table><tr><td>Children 3 years old and under</td><td>Free</td></tr><tr><td>Children 4–11 years old</td><td>HK$165.00 (approx. $21.04) per person</td></tr><tr><td>Children 12–17 years old</td><td>HK$235.00 (approx. $29.96) per person</td></tr><tr><td>Adult</td><td>HK$235.00 (approx. $29.96) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d6ea1dbf-6ad5-beb9-1f57-77b46b3f362f', 344950, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d6ea1dbf-6ad5-beb9-1f57-77b46b3f362f', 344950, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>The deposit is determined based on the duration of your stay. The charge is HK$1,000.00 (approx. $127.49) per night.</strong></p><p>Deposit Payment Methods: <strong>This property accepts cash and credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment .</strong></p>');
