INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Harbour Grand Hong Kong');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '香港港島海逸君綽酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'No. 23 Oil Street, North Point, Eastern District, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '828');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75a78d40-b390-190d-2619-ac1d9711ab63', 344950, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>The Harbour Grand Hong Kong is an icon of fine luxury hospitality that enjoys an excellent location near the city’s fashionable Sogo shopping area in Causeway Bay. The property is conveniently situated within walking distance of Hong Kong''s extensive Mass Transit Railway (MTR) system, sitting by the Fortress Hill Station and Hong Hum Station.</p><p>Located at the heart of Hong Kong Island, each of the hotel''s rooms enjoys unobstructed views of Victoria Harbor. Discerning guests can choose luxury rooms with Jacuzzis and terraces. Suites with fully-equipped kitchens cater to guests planning longer stays, while all rooms enjoy Internet access.</p><p>Three restaurants in splendid settings with bay window views of the surrounding landscapes serve Chinese, Western and Japanese cuisines. A coffee lounge is located on-site.</p><p>Fully equipped meeting rooms and a business center are available to guests to conduct any business related activities and events.</p><p>To ensure a relaxing and pleasurable stay to all guests, quality massage, spa and sauna facilities are available as well as an outdoor swimming pool. For those keeping to a tight exercise schedule, a fully equipped gym is also on-site, where guests can break a sweat whilst taking in incomparable views of Hong Kong.</p><p>According to Hong Kong Governments new law, Product Eco-responsibility (Amendment) Bill 2023, effective from 22nd April 2024, hotels are not allowed to provide disposable toiletries and in-room plastic bottled water to guests for free but can be provided upon request at a charge.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc45372b-192b-6c5b-298d-f447631ace80', 344950, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc45372b-192b-6c5b-298d-f447631ace80', 344950, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5b3eea11-4778-eaf7-16a6-7c40034e9a5b', 344950, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5b3eea11-4778-eaf7-16a6-7c40034e9a5b', 344950, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 11 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1cda8510-3504-ca07-ba1b-0b0c8171a983', 344950, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1cda8510-3504-ca07-ba1b-0b0c8171a983', 344950, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('707ba667-1427-6eb9-7d7a-2004906e100f', 344950, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('707ba667-1427-6eb9-7d7a-2004906e100f', 344950, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Châu Á</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:30 Đang Mở</p><table><tr><td>Trẻ em 3 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 4–11 tuổi</td><td>165,00 HK$(khoảng 546.045₫) mỗi người</td></tr><tr><td>Trẻ em 12–17 tuổi</td><td>235,00 HK$(khoảng 777.700₫) mỗi người</td></tr><tr><td>Người lớn</td><td>235,00 HK$(khoảng 777.700₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d6ea1dbf-6ad5-beb9-1f57-77b46b3f362f', 344950, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d6ea1dbf-6ad5-beb9-1f57-77b46b3f362f', 344950, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khoản tiền cọc được tính dựa trên độ dài lưu trú của bạn. Mức phí là 1.000,00 HK$ (khoảng 3.309.362₫)/đêm.</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận tiền mặt và thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu .</strong></p>');
