INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'The Kowloon Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '香港九龍酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '19-21 Nathan Road (Mudun Dao), Tsim Sha Tsui, Yau Tsim Mong District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '736');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>The Kowloon Hotel is located in Tsim Sha Tsui, close to the Hong Kong waterfront, the Hong Kong Cultural Center, the Space Museum and the Star Ferry Terminal. It''s also within walking distance of the Tsim Sha Tsui MTR station.</p><p>This hotel offers a range of room types, all of which feature contemporary-style furnishings and high-speed broadband Internet access (two devices per room). Guestrooms also feature safes, hairdryers, LCD TVs and IDD phones. Harbour Club guests on the hotel''s upper floors enjoy exclusive access to the Harbour Club Lounge. Guests can choose from smoking and non-smoking floors.</p><p>Guests can enjoy luxury dim sum and Chinese cuisine at Loong Yat Heen, international fare served à la carte or buffet-style at The Window Café, and light meals, drinks and sandwiches at Coffee Corner. Drinks and cocktails are available at The Middle Row Bar.</p><p>This Hong Kong hotel houses a business center and two function rooms which can be used for a range of events.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6e2b18f4-82cf-b77b-f428-1bddf26d9021', 425085, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6e2b18f4-82cf-b77b-f428-1bddf26d9021', 425085, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 14:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0b992d15-2189-3037-4087-2e9bc52b8ca3', 425085, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0b992d15-2189-3037-4087-2e9bc52b8ca3', 425085, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Children between 0 and 11 years old can stay for free if no extra bed is needed.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('78b0762c-7c5f-f9b4-73b4-f4e83a81b865', 425085, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('78b0762c-7c5f-f9b4-73b4-f4e83a81b865', 425085, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs can be added. Extra bed policies vary according to room type. Please refer to the relevant room type policy.</p><p>Fees for extra beds and cribs are not included in the total and must be paid at the hotel.</p><table><tr><td>Children 1 year old and under</td><td>Extra crib: Free</td></tr></table>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e9fb61b5-f4b9-9672-8086-35c19c3308e7', 425085, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e9fb61b5-f4b9-9672-8086-35c19c3308e7', 425085, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Western</p><p>Opening hours: [Mon - Sun] 07:00-10:30 Open</p><table><tr><td>Children 17 years old and under</td><td>HK$148.50 (approx. $18.93) per person</td></tr><tr><td>Adult</td><td>HK$148.50 (approx. $18.93) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27171a37-2992-eec6-5c97-024da6d3d36c', 425085, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27171a37-2992-eec6-5c97-024da6d3d36c', 425085, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>The deposit is determined based on the duration of your stay. The charge is HK$500.00 (approx. $63.74) per night.</strong></p><p>Deposit Payment Methods: <strong>This property accepts cash and credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment within 14 days after check-out.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0d766ff5-5eaf-ca4e-62ae-a411e9b7a55e', 425085, 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
