INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'The Kowloon Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '香港九龍酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '19-21 Nathan Road (Mudun Dao), Tsim Sha Tsui, Yau Tsim Mong District, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '736');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae357b63-f8f5-78ee-67dc-da24a038d19a', 425085, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>The Kowloon Hotel is located in Tsim Sha Tsui, close to the Hong Kong waterfront, the Hong Kong Cultural Center, the Space Museum and the Star Ferry Terminal. It''s also within walking distance of the Tsim Sha Tsui MTR station.</p><p>This hotel offers a range of room types, all of which feature contemporary-style furnishings and high-speed broadband Internet access (two devices per room). Guestrooms also feature safes, hairdryers, LCD TVs and IDD phones. Harbour Club guests on the hotel''s upper floors enjoy exclusive access to the Harbour Club Lounge. Guests can choose from smoking and non-smoking floors.</p><p>Guests can enjoy luxury dim sum and Chinese cuisine at Loong Yat Heen, international fare served à la carte or buffet-style at The Window Café, and light meals, drinks and sandwiches at Coffee Corner. Drinks and cocktails are available at The Middle Row Bar.</p><p>This Hong Kong hotel houses a business center and two function rooms which can be used for a range of events.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6e2b18f4-82cf-b77b-f428-1bddf26d9021', 425085, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6e2b18f4-82cf-b77b-f428-1bddf26d9021', 425085, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 14:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0b992d15-2189-3037-4087-2e9bc52b8ca3', 425085, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0b992d15-2189-3037-4087-2e9bc52b8ca3', 425085, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 11 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('78b0762c-7c5f-f9b4-73b4-f4e83a81b865', 425085, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('78b0762c-7c5f-f9b4-73b4-f4e83a81b865', 425085, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều có thể bổ sung cũi. Chính sách về giường phụ khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</p><p>Phí giường phụ và cũi chưa được bao gồm trong tổng giá và phải được thanh toán tại khách sạn.</p><table><tr><td>Trẻ em 1 tuổi trở xuống</td><td>Thêm cũi: Miễn phí</td></tr></table>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e9fb61b5-f4b9-9672-8086-35c19c3308e7', 425085, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e9fb61b5-f4b9-9672-8086-35c19c3308e7', 425085, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Tây phương</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:30 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>148,50 HK$(khoảng 491.724₫) mỗi người</td></tr><tr><td>Người lớn</td><td>148,50 HK$(khoảng 491.724₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27171a37-2992-eec6-5c97-024da6d3d36c', 425085, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27171a37-2992-eec6-5c97-024da6d3d36c', 425085, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khoản tiền cọc được tính dựa trên độ dài lưu trú của bạn. Mức phí là 500,00 HK$ (khoảng 1.655.637₫)/đêm.</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận tiền mặt và thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 14 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0d766ff5-5eaf-ca4e-62ae-a411e9b7a55e', 425085, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
