INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Regal Airport Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '香港富豪機場酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'No.9 Cheong Tat Rd, Chek Lap Kok, Islands District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '1171');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Regal Airport Hotel Hong Kong has been recognized as the World''s Best Airport Hotel by Business Traveller UK Magazine. Directly connected to, and only a two-minute walk from the Arrival Hall A of Terminal 1 of Hong Kong International Airport, the Hotel is also in close proximity to the AsiaWorld-Expo convention centre and just 10-minute ride to Hong Kong-Zhuhai-Macao Bridge Hong Kong Port by public transport. All 1,171 smoke-free guest rooms and suites have contemporary design and comfort is ensured by the double-glazed soundproof windows and comprehensive in-room amenities. Regal Airport Hotel Hong Kong also features world-class meeting facilities with 30 function rooms and one of the largest pillar-free grand ballrooms in a hotel equipped with a 9-meter width and 4-meter height HD LED wall and 270-degree 3D Projection Mapping technology. Additionally, the Hotel features a variety of authentic cuisine at its six restaurants and bars, and it has a complete range of recreational facilities including the award-winning OM Spa, state-of-the-art gym, an outdoor pool and an indoor heated swimming pool.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5634c667-93f2-8721-5903-4a593d09f117', 436519, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5634c667-93f2-8721-5903-4a593d09f117', 436519, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('577da849-4eda-67b4-0c6a-f1af5a5d0951', 436519, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('577da849-4eda-67b4-0c6a-f1af5a5d0951', 436519, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Children between 0 and 11 years old can stay for free if no extra bed is needed.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9f0c2fe5-f6b4-1761-e0d8-8f6b6a9d076a', 436519, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9f0c2fe5-f6b4-1761-e0d8-8f6b6a9d076a', 436519, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('85bc6959-250a-a8e4-62f6-1a6df78ebfdd', 436519, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('85bc6959-250a-a8e4-62f6-1a6df78ebfdd', 436519, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 06:30-10:30 Open</p><table><tr><td>Children 17 years old and under</td><td>HK$284.00 (approx. $36.21) per person</td></tr><tr><td>Adult</td><td>HK$284.00 (approx. $36.21) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dab5dc73-b964-c6cf-7d23-904500262d39', 436519, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dab5dc73-b964-c6cf-7d23-904500262d39', 436519, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of HK$500.00 (approx. $63.74) is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts cash and credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment within 7 days after check-out.</strong></p>');
