INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Regal Airport Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '香港富豪機場酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'No.9 Cheong Tat Rd, Chek Lap Kok, Islands District, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '1171');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a98843e-0005-f2ec-5beb-8844f8f48b6b', 436519, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Regal Airport Hotel Hong Kong has been recognized as the World''s Best Airport Hotel by Business Traveller UK Magazine. Directly connected to, and only a two-minute walk from the Arrival Hall A of Terminal 1 of Hong Kong International Airport, the Hotel is also in close proximity to the AsiaWorld-Expo convention centre and just 10-minute ride to Hong Kong-Zhuhai-Macao Bridge Hong Kong Port by public transport. All 1,171 smoke-free guest rooms and suites have contemporary design and comfort is ensured by the double-glazed soundproof windows and comprehensive in-room amenities. Regal Airport Hotel Hong Kong also features world-class meeting facilities with 30 function rooms and one of the largest pillar-free grand ballrooms in a hotel equipped with a 9-meter width and 4-meter height HD LED wall and 270-degree 3D Projection Mapping technology. Additionally, the Hotel features a variety of authentic cuisine at its six restaurants and bars, and it has a complete range of recreational facilities including the award-winning OM Spa, state-of-the-art gym, an outdoor pool and an indoor heated swimming pool.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5634c667-93f2-8721-5903-4a593d09f117', 436519, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5634c667-93f2-8721-5903-4a593d09f117', 436519, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('577da849-4eda-67b4-0c6a-f1af5a5d0951', 436519, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('577da849-4eda-67b4-0c6a-f1af5a5d0951', 436519, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 11 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9f0c2fe5-f6b4-1761-e0d8-8f6b6a9d076a', 436519, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9f0c2fe5-f6b4-1761-e0d8-8f6b6a9d076a', 436519, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('85bc6959-250a-a8e4-62f6-1a6df78ebfdd', 436519, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('85bc6959-250a-a8e4-62f6-1a6df78ebfdd', 436519, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:30 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>284,00 HK$(khoảng 940.402₫) mỗi người</td></tr><tr><td>Người lớn</td><td>284,00 HK$(khoảng 940.402₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dab5dc73-b964-c6cf-7d23-904500262d39', 436519, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dab5dc73-b964-c6cf-7d23-904500262d39', 436519, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 500,00 HK$ (khoảng 1.654.681₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận tiền mặt và thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
