INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'The Harbourview-Chinese YMCA of Hong Kong');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '灣景國際-香港中華基督教青年會');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'No.4 Harbour Road, Wan Chai District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '320');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Facing Victoria Harbour, the Harbourview is a short stroll from the Hong Kong Convention and Exhibition Centre, the Wan Chai MTR station and the Kowloon Ferry Terminal. Central and Pacific Place Mall are also easily accessible from the hotel.</p><p>Guestrooms in this Hong Kong hotel feature amenities including IDD telephones, satellite and cable TVs, mini-bars, safes, hairdryers, air-conditioning and Wi-Fi connectivity. Over half the hotel rooms have panoramic views of Victoria Harbour.</p><p>The hotel''s business services include valet, travel, limousine, banquet and event planning services. Also available is a function room for private seminars, meetings and conferences which can accomodate up to 250 guests.</p><p>This Hong Kong hotel''s main restaurant offers views of Victoria Harbour and serves a variety of international cuisines. The teahouse also provides a relaxed setting, drinks and snacks.</p><p>The hotel also houses a fully-equipped fitness center.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df895542-f301-e3b3-38b2-fddbdac288d8', 436871, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df895542-f301-e3b3-38b2-fddbdac288d8', 436871, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6f069ac5-f0df-b4ba-eb2a-fea93a023f16', 436871, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6f069ac5-f0df-b4ba-eb2a-fea93a023f16', 436871, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Children between 0 and 3 years old can stay for free if no extra bed is needed.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d7fc1361-1aee-0b2c-25d9-f7486a27b673', 436871, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d7fc1361-1aee-0b2c-25d9-f7486a27b673', 436871, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0002487e-c15f-7423-0dfe-6815ef80aaa6', 436871, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0002487e-c15f-7423-0dfe-6815ef80aaa6', 436871, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:00-10:30 Open</p><table><tr><td>Children 3 years old and under</td><td>Free</td></tr><tr><td>Children 4–17 years old</td><td>HK$219.00 (approx. $27.92) per person</td></tr><tr><td>Adult</td><td>HK$219.00 (approx. $27.92) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
