INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'The Harbourview-Chinese YMCA of Hong Kong');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '灣景國際-香港中華基督教青年會');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'No.4 Harbour Road, Loan Tử, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '320');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2cdaf313-842b-1c5d-af86-3ab8db39089e', 436871, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Facing Victoria Harbour, the Harbourview is a short stroll from the Hong Kong Convention and Exhibition Centre, the Wan Chai MTR station and the Kowloon Ferry Terminal. Central and Pacific Place Mall are also easily accessible from the hotel.</p><p>Guestrooms in this Hong Kong hotel feature amenities including IDD telephones, satellite and cable TVs, mini-bars, safes, hairdryers, air-conditioning and Wi-Fi connectivity. Over half the hotel rooms have panoramic views of Victoria Harbour.</p><p>The hotel''s business services include valet, travel, limousine, banquet and event planning services. Also available is a function room for private seminars, meetings and conferences which can accomodate up to 250 guests.</p><p>This Hong Kong hotel''s main restaurant offers views of Victoria Harbour and serves a variety of international cuisines. The teahouse also provides a relaxed setting, drinks and snacks.</p><p>The hotel also houses a fully-equipped fitness center.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df895542-f301-e3b3-38b2-fddbdac288d8', 436871, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df895542-f301-e3b3-38b2-fddbdac288d8', 436871, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6f069ac5-f0df-b4ba-eb2a-fea93a023f16', 436871, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6f069ac5-f0df-b4ba-eb2a-fea93a023f16', 436871, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 3 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d7fc1361-1aee-0b2c-25d9-f7486a27b673', 436871, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d7fc1361-1aee-0b2c-25d9-f7486a27b673', 436871, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0002487e-c15f-7423-0dfe-6815ef80aaa6', 436871, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0002487e-c15f-7423-0dfe-6815ef80aaa6', 436871, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:30 Đang Mở</p><table><tr><td>Trẻ em 3 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 4–17 tuổi</td><td>219,00 HK$(khoảng 724.750₫) mỗi người</td></tr><tr><td>Người lớn</td><td>219,00 HK$(khoảng 724.750₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
