INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Silka Far East Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '香港遠東絲麗酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '135-143 Castle Peak Road, Tsuen Wan District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '240');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>The Silka Far East Hotel is a budget hotel located in Tsuen Wan. Close to the Tsuen Wan MTR station Hong Kong''s many great tourist attractions are easily accessible. Local highlights include the Sam Tung Uk Museum, Tin Hau Temple and Discovery Park, one of Hong Kong''s largest shopping centers. Hong Kong International Airport and Hong Kong Disneyland are 30 minutes away. Two of Tseun Wan''s major hospitals, Yan Chai Hospital and Tsuen Wan Adventist Hospital, are close at hand.</p><p>Simple and clean, the rooms are on the small side but are stylishly decorated with neutral tones and splashes of color.</p><p>The Function Room is open for buffet breakfast every morning and can also be booked for events of up to 80 people.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aadc89b9-7a1d-0109-e724-4249555b1dba', 511694, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aadc89b9-7a1d-0109-e724-4249555b1dba', 511694, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 14:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('61b1df0a-700d-5df8-9b1b-acef6418ac78', 511694, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('61b1df0a-700d-5df8-9b1b-acef6418ac78', 511694, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Children between 0 and 12 years old can stay for free if no extra bed is needed.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('567663e6-6bba-af45-1b9b-f79f6d443d30', 511694, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('567663e6-6bba-af45-1b9b-f79f6d443d30', 511694, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs and extra beds cannot be added.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b683a00c-ff30-b52a-0fc8-95061c88ab89', 511694, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b683a00c-ff30-b52a-0fc8-95061c88ab89', 511694, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:00-10:00 Open</p><table><tr><td>Children 17 years old and under</td><td>HK$86.00 (approx. $10.96) per person</td></tr><tr><td>Adult</td><td>HK$86.00 (approx. $10.96) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c6360be9-60e3-82da-3c1f-672aab755c6b', 511694, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
