INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Silka Far East Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '香港遠東絲麗酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '135-143 Castle Peak Road, Thuyền Loan, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '240');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('267cb6bf-a1d8-2ec0-e5b3-eac958597fa6', 511694, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>The Silka Far East Hotel is a budget hotel located in Tsuen Wan. Close to the Tsuen Wan MTR station Hong Kong''s many great tourist attractions are easily accessible. Local highlights include the Sam Tung Uk Museum, Tin Hau Temple and Discovery Park, one of Hong Kong''s largest shopping centers. Hong Kong International Airport and Hong Kong Disneyland are 30 minutes away. Two of Tseun Wan''s major hospitals, Yan Chai Hospital and Tsuen Wan Adventist Hospital, are close at hand.</p><p>Simple and clean, the rooms are on the small side but are stylishly decorated with neutral tones and splashes of color.</p><p>The Function Room is open for buffet breakfast every morning and can also be booked for events of up to 80 people.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aadc89b9-7a1d-0109-e724-4249555b1dba', 511694, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aadc89b9-7a1d-0109-e724-4249555b1dba', 511694, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 14:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('61b1df0a-700d-5df8-9b1b-acef6418ac78', 511694, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('61b1df0a-700d-5df8-9b1b-acef6418ac78', 511694, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 12 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('567663e6-6bba-af45-1b9b-f79f6d443d30', 511694, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('567663e6-6bba-af45-1b9b-f79f6d443d30', 511694, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b683a00c-ff30-b52a-0fc8-95061c88ab89', 511694, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b683a00c-ff30-b52a-0fc8-95061c88ab89', 511694, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>86,00 HK$(khoảng 284.770₫) mỗi người</td></tr><tr><td>Người lớn</td><td>86,00 HK$(khoảng 284.770₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c6360be9-60e3-82da-3c1f-672aab755c6b', 511694, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
