INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hotel Samjung');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '삼정 호텔');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '150 Bongeunsa-ro, Gangnam-gu, Seoul, 06125, South Korea');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '160');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Hotel Samjung, you''ll be centrally located in Seoul, within a 5-minute drive of Starfield COEX Mall and COEX Convention and Exhibition Center. This hotel is 4 mi (6.5 km) from Lotte World and 4.8 mi (7.8 km) from Dongdaemun History and Culture Park.</p><p>Make use of convenient amenities such as complimentary wireless internet access, concierge services, and wedding services.</p><p>Enjoy a meal at the restaurant or snacks in the coffee shop/cafe. The hotel also offers room service (during limited hours). Buffet breakfasts are available daily from 7:00 AM to 10 AM for a fee.</p><p>Featured amenities include complimentary wired internet access, a 24-hour business center, and a 24-hour front desk. Free self parking is available onsite.</p><p>Make yourself at home in one of the 160 individually furnished guestrooms, featuring refrigerators and flat-screen televisions. Complimentary wired and wireless internet access keeps you connected, and cable programming provides entertainment. Bathrooms feature bathtubs or showers, bidets, and hair dryers. Conveniences include phones, as well as safes and desks.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aaae404d-f23d-0fcb-bd35-041c24e73bea', 687631, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aaae404d-f23d-0fcb-bd35-041c24e73bea', 687631, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p><p>If you will arrive outside of check-in hours, contact the property in advance</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c99779e7-4765-819c-fef2-c408c992297d', 687631, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c99779e7-4765-819c-fef2-c408c992297d', 687631, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f2c1240f-854d-df47-911b-ef2bb10ddec4', 687631, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f2c1240f-854d-df47-911b-ef2bb10ddec4', 687631, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs and extra beds cannot be added.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('94caccc9-a17e-3a74-7531-cbc645754df9', 687631, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('94caccc9-a17e-3a74-7531-cbc645754df9', 687631, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:00-10:00 Open</p><table><tr><td>Adult</td><td>KRW 33,000 (approx. $24.24) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fb08475e-162e-3d5a-36cf-b28a825a9b4d', 687631, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fb08475e-162e-3d5a-36cf-b28a825a9b4d', 687631, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of KRW 20,000 (approx. $14.73) is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards and cash</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment on the day of check-out.</strong></p>');
