INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hotel Samjung');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '삼정 호텔');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '150 Bongeunsa-ro, Gangnam-gu, 06125 Seoul, Hàn Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '160');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd01842a-c573-1ba1-c184-97ad9743fef1', 687631, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Hotel Samjung ở trung tâm Seoul, cách Trung tâm Thương mại Starfield COEX Mall và Trung tâm hội nghị và triển lãm COEX 5 phút lái xe. Khách sạn này cách Khu vui chơi Lotte World 6,5 km và cách Công viên Văn hóa và Lịch sử Dongdaemun 7,8 km.</p><p>Hãy tận hưởng những dịch vụ, tiện ích như quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và dịch vụ cưới.</p><p>Khách có thể thưởng thức những món ăn ngon tại nhà hàng hoặc dùng bữa nhẹ tại quán cà phê. Khách sạn này còn cung cấp dịch vụ phòng (có giới hạn thời gian). Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:00 đến 10:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm truy cập Internet tốc độ cao (có dây) miễn phí, trung tâm dịch vụ văn phòng phục vụ 24 giờ và quầy tiếp tân phục vụ 24 giờ/ngày. Có bãi đậu xe tự phục vụ miễn phí trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 160 phòng trang bị nội thất với thiết kế riêng biệt với tủ lạnh và TV màn hình phẳng. Truy cập internet có dây và không dây miễn phí giúp bạn luôn kết nối; và các chương trình truyền hình cáp sẽ mang đến những giây phút giải trí thoải mái. Các phòng tắm được trang bị bồn tắm hoặc buồng tắm vòi sen, chậu vệ sinh/vòi rửa và máy sấy tóc. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật và bàn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aaae404d-f23d-0fcb-bd35-041c24e73bea', 687631, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aaae404d-f23d-0fcb-bd35-041c24e73bea', 687631, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c99779e7-4765-819c-fef2-c408c992297d', 687631, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c99779e7-4765-819c-fef2-c408c992297d', 687631, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f2c1240f-854d-df47-911b-ef2bb10ddec4', 687631, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f2c1240f-854d-df47-911b-ef2bb10ddec4', 687631, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('94caccc9-a17e-3a74-7531-cbc645754df9', 687631, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('94caccc9-a17e-3a74-7531-cbc645754df9', 687631, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:00 Đang Mở</p><table><tr><td>Người lớn</td><td>33.000 KRW(khoảng 631.019₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fb08475e-162e-3d5a-36cf-b28a825a9b4d', 687631, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fb08475e-162e-3d5a-36cf-b28a825a9b4d', 687631, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 20.000 KRW (khoảng 382.436₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng và tiền mặt</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Vào ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fb825c9-9189-8eb1-9754-0cb64f1b0b33', 687631, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fb825c9-9189-8eb1-9754-0cb64f1b0b33', 687631, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Không được phép mang theo thú cưng</p>');
