INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Scandic Sluseholmen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Molestien 11, Copenhagen, Hovedstaden, 2450, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '215');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>A stay at Scandic Sluseholmen places you in the heart of Copenhagen, within a 10-minute drive of Tivoli Gardens and City Hall Square. This hotel is 3.8 mi (6 km) from Nyhavn and 3.9 mi (6.3 km) from Amalienborg Palace.</p><p>Enjoy a range of recreational amenities, including a hot tub, a sauna, and a 24-hour fitness center. Additional amenities at this hotel include complimentary wireless internet access, concierge services, and a reception hall.</p><p>Grab a bite to eat at Elements, a restaurant where you can enjoy drinks at the bar/lounge and dine alfresco. Or stay in and take advantage of the room service (during limited hours). Buffet breakfasts are served on weekdays from 6:30 AM to 9:30 AM and on weekends from 7:00 AM to 10:00 AM for a fee.</p><p>Featured amenities include dry cleaning/laundry services, a 24-hour front desk, and luggage storage. Planning an event in Copenhagen? This hotel has 5608 square feet (521 square meters) of space consisting of conference space and 20 meeting rooms. Self parking (subject to charges) is available onsite.</p><p>Stay in one of 215 guestrooms featuring LED televisions. Complimentary wireless internet access keeps you connected, and satellite programming is available for your entertainment. Private bathrooms have complimentary toiletries and hair dryers. Conveniences include phones, as well as safes and desks.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '274637');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80b959d8-a301-16e4-b8e9-d0683d89e255', 744861, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80b959d8-a301-16e4-b8e9-d0683d89e255', 744861, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>16:00–01:00 the next day</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff1d2d10-35c3-827b-f81b-e90073bfd19d', 744861, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff1d2d10-35c3-827b-f81b-e90073bfd19d', 744861, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a53db35-bec3-24ee-9e19-a12e0991d41c', 744861, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a53db35-bec3-24ee-9e19-a12e0991d41c', 744861, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, extra beds cannot be added. Crib policies vary according to room type. Please refer to the relevant room type policy.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f057eb2d-3563-3f72-8bdf-e2ae745f9b15', 744861, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f057eb2d-3563-3f72-8bdf-e2ae745f9b15', 744861, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Western, Continental</p><p>Opening hours: [Mon - Fri] 06:30-09:00 Open [Sat - Sun] 06:30-09:30 Open</p><table><tr><td>Children 6 years old and under</td><td>Free</td></tr><tr><td>Children 7–11 years old</td><td>DKK 75 (approx. $11.41) per person</td></tr><tr><td>Children 12–17 years old</td><td>DKK 159 (approx. $24.19) per person</td></tr><tr><td>Adult</td><td>DKK 159 (approx. $24.19) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc0ea096-f992-f070-c3d0-34424c921bc3', 744861, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
