INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Scandic Sluseholmen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Molestien 11, 2450 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '215');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, Scandic Sluseholmen cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút lái xe. Khách sạn cách Khu Nyhavn 6 km và cách Cung điện Amalienborg 6,3 km.</p><p>Hãy tận hưởng nhiều dịch vụ, tiện nghi thể thao, giải trí như bồn tắm thủy lực, phòng tắm hơi và trung tâm thể dục phục vụ 24 giờ. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và sảnh tiếp tân.</p><p>Khách có thể dùng bữa tại nhà hàng Elements hay gọi những ly nước từ quầy bar/khu lounge hoặc dùng bữa tối ngoài trời. Ngoài ra, khách cũng có thể nghỉ lại trong phòng và thưởng thức những bữa ăn ngon với dịch vụ phòng (có giới hạn thời gian). Khách có thể dùng bữa sáng buffet các ngày trong tuần từ 6:30 đến 9:30 và cuối tuần (phụ phí) từ 7:00 đến 10:00.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm dịch vụ giặt ủi/giặt khô, quầy tiếp tân phục vụ 24 giờ/ngày và dịch vụ trông giữ/bảo quản hành lý. Có kế hoạch tổ chức sự kiện tại Copenhagen? Khách sạn này có khu vực tổ chức rộng 521 mét vuông, bao gồm khu hội nghị và 20 phòng họp. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ tại một trong 215 phòng được trang bị TV LED. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình vệ tinh sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng có đồ dùng nhà tắm miễn phí và máy sấy tóc. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật và bàn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('69db8e9b-f626-c98c-f229-27aa5f2fecfa', 744861, 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '274637');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80b959d8-a301-16e4-b8e9-d0683d89e255', 744861, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80b959d8-a301-16e4-b8e9-d0683d89e255', 744861, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>16:00 – 01:00 ngày hôm sau</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff1d2d10-35c3-827b-f81b-e90073bfd19d', 744861, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff1d2d10-35c3-827b-f81b-e90073bfd19d', 744861, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a53db35-bec3-24ee-9e19-a12e0991d41c', 744861, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a53db35-bec3-24ee-9e19-a12e0991d41c', 744861, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung giường phụ. Chính sách về cũi khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f057eb2d-3563-3f72-8bdf-e2ae745f9b15', 744861, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f057eb2d-3563-3f72-8bdf-e2ae745f9b15', 744861, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Tây phương, Đại lục</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-09:00 Đang Mở [Thứ 7 - CN] 06:30-09:30 Đang Mở</p><table><tr><td>Trẻ em 6 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 7–11 tuổi</td><td>75 DKK(khoảng 296.489₫) mỗi người</td></tr><tr><td>Trẻ em 12–17 tuổi</td><td>159 DKK(khoảng 628.557₫) mỗi người</td></tr><tr><td>Người lớn</td><td>159 DKK(khoảng 628.557₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc0ea096-f992-f070-c3d0-34424c921bc3', 744861, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc0ea096-f992-f070-c3d0-34424c921bc3', 744861, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Chỗ nghỉ không yêu cầu đặt cọc</strong></p>');
