INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8efa714-ec22-aea7-3d24-e995a70f9766', 744865, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hotel Mayfair');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8efa714-ec22-aea7-3d24-e995a70f9766', 744865, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Colbjørnsensgade 8, Vesterbro/Kongens Enghave, 1652 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8efa714-ec22-aea7-3d24-e995a70f9766', 744865, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8efa714-ec22-aea7-3d24-e995a70f9766', 744865, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '198');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8efa714-ec22-aea7-3d24-e995a70f9766', 744865, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, Hotel Mayfair, cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút đi bộ. Khách sạn cách Ny Carlsberg Glyptotek 1,1 km và cách Phố Strøget 1,5 km.</p><p>Đừng bỏ qua những dịch vụ, tiện nghi thể thao, giải trí tuyệt vời, bao gồm trung tâm thể dục phục vụ 24 giờ và xe đạp cho thuê.</p><p>Khách có thể dùng bữa sáng buffet các ngày trong tuần từ 6:30 đến 10:00 và cuối tuần (phụ phí) từ 7:30 đến 11:00.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm máy vi tính, dịch vụ giặt ủi/giặt khô và quầy tiếp tân phục vụ 24 giờ/ngày.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 203 phòng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Các phòng tắm được trang bị bồn tắm hoặc buồng tắm vòi sen với vòi sen phun mưa và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8efa714-ec22-aea7-3d24-e995a70f9766', 744865, 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '227259');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d90e3559-28c5-4488-0e74-bb6015e90c3e', 744865, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d90e3559-28c5-4488-0e74-bb6015e90c3e', 744865, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 24:00</strong></p><p>Trả phòng: <strong>00:00–11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4f03ea8e-a2df-1f31-0421-d20cd6ff79ee', 744865, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4f03ea8e-a2df-1f31-0421-d20cd6ff79ee', 744865, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('99448f64-72ad-2ebf-52b0-4d71b21323bf', 744865, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('99448f64-72ad-2ebf-52b0-4d71b21323bf', 744865, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung giường phụ. Chính sách về cũi khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9f80a260-2850-930d-93b4-47e921d2cf53', 744865, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9f80a260-2850-930d-93b4-47e921d2cf53', 744865, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Cơ sở lưu trú này có 2 lựa chọn cho suất ăn sáng đặt thêm.</p><p>Ẩm thực: Ẩm thực địa phương</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:00 Đang Mở [Thứ 7 - CN] 07:30-11:00 Đang Mở</p><table><tr><td>Trẻ em 4 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 5–8 tuổi</td><td>95 DKK(khoảng 375.553₫) mỗi người</td></tr><tr><td>Trẻ em 9–17 tuổi</td><td>225 DKK(khoảng 889.468₫) mỗi người</td></tr><tr><td>Người lớn</td><td>225 DKK(khoảng 889.468₫) mỗi người</td></tr></table><p>Ẩm thực: Tây phương</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:00 Đang Mở [Thứ 7 - CN] 07:30-11:00 Đang Mở</p><p>Giá thêm bữa sáng: Phụ thuộc vào món bạn đặt</p><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e390cb64-ed34-4cc2-3a8e-401d3a6ab3a9', 744865, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e390cb64-ed34-4cc2-3a8e-401d3a6ab3a9', 744865, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 1.500 DKK (khoảng 5.929.785₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('96a31409-1853-992b-746a-fa1342e60d42', 744865, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
