INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5bcb83dd-5e08-8040-a456-7fe6cc9e4f3f', 744866, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Comfort Hotel Vesterbro');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5bcb83dd-5e08-8040-a456-7fe6cc9e4f3f', 744866, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Vesterbrogade 23/29, Vesterbro/Kongens Enghave, Copenhagen, Hovedstaden, 1620, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5bcb83dd-5e08-8040-a456-7fe6cc9e4f3f', 744866, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5bcb83dd-5e08-8040-a456-7fe6cc9e4f3f', 744866, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '399');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5bcb83dd-5e08-8040-a456-7fe6cc9e4f3f', 744866, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Comfort Hotel Vesterbro, you''ll be centrally located in Copenhagen, within a 10-minute walk of Tivoli Gardens and City Hall Square. This hotel is 1 mi (1.7 km) from Strøget and 1.2 mi (1.9 km) from Torvehallerne.</p><p>Don''t miss out on recreational opportunities including a fitness center and bicycles to rent. Additional features at this hotel include complimentary wireless internet access, concierge services, and a banquet hall.</p><p>Enjoy a meal at the restaurant or snacks in the hotel''s coffee shop/cafe. Quench your thirst with your favorite drink at the bar/lounge. Buffet breakfasts are available daily from 7:30 AM to 11:00 AM for a fee.</p><p>Featured amenities include express check-in, express check-out, and dry cleaning/laundry services. Planning an event in Copenhagen? This hotel has 775 square feet (72 square meters) of space consisting of conference space and meeting rooms. Self parking (subject to charges) is available onsite.</p><p>Stay in one of 400 guestrooms featuring LCD televisions. Complimentary wireless internet access keeps you connected, and digital programming is available for your entertainment. Bathrooms have showers and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5bcb83dd-5e08-8040-a456-7fe6cc9e4f3f', 744866, 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '232090');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4ef3a4f1-26ab-1964-bc1f-80c889fca6f4', 744866, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4ef3a4f1-26ab-1964-bc1f-80c889fca6f4', 744866, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p><p>If you will arrive outside of check-in hours, contact the property in advance</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('04e6a449-e65b-9c89-3495-5f200e3080b5', 744866, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('04e6a449-e65b-9c89-3495-5f200e3080b5', 744866, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('29667bdd-d9d9-bcf2-d66c-18703a157dd7', 744866, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('29667bdd-d9d9-bcf2-d66c-18703a157dd7', 744866, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, extra beds cannot be added. Crib policies vary according to room type. Please refer to the relevant room type policy.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05fdd019-8890-514f-9b74-df43e29c7943', 744866, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05fdd019-8890-514f-9b74-df43e29c7943', 744866, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:30-11:00 Open</p><table><tr><td>Adult</td><td>DKK 175 (approx. $26.62) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
