INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', '1 hotel Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Krystalgade 22, Indre By, Copenhagen, Hovedstaden, 1172, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '282');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at 1 Hotel Copenhagen, you''ll be centrally located in Copenhagen, steps from Latin Quarter and Church of Our Lady. This luxury hotel is 0.3 mi (0.4 km) from Torvehallerne and 0.7 mi (1.1 km) from Round Tower.</p><p>Relax at the full-service spa, where you can enjoy massages. You can take advantage of recreational amenities such as a 24-hour fitness center and bicycles to rent. Additional features at this hotel include complimentary wireless internet access, concierge services, and gift shops/newsstands.</p><p>Enjoy a meal at Pære Dining Room or snacks in the coffee shop/cafe. The hotel also offers room service (during limited hours). Quench your thirst with your favorite drink at the bar/lounge. Buffet breakfasts are served on weekdays from 6:30 AM to 11:00 AM and on weekends from 7:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include express check-out, dry cleaning/laundry services, and a 24-hour front desk. Planning an event in Copenhagen? This hotel has 3444 square feet (320 square meters) of space consisting of conference space and 4 meeting rooms.</p><p>Make yourself at home in one of the 282 guestrooms featuring minibars and flat-screen televisions. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Bathrooms have complimentary toiletries and hair dryers. Conveniences include phones, as well as safes and desks.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73bf5452-147e-992b-527d-2faeb03a9808', 744872, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73bf5452-147e-992b-527d-2faeb03a9808', 744872, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–23:30</strong></p><p>Check-out: <strong>04:00–12:00</strong></p><p>Front desk hours: 24/7</p><p>If you will arrive outside of check-in hours, contact the property in advance</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95c387e7-85c0-a79b-2fe1-0f8fd60604fb', 744872, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95c387e7-85c0-a79b-2fe1-0f8fd60604fb', 744872, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b6e6ec41-c1a7-b3ef-cd9f-da1f9ab30662', 744872, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b6e6ec41-c1a7-b3ef-cd9f-da1f9ab30662', 744872, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs can be added. Extra bed policies vary according to room type. Please refer to the relevant room type policy.</p><p>Fees for extra beds and cribs are not included in the total and must be paid at the hotel.</p><table><tr><td>Children 2 years old and under</td><td>Extra crib: Free</td></tr></table>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f83b5169-d361-98d8-15d8-0dbc7b8c7735', 744872, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f83b5169-d361-98d8-15d8-0dbc7b8c7735', 744872, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Fri] 06:30-11:00 Open [Sat - Sun] 07:00-11:00 Open</p><table><tr><td>Children 17 years old and under</td><td>DKK 345 (approx. $52.56) per person</td></tr><tr><td>Adult</td><td>DKK 345 (approx. $52.56) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('129520fb-3196-34ef-5d8b-9ea1d62a0846', 744872, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('129520fb-3196-34ef-5d8b-9ea1d62a0846', 744872, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of DKK 2,000 (approx. $304.71) is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment within 7 days after check-out.</strong></p>');
