INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', '1 hotel Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Krystalgade 22, Indre By, 1172 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '282');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b2bcfb7e-9e62-96ca-ba55-36e127af5aac', 744872, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, 1 Hotel Copenhagen cách Khu phố Latin và Nhà thờ Đức Mẹ vài bước. Khách sạn sang trọng này cách Torvehallerne 0,4 km và cách Tháp thiên văn Round Tower 1,1 km.</p><p>Hãy thư giãn tại khu spa phục vụ đầy đủ các liệu pháp, tận hưởng massage. Đừng bỏ qua cơ hội tận hưởng những dịch vụ, tiện nghi thể thao, giải trí như trung tâm thể dục phục vụ 24 giờ và xe đạp cho thuê. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và cửa hàng quà tặng/sạp báo.</p><p>Khách có thể thưởng thức những món ăn ngon tại Pære Dining Room hoặc dùng bữa tại quán cà phê. Khách sạn này còn cung cấp dịch vụ phòng (có giới hạn thời gian). Đập tan cơn khát với đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet các ngày trong tuần từ 6:30 đến 11:00 và cuối tuần (phụ phí) từ 7:00 đến 11:00.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trả phòng nhanh, dịch vụ giặt ủi/giặt khô và quầy tiếp tân phục vụ 24 giờ/ngày. Có kế hoạch tổ chức sự kiện tại Copenhagen? Khách sạn này có khu vực tổ chức rộng 320 mét vuông, bao gồm khu hội nghị và 4 phòng họp.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 282 phòng được trang bị minibar và TV màn hình phẳng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm có đồ dùng nhà tắm miễn phí và máy sấy tóc. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật và bàn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73bf5452-147e-992b-527d-2faeb03a9808', 744872, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73bf5452-147e-992b-527d-2faeb03a9808', 744872, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 23:30</strong></p><p>Trả phòng: <strong>04:00–12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95c387e7-85c0-a79b-2fe1-0f8fd60604fb', 744872, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95c387e7-85c0-a79b-2fe1-0f8fd60604fb', 744872, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b6e6ec41-c1a7-b3ef-cd9f-da1f9ab30662', 744872, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b6e6ec41-c1a7-b3ef-cd9f-da1f9ab30662', 744872, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều có thể bổ sung cũi. Chính sách về giường phụ khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</p><p>Phí giường phụ và cũi chưa được bao gồm trong tổng giá và phải được thanh toán tại khách sạn.</p><table><tr><td>Trẻ em 2 tuổi trở xuống</td><td>Thêm cũi: Miễn phí</td></tr></table>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f83b5169-d361-98d8-15d8-0dbc7b8c7735', 744872, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f83b5169-d361-98d8-15d8-0dbc7b8c7735', 744872, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-11:00 Đang Mở [Thứ 7 - CN] 07:00-11:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>345 DKK(khoảng 1.364.411₫) mỗi người</td></tr><tr><td>Người lớn</td><td>345 DKK(khoảng 1.364.411₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('129520fb-3196-34ef-5d8b-9ea1d62a0846', 744872, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('129520fb-3196-34ef-5d8b-9ea1d62a0846', 744872, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 2.000 DKK (khoảng 7.909.629₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('16fdd7ac-bee2-a57e-f11d-91b0b731e373', 744872, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('16fdd7ac-bee2-a57e-f11d-91b0b731e373', 744872, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó</p>');
