INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', 'Manon Les Suites');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Gyldenløvesgade 19, Indre By, Copenhagen, Hovedstaden, 1600, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '87');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located in Copenhagen (Copenhagen City Centre), Manon Les Suites Guldsmeden is within a 10-minute walk of Tivoli Gardens and City Hall Square. This luxury aparthotel is 0.5 mi (0.8 km) from Strøget and 1.8 mi (2.8 km) from Nyhavn.</p><p>Enjoy a range of recreational amenities, including an indoor pool, a steam room, and a fitness center. This aparthotel also features complimentary wireless internet access and concierge services.</p><p>Satisfy your appetite at Chapung, a restaurant which features a bar/lounge. Dining is also available at the coffee shop/cafe. Quench your thirst with your favorite drink at the poolside bar. Buffet breakfasts are available daily from 7:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include dry cleaning/laundry services, a 24-hour front desk, and multilingual staff.</p><p>Make yourself at home in one of the 87 air-conditioned rooms featuring refrigerators and LCD televisions. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Private bathrooms with showers feature designer toiletries and hair dryers. Conveniences include phones, as well as safes and separate sitting areas.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f51ac157-d590-5b6b-e3e9-fa27ab55cbf2', 744878, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f51ac157-d590-5b6b-e3e9-fa27ab55cbf2', 744878, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>00:30–12:00</strong></p><p>Front desk hours: 24/7</p><p>The host or staff will greet you upon arrival</p><p>The property will provide check-in details after booking</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('96eff426-a209-19de-7dee-c4693cd96123', 744878, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('96eff426-a209-19de-7dee-c4693cd96123', 744878, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children aged 15 and above are welcome at this hotel.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f2d366de-7cf3-e9b4-e155-4372c56f8019', 744878, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
