INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ce4a4fcc-f177-2068-e270-ad7dd872af49', 744878, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ce4a4fcc-f177-2068-e270-ad7dd872af49', 744878, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Fri] 07:00-11:00 Open [Sat - Sun] 08:00-12:00 Open</p><table><tr><td>Children 15–17 years old</td><td>DKK 295 (approx. $44.94) per person</td></tr><tr><td>Adult</td><td>DKK 295 (approx. $44.94) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
