INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Manon Les Suites Guldsmeden');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', 'Manon Les Suites');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Gyldenløvesgade 19, Indre By, 1600 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '87');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cb7401c3-28fb-1a31-ef84-33deb670abad', 744878, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Manon Les Suites Guldsmeden ở Trung tâm Copenhagen, Copenhagen, cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút đi bộ. Khách sạn căn hộ sang trọng này cách Phố Strøget 0,8 km và cách Khu Nyhavn 2,6 km.</p><p>Hãy tận hưởng nhiều dịch vụ, tiện nghi thể thao, giải trí như hồ bơi trong nhà, phòng xông hơi và trung tâm thể dục. Khách sạn căn hộ này còn có quyền truy cập Internet không dây miễn phí và dịch vụ tư vấn/hỗ trợ khách.</p><p>Thưởng thức những bữa ăn ngon tại nhà hàng Chapung có quầy bar/khu lounge. Hoặc khách cũng có thể chọn dùng bữa tại quán cà phê. Đập tan cơn khát với đồ uống yêu thích tại quầy bar bên hồ bơi. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:00 đến 11:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm dịch vụ giặt ủi/giặt khô, quầy tiếp tân phục vụ 24 giờ/ngày và nhân viên thông thạo nhiều ngôn ngữ.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 87 phòng được trang bị máy điều hòa cùng tủ lạnh và TV LCD. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng với buồng tắm vòi sen có đồ dùng nhà tắm được thiết kế riêng và máy sấy tóc. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật và khu tiếp khách tách biệt.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f51ac157-d590-5b6b-e3e9-fa27ab55cbf2', 744878, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f51ac157-d590-5b6b-e3e9-fa27ab55cbf2', 744878, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>00:30–12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('96eff426-a209-19de-7dee-c4693cd96123', 744878, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('96eff426-a209-19de-7dee-c4693cd96123', 744878, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em 15 tuổi trở lên được chào đón tại khách sạn này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f2d366de-7cf3-e9b4-e155-4372c56f8019', 744878, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f2d366de-7cf3-e9b4-e155-4372c56f8019', 744878, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ce4a4fcc-f177-2068-e270-ad7dd872af49', 744878, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ce4a4fcc-f177-2068-e270-ad7dd872af49', 744878, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 07:00-11:00 Đang Mở [Thứ 7 - CN] 08:00-12:00 Đang Mở</p><table><tr><td>Trẻ em 15–17 tuổi</td><td>295 DKK(khoảng 1.166.670₫) mỗi người</td></tr><tr><td>Người lớn</td><td>295 DKK(khoảng 1.166.670₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('41d80728-2f8e-37e2-fa4f-08a00e9de68d', 744878, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('41d80728-2f8e-37e2-fa4f-08a00e9de68d', 744878, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 1.000 DKK (khoảng 3.954.814₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Vào ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b429653d-3ec4-dad8-aed1-77db579ada96', 744878, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b429653d-3ec4-dad8-aed1-77db579ada96', 744878, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: 250 DKK (khoảng 988.704₫)/thú cưng/lần lưu trú</p>');
