INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Generator Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Adelgade 5, 7, Indre By, Copenhagen, Hovedstaden, 1304, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '175');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Generator Copenhagen , you''ll be centrally located in Copenhagen, just a 4-minute walk from Strøget and 6 minutes by foot from Nyhavn. This hostel is 1.3 mi (2.1 km) from Tivoli Gardens and 1.2 mi (1.9 km) from City Hall Square.</p><p>Take advantage of recreation opportunities including a nightclub and bicycles to rent. This hostel also features complimentary wireless internet access, concierge services, and a television in a common area.</p><p>Enjoy a meal at Generator Coffee Shop or snacks in the hostel''s coffee shop/cafe. Need to unwind? Take a break with a tasty beverage at one of the 2 bars/lounges. To-go breakfasts are served on weekdays from 7:00 AM to 10:00 AM for a fee.</p><p>Featured amenities include a computer station, express check-in, and express check-out.</p><p>Make yourself at home in one of the 175 guestrooms. Complimentary wireless internet access is available to keep you connected. Bathrooms have showers and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('daee4b82-6ee0-bcb8-8b36-1174a0af6540', 744882, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('daee4b82-6ee0-bcb8-8b36-1174a0af6540', 744882, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 10:00</strong></p><p>Front desk hours: 24/7</p><p>The property will provide check-in details after booking</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27f8d6ed-0c45-dc75-66ec-3c98b92dc8d4', 744882, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
