INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Generator Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Adelgade 5, 7, Indre By, 1304 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '175');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b084ba8-ee9a-7143-97e1-0cc2cee43d55', 744882, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Generator Copenhagen ở trung tâm Copenhagen, chỉ cách Phố Strøget 4 phút đi bộ và cách Khu Nyhavn 6 phút đi bộ. Hostel này cách Công viên Tivoli 2,1 km và cách Quảng trường Tòa thị chính 1,9 km.</p><p>Hãy tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm hộp đêm và xe đạp cho thuê. Hostel này còn có quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và TV ở khu vực chung.</p><p>Khách có thể thưởng thức những bữa ăn ngon tại Generator Coffee Shop hoặc dùng bữa nhẹ ở quán cà phê của Hostel. Đập tan cơn khát với đồ uống yêu thích của mình tại 2 quầy bar/khu lounge. Khách có thể dùng bữa sáng mang đi (có phụ phí) từ 7:00 đến 10:00 vào các ngày trong tuần.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm máy vi tính, nhận phòng nhanh và trả phòng nhanh.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 175 phòng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Các phòng tắm được trang bị buồng tắm vòi sen và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('daee4b82-6ee0-bcb8-8b36-1174a0af6540', 744882, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('daee4b82-6ee0-bcb8-8b36-1174a0af6540', 744882, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 10:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27f8d6ed-0c45-dc75-66ec-3c98b92dc8d4', 744882, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27f8d6ed-0c45-dc75-66ec-3c98b92dc8d4', 744882, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Cơ sở lưu trú này không nhận khách lưu trú là trẻ em</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2ddc5e78-5463-2909-4fcf-927e3a7bac39', 744882, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2ddc5e78-5463-2909-4fcf-927e3a7bac39', 744882, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc4fe16d-a861-794f-22a7-b391e97d39c1', 744882, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc4fe16d-a861-794f-22a7-b391e97d39c1', 744882, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Ẩm thực: Chay</p><table><tr><td>Người lớn</td><td>Liên hệ khách sạn</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c28e7ba2-ce17-86bc-af39-be85aa563d30', 744882, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c28e7ba2-ce17-86bc-af39-be85aa563d30', 744882, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: 185 DKK (khoảng 731.641₫)/thú cưng/lần lưu trú</p>');
