INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hotel Dada Gyeongbokgung');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '다다호텔 경복궁');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '33, Samil-daero 32ga-gil, Jongno-gu, Seoul, 03132, South Korea');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '35');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Please note that breakfast is only available for reservations made before August 4, 2025. Breakfast is not available for reservations made after August 5.</p><p>In the heart of Seoul, Hotel Dada Insadong is within a 5-minute drive of Gwanghwamun and Gyeongbokgung Palace. This guesthouse is 0.8 mi (1.3 km) from Bukchon Hanok Village and 1.2 mi (1.9 km) from Myeongdong Street.</p><p>Take in the views from a rooftop terrace and a garden and make use of amenities such as complimentary wireless internet access. Additional amenities at this guesthouse include tour/ticket assistance and a vending machine.</p><p>Featured amenities include express check-in, express check-out, and a 24-hour front desk.</p><p>Make yourself at home in one of the 37 air-conditioned rooms featuring refrigerators and flat-screen televisions. Complimentary wireless internet access keeps you connected, and satellite programming is available for your entertainment. Private bathrooms with showers feature complimentary toiletries and hair dryers. Conveniences include desks and complimentary bottled water, and housekeeping is provided on request.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc303b94-9ea1-0210-48c6-7cc1d85850f2', 989214, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc303b94-9ea1-0210-48c6-7cc1d85850f2', 989214, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Self check-in: Contact the property for the access code</p><p>The property will provide check-in details after booking</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c3e8b794-6ef0-3ddf-a456-4ac879b81779', 989214, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c3e8b794-6ef0-3ddf-a456-4ac879b81779', 989214, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5887ee77-8566-59c4-60b4-df12215a0623', 989214, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
