INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hotel Dada Gyeongbokgung');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '다다호텔 경복궁');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '33, Samil-daero 32ga-gil, Jongno-gu, 03132 Seoul, Hàn Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '35');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38283a1c-85b6-864f-6bac-f5d5220ef808', 989214, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Seoul, Hotel Dada Gyeongbokgung cách Gwanghwamun và Làng Bukchon Hanok 5 phút lái xe. Nhà khách cách Khu mua sắm Myeongdong Street 1,9 km và cách Cung điện Gyeongbokgung 2 km.</p><p>Hãy thư thả ngắm cảnh từ sân thượng hay vườn; và tận hưởng những dịch vụ, tiện ích như quyền truy cập Internet không dây miễn phí. Những dịch vụ, tiện ích khác tại Nhà khách này bao gồm dịch vụ hỗ trợ tour/vé du lịch và máy bán hàng tự động.</p><p>Khách có thể dùng bữa tại quán cà phê của Nhà khách.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm nhận phòng nhanh, trả phòng nhanh và dịch vụ giặt ủi/giặt khô.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 37 phòng được trang bị máy điều hòa cùng tủ lạnh và TV màn hình phẳng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình vệ tinh sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng với buồng tắm vòi sen có đồ dùng nhà tắm miễn phí và máy sấy tóc. Tiện nghi phòng bao gồm bàn và nước đóng chai miễn phí; bên cạnh đó dịch vụ dọn phòng cũng phục vụ dịch vụ dọn phòng (theo yêu cầu).</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc303b94-9ea1-0210-48c6-7cc1d85850f2', 989214, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc303b94-9ea1-0210-48c6-7cc1d85850f2', 989214, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Tự nhận phòng: Liên lạc với chỗ nghỉ để biết mã vào phòng</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c3e8b794-6ef0-3ddf-a456-4ac879b81779', 989214, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c3e8b794-6ef0-3ddf-a456-4ac879b81779', 989214, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5887ee77-8566-59c4-60b4-df12215a0623', 989214, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5887ee77-8566-59c4-60b4-df12215a0623', 989214, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20cfab90-08eb-56f4-f9a2-2089d1a21f87', 989214, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
