INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'AC Hotel Bella Sky Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Martha Christensens Vej 5, Amager Vest, Copenhagen, Hovedstaden, 2300, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '811');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Experience 4-star sophistication in Denmark''s capital city with the beautifully designed accommodations and deluxe amenities at AC Hotel Bella Sky Copenhagen. Boasting a location near the airport and the vibrant city center, our pet-friendly hotel in Copenhagen is steps away from the train station, which allows for easy exploration of local attractions, including Tivoli Gardens and Amager Common. Unpack your bags in modern hotel rooms with pillow top bedding, floor-to-ceiling windows and authentic Danish design. Then explore our hotel''s luxurious amenities, including a fitness center and delicious restaurants. Start your day with the hot breakfast buffet and savor locally-sourced fare for lunch or dinner. If visiting Copenhagen for business, plan your next successful event in the adjacent Bella Center and tackle projects with our hotel''s complimentary Wi-Fi, parking and onsite business center. We are ready to make your visit memorable at our hotel in downtown Copenhagen.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '1986559');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('66acda38-84ea-52ec-4fae-47f08c076a49', 1863116, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('66acda38-84ea-52ec-4fae-47f08c076a49', 1863116, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–24:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7b4d9dde-30fa-0346-763e-4386a4373eba', 1863116, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7b4d9dde-30fa-0346-763e-4386a4373eba', 1863116, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
