INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('676960ce-13b0-58b9-80d3-e1012859e81d', 1863116, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Continental</p><p>Opening hours: [Mon - Fri] 06:30-10:30 Open [Sat - Sun] 06:30-11:00 Open</p><table><tr><td>Children 3 years old and under</td><td>Free</td></tr><tr><td>Children 4–17 years old</td><td>DKK 125 (approx. $19.01) per person</td></tr><tr><td>Adult</td><td>DKK 195 (approx. $29.66) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27f841b0-5cd3-d999-4f5e-6b0c1635a0cc', 1863116, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
