INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'AC Hotel Bella Sky Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Martha Christensens Vej 5, Amager Vest, 2300 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '811');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, AC Hotel by Marriott Bella Sky Copenhagen cách Sân vận động Royal 3 phút lái xe và cách Phố Strøget 7 phút lái xe. Khách sạn golf này cách Quảng trường Tòa thị chính 5,5 km và cách Công viên Tivoli 5,6 km.</p><p>Hãy tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm trung tâm thể dục và xe đạp cho thuê. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và cửa hàng quà tặng/sạp báo.</p><p>Thưởng thức những bữa ăn ngon tại BM Breakfast Restaurant, một trong 3 nhà hàng của Khách sạn. Thư giãn sau một ngày dài bên cạnh ly đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 6:30 đến 10:30 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng phục vụ 24 giờ, trả phòng nhanh và dịch vụ giặt ủi/giặt khô. Khu vực phục vụ hội thảo, sự kiện tại Khách sạn này bao gồm trung tâm hội nghị và phòng họp. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 811 phòng được trang bị minibar và TV LCD. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm thiết kế mở với bồn tắm hoặc buồng tắm vòi sen có đồ dùng nhà tắm miễn phí và máy sấy tóc. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật và bàn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20494e5a-9afe-d640-6670-f4bb422dfb0e', 1863116, 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '1986559');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('66acda38-84ea-52ec-4fae-47f08c076a49', 1863116, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('66acda38-84ea-52ec-4fae-47f08c076a49', 1863116, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 24:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7b4d9dde-30fa-0346-763e-4386a4373eba', 1863116, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7b4d9dde-30fa-0346-763e-4386a4373eba', 1863116, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c9107a6d-37b3-fa3f-b836-df7bba06d5ac', 1863116, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c9107a6d-37b3-fa3f-b836-df7bba06d5ac', 1863116, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('676960ce-13b0-58b9-80d3-e1012859e81d', 1863116, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('676960ce-13b0-58b9-80d3-e1012859e81d', 1863116, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Đại lục</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:30 Đang Mở [Thứ 7 - CN] 06:30-11:00 Đang Mở</p><table><tr><td>Trẻ em 3 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 4–17 tuổi</td><td>125 DKK(khoảng 494.149₫) mỗi người</td></tr><tr><td>Người lớn</td><td>195 DKK(khoảng 770.872₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27f841b0-5cd3-d999-4f5e-6b0c1635a0cc', 1863116, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27f841b0-5cd3-d999-4f5e-6b0c1635a0cc', 1863116, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 250 DKK (khoảng 988.298₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8e0edb37-80f2-8657-4442-29b8bed67358', 1863116, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8e0edb37-80f2-8657-4442-29b8bed67358', 1863116, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó, mèo</p><p>Phí: 300 DKK (khoảng 1.185.957₫)/phòng/ngày</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e1b00699-e190-c438-be37-2cbc670fd26a', 1863116, 'POLICY', 'serviceAnimal', 'vi', 'policy_title', 'Động vật hỗ trợ');
