INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7ac9f258-8884-784a-04ed-194a41b1aafd', 1960954, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Prestige Inn');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7ac9f258-8884-784a-04ed-194a41b1aafd', 1960954, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '6630 Hoover St, 77092 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7ac9f258-8884-784a-04ed-194a41b1aafd', 1960954, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '32');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7ac9f258-8884-784a-04ed-194a41b1aafd', 1960954, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Prestige Inn ở trung tâm Houston, chỉ cách Trung tâm mua sắm Memorial City và Đường Westheimer 15 phút lái xe. Motel này cách Công viên Daikin 19,5 km và cách Đại học Rice 19,9 km.</p><p>Motel này gồm 2 tầng nằm trong 2 tòa nhà và có khu vực hút thuốc riêng.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm quầy tiếp tân phục vụ 24 giờ/ngày, nhân viên thông thạo nhiều ngôn ngữ và dịch vụ trông giữ/bảo quản hành lý.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 32 phòng được trang bị máy điều hòa cùng tủ lạnh và TV LED. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm được trang bị vòi sen/bồn tắm kết hợp và đồ dùng nhà tắm miễn phí. Tiện nghi phòng bao gồm bàn và lò vi sóng; bên cạnh đó dịch vụ dọn phòng cũng phục vụ dịch vụ dọn phòng (theo yêu cầu).</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e83b8b35-2969-9ab6-3412-71757e8b215b', 1960954, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e83b8b35-2969-9ab6-3412-71757e8b215b', 1960954, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 05:30 ngày hôm sau</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6e54180e-df70-f980-9f6f-6bbe8ade0930', 1960954, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6e54180e-df70-f980-9f6f-6bbe8ade0930', 1960954, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('41ffa10c-24f9-fc4d-c258-bfec6c15dcad', 1960954, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('41ffa10c-24f9-fc4d-c258-bfec6c15dcad', 1960954, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a4fc1927-e042-3d2c-b496-28d18b438da8', 1960954, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
