INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('601a4352-3e82-0f86-d21f-edcc3c0cb26a', 2139235, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Cabinn City');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('601a4352-3e82-0f86-d21f-edcc3c0cb26a', 2139235, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', 'CABINN City Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('601a4352-3e82-0f86-d21f-edcc3c0cb26a', 2139235, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Mitchellsgade 14, Copenhagen, Hovedstaden, 1568, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('601a4352-3e82-0f86-d21f-edcc3c0cb26a', 2139235, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('601a4352-3e82-0f86-d21f-edcc3c0cb26a', 2139235, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '300');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('601a4352-3e82-0f86-d21f-edcc3c0cb26a', 2139235, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at CABINN City Hotel, you''ll be centrally located in Copenhagen, within a 10-minute walk of Tivoli Gardens and City Hall Square. This hotel is 0.6 mi (0.9 km) from Strøget and 1.4 mi (2.3 km) from Nyhavn.</p><p>Enjoy recreation amenities such as bicycles to rent or take in the view from a terrace. Additional features at this hotel include complimentary wireless internet access and a television in a common area.</p><p>Grab a bite from the snack bar/deli serving guests of CABINN City Hotel. Quench your thirst with your favorite drink at the bar/lounge. Buffet breakfasts are served on weekends from 7:30 AM to 10:30 AM for a fee. Children aged 3 and younger eat free breakfast.</p><p>Featured amenities include a 24-hour front desk, luggage storage, and ATM/banking services. Self parking (subject to charges) is available onsite.</p><p>Make yourself at home in one of the 352 guestrooms. Complimentary wireless internet access keeps you connected, and satellite programming is available for your entertainment. Bathrooms with showers are provided. Conveniences include desks and coffee/tea makers, and housekeeping is provided weekly.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('805b8991-271c-4f8d-d4de-b5d536a8a32b', 2139235, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('805b8991-271c-4f8d-d4de-b5d536a8a32b', 2139235, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–23:30</strong></p><p>Check-out: <strong>08:00–11:00</strong></p><p>Front desk hours: 24/7</p><p>If you will arrive outside of check-in hours, contact the property in advance</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('229d2f65-6a88-67fb-8af4-e6865c38ca6f', 2139235, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('229d2f65-6a88-67fb-8af4-e6865c38ca6f', 2139235, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('09ba5191-dfbd-5b59-9f6d-4fa867718b43', 2139235, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('09ba5191-dfbd-5b59-9f6d-4fa867718b43', 2139235, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('59d97b37-34f3-f3cf-b29a-4714c31c4ea8', 2139235, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('59d97b37-34f3-f3cf-b29a-4714c31c4ea8', 2139235, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Continental</p><p>Opening hours: [Mon - Sun] 07:00-10:00 Open</p><table><tr><td>Children 17 years old and under</td><td>DKK 125 (approx. $19.04) per person</td></tr><tr><td>Adult</td><td>DKK 125 (approx. $19.04) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
