INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('601a4352-3e82-0f86-d21f-edcc3c0cb26a', 2139235, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, CABINN City Hotel, cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút đi bộ. Khách sạn cách Phố Strøget 0,9 km và cách Khu Nyhavn 2,3 km.</p><p>Hãy tận hưởng những tiện nghi, dịch vụ thư giãn như xe đạp cho thuê hay chỉ đơn giản là ngắm cảnh từ sân thượng/sân hiên. Những dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí và TV ở khu vực chung.</p><p>Khách có thể tìm thấy nhiều quà vặt và món ăn nhẹ tại tiệm/cửa hàng đồ ăn nhanh của CABINN City Hotel. Đập tan cơn khát với đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:30 đến 10:30 vào ngày cuối tuần. LOCALIZE</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm quầy tiếp tân phục vụ 24 giờ/ngày, dịch vụ trông giữ/bảo quản hành lý và dịch vụ ATM/ngân hàng. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 352 phòng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình vệ tinh sẽ mang đến những phút giây giải trí thoải mái. Các phòng có phòng tắm với buồng tắm vòi sen. Tiện nghi phòng bao gồm bàn và dụng cụ pha cà phê/trà; bên cạnh đó dịch vụ dọn phòng cũng phục vụ hàng tuần.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('805b8991-271c-4f8d-d4de-b5d536a8a32b', 2139235, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('805b8991-271c-4f8d-d4de-b5d536a8a32b', 2139235, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 23:30</strong></p><p>Trả phòng: <strong>08:00–11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('229d2f65-6a88-67fb-8af4-e6865c38ca6f', 2139235, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('229d2f65-6a88-67fb-8af4-e6865c38ca6f', 2139235, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('09ba5191-dfbd-5b59-9f6d-4fa867718b43', 2139235, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('09ba5191-dfbd-5b59-9f6d-4fa867718b43', 2139235, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('59d97b37-34f3-f3cf-b29a-4714c31c4ea8', 2139235, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('59d97b37-34f3-f3cf-b29a-4714c31c4ea8', 2139235, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Đại lục</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>125 DKK(khoảng 494.352₫) mỗi người</td></tr><tr><td>Người lớn</td><td>125 DKK(khoảng 494.352₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('61f912c2-fd1b-06d9-05ee-b76f3c7b4225', 2139235, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('61f912c2-fd1b-06d9-05ee-b76f3c7b4225', 2139235, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Chỗ nghỉ không yêu cầu đặt cọc</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('133eb113-cc36-4ced-773a-56b706acd528', 2139235, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
