INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4fea3cf-80b3-7088-06a0-72b013fd3f47', 2157246, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hotel Sanders');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4fea3cf-80b3-7088-06a0-72b013fd3f47', 2157246, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Tordenskjoldsgade 15, Indre By, Copenhagen, Hovedstaden, 1055, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4fea3cf-80b3-7088-06a0-72b013fd3f47', 2157246, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4fea3cf-80b3-7088-06a0-72b013fd3f47', 2157246, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '54');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4fea3cf-80b3-7088-06a0-72b013fd3f47', 2157246, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Hotel Sanders, you''ll be centrally located in Copenhagen, within a 5-minute walk of Nyhavn and Strøget. This luxury hotel is 1.3 mi (2.1 km) from Tivoli Gardens and 1.1 mi (1.7 km) from City Hall Square.</p><p>Enjoy recreation amenities such as bicycles to rent or take in the view from a rooftop terrace. Additional amenities at this hotel include complimentary wireless internet access, concierge services, and discounted use of a nearby fitness facility.</p><p>Enjoy a meal at the restaurant, or stay in and take advantage of the hotel''s room service (during limited hours). Quench your thirst with your favorite drink at the bar/lounge. Buffet breakfasts are available daily from 7:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include complimentary wired internet access, a business center, and dry cleaning/laundry services.</p><p>Make yourself at home in one of the 55 guestrooms featuring minibars and espresso makers. Your bed comes with down comforters and premium bedding. Wired and wireless internet access is complimentary, and flat-screen televisions with cable programming provide entertainment. Bathrooms feature showers, complimentary toiletries, and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7be735ee-97d1-08e3-85d0-26d230a9fee6', 2157246, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7be735ee-97d1-08e3-85d0-26d230a9fee6', 2157246, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('612c1fd3-fc26-321e-04c5-68d1e71e4aaa', 2157246, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('612c1fd3-fc26-321e-04c5-68d1e71e4aaa', 2157246, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c37e79de-f1be-0bca-1026-1869da1cffc3', 2157246, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c37e79de-f1be-0bca-1026-1869da1cffc3', 2157246, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('719af9a6-03f7-c6b5-b514-7a1f7c0c555d', 2157246, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('719af9a6-03f7-c6b5-b514-7a1f7c0c555d', 2157246, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:00-11:00 Open</p><table><tr><td>Children 17 years old and under</td><td>DKK 213 (approx. $32.45) per person</td></tr><tr><td>Adult</td><td>DKK 425 (approx. $64.75) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
