INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4fea3cf-80b3-7088-06a0-72b013fd3f47', 2157246, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Hotel Sanders ở trung tâm Copenhagen, cách Khu Nyhavn và Phố Strøget 5 phút đi bộ. Khách sạn sang trọng này cách Công viên Tivoli 2,1 km và cách Quảng trường Tòa thị chính 1,7 km.</p><p>Hãy tận hưởng những tiện nghi, dịch vụ thư giãn như xe đạp cho thuê hay chỉ đơn giản là ngắm cảnh từ sân thượng. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và quyền sử dụng phòng tập thể dục lân cận với giá ưu đãi.</p><p>Khách có thể lựa chọn dùng bữa tại nhà hàng của Khách sạn hoặc nghỉ lại trong phòng và thưởng thức những món ăn ngon với dịch vụ phòng (có giới hạn thời gian). Đập tan cơn khát với đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:00 đến 11:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm truy cập Internet tốc độ cao (có dây) miễn phí, trung tâm dịch vụ văn phòng và dịch vụ giặt ủi/giặt khô.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 55 phòng được trang bị minibar và dụng cụ pha espresso. Giường được trang bị chăn bông và bộ đồ giường cao cấp. Khách có thể truy cập internet có dây hoặc không dây miễn phí và giải trí cùng TV màn hình phẳng với các chương trình truyền hình cáp. Các phòng tắm được trang bị buồng tắm vòi sen, đồ dùng nhà tắm miễn phí và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7be735ee-97d1-08e3-85d0-26d230a9fee6', 2157246, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7be735ee-97d1-08e3-85d0-26d230a9fee6', 2157246, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('612c1fd3-fc26-321e-04c5-68d1e71e4aaa', 2157246, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('612c1fd3-fc26-321e-04c5-68d1e71e4aaa', 2157246, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c37e79de-f1be-0bca-1026-1869da1cffc3', 2157246, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c37e79de-f1be-0bca-1026-1869da1cffc3', 2157246, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('719af9a6-03f7-c6b5-b514-7a1f7c0c555d', 2157246, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('719af9a6-03f7-c6b5-b514-7a1f7c0c555d', 2157246, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-11:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>213 DKK(khoảng 842.375₫) mỗi người</td></tr><tr><td>Người lớn</td><td>425 DKK(khoảng 1.680.796₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a17b592d-d7f6-d910-97b3-63c4e51dbaea', 2157246, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a17b592d-d7f6-d910-97b3-63c4e51dbaea', 2157246, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Chỗ nghỉ không yêu cầu đặt cọc</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5fcf6916-a64a-8cac-28ab-af19eb4d1c2c', 2157246, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5fcf6916-a64a-8cac-28ab-af19eb4d1c2c', 2157246, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Không được phép mang theo thú cưng</p>');
