INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('adc40215-8cfc-4151-0f23-3e1b58be231a', 2159295, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('adc40215-8cfc-4151-0f23-3e1b58be231a', 2159295, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '366');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('adc40215-8cfc-4151-0f23-3e1b58be231a', 2159295, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Historic waterfront hotel in central Copenhagen near Nyhavn and top attractions. Offers 366 renovated rooms- meeting facilities- sauna- bar- and outdoor cafe. In 2025- the newly renovated ground floor opened- featuring a new breakfast area and the vibrant restaurant aye aye. Ideal for business and leisure stays.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('adc40215-8cfc-4151-0f23-3e1b58be231a', 2159295, 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '229647');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bd5f7c84-809f-a599-0d49-a5f811e43e10', 2159295, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bd5f7c84-809f-a599-0d49-a5f811e43e10', 2159295, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>14:00–02:00 the next day</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc36c050-c18b-fe45-7fbd-89277406dc7f', 2159295, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc36c050-c18b-fe45-7fbd-89277406dc7f', 2159295, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('de86ccb1-7fc3-ab02-4149-15bc1c01fb5e', 2159295, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('de86ccb1-7fc3-ab02-4149-15bc1c01fb5e', 2159295, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('104faa94-54e6-1221-107d-8f450819a8fb', 2159295, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('104faa94-54e6-1221-107d-8f450819a8fb', 2159295, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:00-11:00 Open</p><table><tr><td>Children 2 years old and under</td><td>Free</td></tr><tr><td>Children 3–12 years old</td><td>DKK 130 (approx. $19.78) per person</td></tr><tr><td>Children 13–17 years old</td><td>DKK 260 (approx. $39.55) per person</td></tr><tr><td>Adult</td><td>DKK 260 (approx. $39.55) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4dcc2236-1221-6ce3-137e-44e6d4fd2cc5', 2159295, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4dcc2236-1221-6ce3-137e-44e6d4fd2cc5', 2159295, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>The deposit is determined based on the number of rooms you book. The charge is DKK 1,000 (approx. $152.12) per room.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards and cash</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment on the day of check-out.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fb36aba0-4cb5-28ad-b852-0ad55b6e3c53', 2159295, 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
