INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4985599f-8458-268a-84eb-54d0d1a3d54b', 2192931, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'JW Marriott Houston by the Galleria');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4985599f-8458-268a-84eb-54d0d1a3d54b', 2192931, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '5150 Westheimer Rd, Houston, Texas, 77056');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4985599f-8458-268a-84eb-54d0d1a3d54b', 2192931, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '11');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4985599f-8458-268a-84eb-54d0d1a3d54b', 2192931, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Welcome to the completely renovated JW Marriott Houston by The Galleria. Situated across from the Galleria mall, our hotel in Uptown Houston allows guests easy access to shopping and dining experiences. For those traveling with family, our Houston, TX Galleria hotel is conveniently located near the Houston Zoo and Downtown Aquarium. Our on-site restaurant, Stray Horse, is open for breakfast, lunch, and dinner and features elevated cuisine with regional flavors. Visit JW Market for coffee and grab-and-go options. Stay on track with your fitness goals in our spacious fitness center and yoga room. Enjoy the fresh air at our rooftop pool overlooking the city or enhance your experience with a private pool cabana. Our 41,500 sq. ft. of renovated space offers memorable settings where events can thrive. Throughout your stay at our luxury hotel in Houston let us treat you to seamless service and an enriching experience. End your evening in a renovated suite with stylish furnishings, luxury bedding, and city views.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12666cb1-4468-e5cb-1721-fb13a0583c28', 2192931, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12666cb1-4468-e5cb-1721-fb13a0583c28', 2192931, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6b376460-4f6a-f52d-c799-404f1f67688e', 2192931, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6b376460-4f6a-f52d-c799-404f1f67688e', 2192931, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
