INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4985599f-8458-268a-84eb-54d0d1a3d54b', 2192931, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'JW Marriott Houston by the Galleria');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4985599f-8458-268a-84eb-54d0d1a3d54b', 2192931, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '5150 Westheimer Rd, 77056 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4985599f-8458-268a-84eb-54d0d1a3d54b', 2192931, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '11');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4985599f-8458-268a-84eb-54d0d1a3d54b', 2192931, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Khi lưu trú tại JW Marriott Houston by the Galleria, bạn sẽ sẵn sàng thư giãn sau một ngày du lịch.</p><p>Trong thời gian rảnh rỗi, hãy đi bơi trong ngoài trời hoặc trong nhà bể bơi. Để sạc lại pin hoặc đơn giản là thư giãn, hãy truy cập spa của nơi lưu trú. Hãy duy trì chế độ tập thể dục của bạn bằng cách ghé thăm phòng gym. Có rất nhiều hoạt động để thực hiện, bao gồm sân tennis, sân golf và đi bộ đường dài.</p><p>Cơ sở lưu trú này có nhà hàng. Thưởng thức bữa ăn thoải mái ngay tại phòng của bạn với dịch vụ phòng từ nhà hàng trong khuôn viên. Trong thời gian rảnh rỗi, hãy nhâm nhi đồ uống tại bar hoặc nâng cao giác quan của bạn với cà phê tại cà phê.</p><p>Thuộc tính này cũng cung cấp đổi tiền, nơi chứa hành lý, giặt khô và dịch vụ giặt là (tại chỗ nghỉ).</p><p>Chỗ đỗ xe có sẵn tại chỗ nghỉ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12666cb1-4468-e5cb-1721-fb13a0583c28', 2192931, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12666cb1-4468-e5cb-1721-fb13a0583c28', 2192931, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6b376460-4f6a-f52d-c799-404f1f67688e', 2192931, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6b376460-4f6a-f52d-c799-404f1f67688e', 2192931, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e128af4d-36de-3553-4767-66bba2c73407', 2192931, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e128af4d-36de-3553-4767-66bba2c73407', 2192931, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('40e6076c-ca0a-90df-584d-5f108d63c976', 2192931, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('40e6076c-ca0a-90df-584d-5f108d63c976', 2192931, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Thực đơn cố định</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-11:00 Đang Mở</p><table><tr><td>Người lớn</td><td>36,00 US$(khoảng 934.489₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b296b873-2c78-1e02-65a0-e618aea641ea', 2192931, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
