INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6362637f-5be9-a697-3005-18aff7c9426c', 2193979, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'The Royal Sonesta Houston Galleria');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6362637f-5be9-a697-3005-18aff7c9426c', 2193979, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '2222 W Loop S, Houston, Texas, 77027');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6362637f-5be9-a697-3005-18aff7c9426c', 2193979, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '485');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6362637f-5be9-a697-3005-18aff7c9426c', 2193979, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at The Royal Sonesta Houston Galleria in Houston (The Galleria), you''ll be a 1-minute drive from Westheimer Road and 7 minutes from Rice University. This hotel is 6.6 mi (10.6 km) from MD Anderson Cancer Center and 6.8 mi (10.9 km) from Reliant Stadium.</p><p>Be sure to enjoy recreational amenities including a 24-hour health club and an outdoor pool. Additional amenities at this hotel include shopping on site, wedding services, and a television in a common area.</p><p>Grab lunch at ARA, a restaurant that specializes in international cuisine. Dining is also available at the coffee shop/cafe, and room service (during limited hours) is provided. Quench your thirst with your favorite drink at the bar/lounge. Buffet breakfasts are available daily from 6:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include a 24-hour business center, express check-out, and dry cleaning/laundry services. Planning an event in Houston? This hotel has 50000 square feet (4645 square meters) of space consisting of a conference center and meeting rooms. Self parking (subject to charges) is available onsite.</p><p>Make yourself at home in one of the 485 guestrooms featuring refrigerators and flat-screen televisions. Your pillowtop bed comes with Egyptian cotton sheets. Wireless internet access (surcharge) keeps you connected, and cable programming is available for your entertainment. Private bathrooms with shower/tub combinations feature complimentary toiletries and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c1b37b4f-60e2-a5fd-a89e-78b55911eabc', 2193979, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c1b37b4f-60e2-a5fd-a89e-78b55911eabc', 2193979, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('98f99210-0be2-a301-3ea7-a324e3e68da9', 2193979, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('98f99210-0be2-a301-3ea7-a324e3e68da9', 2193979, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0a2233b9-1aac-17ce-e95f-08a104dc867b', 2193979, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0a2233b9-1aac-17ce-e95f-08a104dc867b', 2193979, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4915844-a059-daa0-a3ff-f964a57f0f36', 2193979, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4915844-a059-daa0-a3ff-f964a57f0f36', 2193979, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 06:00-11:00 Open</p><table><tr><td>Adult</td><td>$$27.00 per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('87db759b-1048-798d-32db-3d288e3b8641', 2193979, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('87db759b-1048-798d-32db-3d288e3b8641', 2193979, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of $100.00 is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment within 14 days after check-out.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b4bf5135-f2bf-c02d-b968-3403150cb150', 2193979, 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b4bf5135-f2bf-c02d-b968-3403150cb150', 2193979, 'POLICY', 'pet', 'en', 'policy_content', '<p>Pets are allowed on request</p><p>Types of pets allowed: dogs, cats</p><p>Fee: $150.00 per pet per stay</p>');
