INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6362637f-5be9-a697-3005-18aff7c9426c', 2193979, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'The Royal Sonesta Houston Galleria');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6362637f-5be9-a697-3005-18aff7c9426c', 2193979, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '2222 W Loop S, 77027 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6362637f-5be9-a697-3005-18aff7c9426c', 2193979, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '485');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6362637f-5be9-a697-3005-18aff7c9426c', 2193979, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>The Royal Sonesta Houston Galleria ở Trung tâm Thương mại Galleria, Houston, cách Đường Westheimer 1 phút lái xe và cách Đại học Rice 7 phút lái xe. Khách sạn này cách Viện Ung thư MD Anderson 10,6 km và cách Sân vận động Reliant 10,9 km.</p><p>Hãy nhớ đừng bỏ qua cơ hội tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm câu lạc bộ sức khỏe phục vụ 24 giờ và hồ bơi ngoài trời. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm khu mua sắm trong khuôn viên, dịch vụ cưới và TV ở khu vực chung.</p><p>Khách có thể dùng bữa trưa tại nhà hàng ARA chuyên về món ăn mang phong cách quốc tế. Các bữa ăn khác cũng được phục vụ tại quán cà phê hoặc khách có thể chọn gọi món với dịch vụ phòng (có giới hạn thời gian). Đập tan cơn khát với đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 6:00 đến 11:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng phục vụ 24 giờ, trả phòng nhanh và dịch vụ giặt ủi/giặt khô. Có kế hoạch tổ chức sự kiện tại Houston? Khách sạn này có khu vực tổ chức rộng 4645 mét vuông, bao gồm trung tâm hội nghị và phòng họp. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 485 phòng được trang bị tủ lạnh và TV màn hình phẳng. Giường nệm có lớp đệm bông được trang bị bộ trải giường bằng vải cotton Ai Cập. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây (phụ phí); trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng với vòi sen/bồn tắm kết hợp có đồ dùng nhà tắm miễn phí và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c1b37b4f-60e2-a5fd-a89e-78b55911eabc', 2193979, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c1b37b4f-60e2-a5fd-a89e-78b55911eabc', 2193979, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('98f99210-0be2-a301-3ea7-a324e3e68da9', 2193979, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('98f99210-0be2-a301-3ea7-a324e3e68da9', 2193979, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0a2233b9-1aac-17ce-e95f-08a104dc867b', 2193979, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0a2233b9-1aac-17ce-e95f-08a104dc867b', 2193979, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4915844-a059-daa0-a3ff-f964a57f0f36', 2193979, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4915844-a059-daa0-a3ff-f964a57f0f36', 2193979, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:00-11:00 Đang Mở</p><table><tr><td>Người lớn</td><td>27,00 US$(khoảng 701.279₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('87db759b-1048-798d-32db-3d288e3b8641', 2193979, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('87db759b-1048-798d-32db-3d288e3b8641', 2193979, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 100,00 US$ (khoảng 2.597.331₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 14 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b4bf5135-f2bf-c02d-b968-3403150cb150', 2193979, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b4bf5135-f2bf-c02d-b968-3403150cb150', 2193979, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó, mèo</p><p>Phí: 150,00 US$ (khoảng 3.895.997₫)/thú cưng/lần lưu trú</p>');
