INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('447c3405-f1ad-7a94-e7d2-a8518ce69edd', 2196657, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '1700 Smith St, Houston, Texas, 77002');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('447c3405-f1ad-7a94-e7d2-a8518ce69edd', 2196657, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '259');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('447c3405-f1ad-7a94-e7d2-a8518ce69edd', 2196657, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>A stay at The Whitehall Houston places you in the heart of Houston, within a 5-minute drive of Downtown Aquarium and Toyota Center. This hotel is 1.5 mi (2.4 km) from Daikin Park and 1.6 mi (2.6 km) from George R. Brown Convention Center.</p><p>Don''t miss out on recreational opportunities including an outdoor pool and a 24-hour fitness center. Additional features at this hotel include complimentary wireless internet access, concierge services, and discounted use of a nearby fitness facility. Getting to nearby attractions is a breeze with the complimentary area shuttle that operates within 1.0 miles.</p><p>Enjoy a meal at the restaurant or snacks in the coffee shop/cafe. The hotel also offers room service (during limited hours). Quench your thirst with your favorite drink at the bar/lounge. Full breakfasts are served on weekdays from 6:00 AM to 11:00 AM and on weekends from 7:00 AM to 1:00 PM for a fee.</p><p>Featured amenities include complimentary wired internet access, a 24-hour business center, and express check-in. Event facilities at this hotel consist of a conference center and meeting rooms.</p><p>Make yourself at home in one of the 259 guestrooms. Your Tempur-Pedic bed comes with premium bedding. Complimentary wired and wireless internet access keeps you connected, and cable programming provides entertainment. Private bathrooms with bathtubs or showers feature complimentary toiletries and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca004de5-b1e5-b5e9-2e94-002226c324b0', 2196657, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca004de5-b1e5-b5e9-2e94-002226c324b0', 2196657, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('135822ad-8762-240a-ea4c-da0cb0ef61f0', 2196657, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('135822ad-8762-240a-ea4c-da0cb0ef61f0', 2196657, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d5884bbc-cd36-79ed-7293-c0948996335f', 2196657, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d5884bbc-cd36-79ed-7293-c0948996335f', 2196657, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs and extra beds can be added.</p><p>Fees for extra beds and cribs are not included in the total price. For details, please contact the hotel.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0b0dbb79-df36-da3f-189a-b23ebf646049', 2196657, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0b0dbb79-df36-da3f-189a-b23ebf646049', 2196657, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Set menu</p><p>Opening hours: [Mon - Fri] 06:00-11:00 Open [Sat - Sun] 07:00-13:00 Open</p><table><tr><td>Adult</td><td>$$15.00 per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
