INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('447c3405-f1ad-7a94-e7d2-a8518ce69edd', 2196657, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'The Whitehall Houston');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('447c3405-f1ad-7a94-e7d2-a8518ce69edd', 2196657, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '1700 Smith St, 77002 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('447c3405-f1ad-7a94-e7d2-a8518ce69edd', 2196657, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '259');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('447c3405-f1ad-7a94-e7d2-a8518ce69edd', 2196657, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Houston, The Whitehall Houston cách Downtown Aquarium và Trung tâm Toyota 5 phút lái xe. Khách sạn cách Trung tâm Hội nghị George R. Brown 2 km và cách Công viên Daikin 2,4 km.</p><p>Đừng bỏ qua những dịch vụ, tiện nghi thể thao, giải trí tuyệt vời, bao gồm hồ bơi ngoài trời và trung tâm thể dục phục vụ 24 giờ. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và quyền sử dụng phòng tập thể dục lân cận với giá ưu đãi. Những chuyến tham quan các thắng cảnh trong vùng sẽ trở nên dễ dàng hơn bao giờ hết với dịch vụ xe đưa đón phục vụ miễn phí trong phạm vi 1.0 dặm.</p><p>Khách có thể thưởng thức những món ăn ngon tại nhà hàng hoặc dùng bữa nhẹ tại quán cà phê. Khách sạn này còn cung cấp dịch vụ phòng (có giới hạn thời gian). Đập tan cơn khát với đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng đầy đủ các ngày trong tuần từ 6:00 đến 11:00 và cuối tuần (phụ phí) từ 7:00 đến 13:00.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm truy cập Internet tốc độ cao (có dây) miễn phí, trung tâm dịch vụ văn phòng phục vụ 24 giờ và nhận phòng nhanh. Khu vực phục vụ hội thảo, sự kiện tại Khách sạn này bao gồm trung tâm hội nghị và phòng họp.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 259 phòng. Giường nệm Tempur-Pedic được trang bị bộ đồ giường cao cấp. Truy cập internet có dây và không dây miễn phí giúp bạn luôn kết nối; và các chương trình truyền hình cáp sẽ mang đến những giây phút giải trí thoải mái. Phòng tắm riêng với bồn tắm hoặc buồng tắm vòi sen có đồ dùng nhà tắm miễn phí và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca004de5-b1e5-b5e9-2e94-002226c324b0', 2196657, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca004de5-b1e5-b5e9-2e94-002226c324b0', 2196657, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('135822ad-8762-240a-ea4c-da0cb0ef61f0', 2196657, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('135822ad-8762-240a-ea4c-da0cb0ef61f0', 2196657, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d5884bbc-cd36-79ed-7293-c0948996335f', 2196657, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d5884bbc-cd36-79ed-7293-c0948996335f', 2196657, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều có thể bổ sung cũi và giường phụ.</p><p>Tổng giá chưa bao gồm phí cho giường phụ và cũi. Vui lòng liên hệ với khách sạn để biết chi tiết.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0b0dbb79-df36-da3f-189a-b23ebf646049', 2196657, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0b0dbb79-df36-da3f-189a-b23ebf646049', 2196657, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Thực đơn cố định</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:00-11:00 Đang Mở [Thứ 7 - CN] 07:00-13:00 Đang Mở</p><table><tr><td>Người lớn</td><td>15,00 US$(khoảng 389.600₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('02311393-7217-bb9c-166d-ab7cc1a7111d', 2196657, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('02311393-7217-bb9c-166d-ab7cc1a7111d', 2196657, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: Liên hệ với cơ sở lưu trú để biết chi tiết</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4924b08-63aa-170d-780f-c8bdcd38e826', 2196657, 'POLICY', 'serviceAnimal', 'vi', 'policy_title', 'Động vật hỗ trợ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4924b08-63aa-170d-780f-c8bdcd38e826', 2196657, 'POLICY', 'serviceAnimal', 'vi', 'policy_content', '<p>Được phép mang theo động vật hỗ trợ nếu có yêu cầu</p>');
