INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Radisson Collection Royal Hotel, Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Hammerichsgade 1, Indre By, Copenhagen, Hovedstaden, 1611, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '263');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Thoughtfully designed by famed Danish architect Arne Jacobsen, the Radisson Collection Royal Hotel, Copenhagen is a 5 star hotel located within walking distance of well-known Tivoli Gardens and popular Stroget shopping district. This sophisticated Copenhagen hotel''s 260 sleek guest rooms and suites are graced with Scandinavian accents and desirable amenities such as in-room mini bar and bathrobes. Two restaurants, a relaxing bar, a large fitness centre and modern meeting facilities accommodating up to 300 guests completing the perfect picture of hospitality.13;10;13;10;Every facet of this high-rise hotel in Copenhagen, from its reflective facade to the spiral staircase and Swan and Egg chairs in the lobby, was designed by Danish architect Arne Jacobsen. Today this very hotel stands as a symbol of Danish design and is a landmark of Copenhagen. 13;10;13;10;The 5 stars are shown in all aspects of the hotel. This venue include the legendary Restaurant and Bar Cafe Royal.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('517c0ca3-c14c-a554-6ef6-0f48b7475d45', 2197629, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('517c0ca3-c14c-a554-6ef6-0f48b7475d45', 2197629, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p><p>If you plan to arrive after 00:00 in the morning on the day following your check-in date, contact the property in advance</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2b5f0dd4-485d-68be-5c5f-d9e8fd769c13', 2197629, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2b5f0dd4-485d-68be-5c5f-d9e8fd769c13', 2197629, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb6aa5b-202b-85a3-ce90-d92a81273c85', 2197629, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb6aa5b-202b-85a3-ce90-d92a81273c85', 2197629, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c73af86-8c83-9c14-12dc-7c6e1fcdecc7', 2197629, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c73af86-8c83-9c14-12dc-7c6e1fcdecc7', 2197629, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><table><tr><td>Children 17 years old and under</td><td>DKK 145 (approx. $22.09) per person</td></tr><tr><td>Adult</td><td>DKK 275 (approx. $41.90) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1ae49404-6765-bc19-d352-a044787ba368', 2197629, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1ae49404-6765-bc19-d352-a044787ba368', 2197629, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of DKK 50 (approx. $7.62) is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment on the day of check-out.</strong></p>');
