INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Radisson Collection Royal Hotel, Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Hammerichsgade 1, Indre By, 1611 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '263');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f14a761e-048b-2345-fa26-593bd16b5448', 2197629, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Radisson Collection Royal Hotel, Copenhagen tọa lạc ở trung tâm Copenhagen, chỉ cách Công viên Tivoli và Quảng trường Tòa thị chính 4 phút đi bộ. Khách sạn sang trọng này cách Phố Strøget 0,4 km và cách Khu Nyhavn 2,4 km.</p><p>Hãy tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí như trung tâm thể dục và xe đạp cho thuê. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và dịch vụ trông trẻ (phụ phí).</p><p>Khách có thể lựa chọn dùng bữa tại nhà hàng của Khách sạn hoặc nghỉ lại trong phòng và thưởng thức những món ăn ngon với dịch vụ phòng 24 giờ. Thư giãn sau một ngày dài bên cạnh ly đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet các ngày trong tuần từ 6:30 đến 10:30 và cuối tuần (phụ phí) từ 7:00 đến 11:00.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm dịch vụ xe limo/xe đưa đón hạng sang, máy vi tính và trả phòng nhanh. Có kế hoạch tổ chức sự kiện tại Copenhagen? Khách sạn này có khu vực tổ chức rộng 750 mét vuông, bao gồm trung tâm hội nghị và 10 phòng họp. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 260 phòng được trang bị máy điều hòa cùng minibar và Smart TV. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình kỹ thuật số sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng có máy sấy tóc và áo choàng tắm. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật và dụng cụ pha cà phê/trà.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('517c0ca3-c14c-a554-6ef6-0f48b7475d45', 2197629, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('517c0ca3-c14c-a554-6ef6-0f48b7475d45', 2197629, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn dự định sẽ đến sau 00:00 vào buổi sáng của ngày sau ngày nhận phòng, vui lòng liên hệ trước với cơ sở lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2b5f0dd4-485d-68be-5c5f-d9e8fd769c13', 2197629, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2b5f0dd4-485d-68be-5c5f-d9e8fd769c13', 2197629, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb6aa5b-202b-85a3-ce90-d92a81273c85', 2197629, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb6aa5b-202b-85a3-ce90-d92a81273c85', 2197629, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c73af86-8c83-9c14-12dc-7c6e1fcdecc7', 2197629, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c73af86-8c83-9c14-12dc-7c6e1fcdecc7', 2197629, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>145 DKK(khoảng 573.448₫) mỗi người</td></tr><tr><td>Người lớn</td><td>275 DKK(khoảng 1.087.574₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1ae49404-6765-bc19-d352-a044787ba368', 2197629, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1ae49404-6765-bc19-d352-a044787ba368', 2197629, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 50 DKK (khoảng 197.741₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Vào ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ed984382-a684-d5cc-3514-93c5375d2177', 2197629, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
