INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Wakeup Copenhagen - Borgergade');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', 'Wakeup Copenhagen Borgergade');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Borgergade 9, Indre By, Copenhagen, Hovedstaden, 1300, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '770');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Wakeup Copenhagen Borgergade, you''ll be centrally located in Copenhagen, just a 5-minute walk from Strøget and 6 minutes by foot from Nyhavn. This hotel is 1.5 mi (2.3 km) from Tivoli Gardens and 1.2 mi (1.9 km) from City Hall Square.</p><p>Enjoy recreation amenities such as bicycles to rent or take in the view from a garden. Additional features at this hotel include complimentary wireless internet access and a television in a common area.</p><p>You can enjoy a meal at the restaurant serving the guests of Wakeup Copenhagen Borgergade, or stop in at the snack bar/deli. Quench your thirst with your favorite drink at the bar/lounge. Buffet breakfasts are available daily from 6:30 AM to 10:00 AM for a fee.</p><p>Featured amenities include a business center, express check-in, and express check-out.</p><p>Stay in one of 770 guestrooms featuring LCD televisions. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Bathrooms have showers and hair dryers. Conveniences include desks, housekeeping is provided on request, and cribs/infant beds (surcharge) can be requested.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f7f0377b-7d4e-5de5-8a3e-6ee6f1a20426', 2198090, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f7f0377b-7d4e-5de5-8a3e-6ee6f1a20426', 2198090, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b473b3b9-736e-916a-e5d2-1cd24238e343', 2198090, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b473b3b9-736e-916a-e5d2-1cd24238e343', 2198090, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2908fd25-1271-7426-b709-63c90a2e8740', 2198090, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2908fd25-1271-7426-b709-63c90a2e8740', 2198090, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs can be added, but extra beds cannot be added.</p><p>Fees for extra beds and cribs are not included in the total and must be paid at the hotel.</p><table><tr><td>Children 1 year old and under</td><td>Extra crib: DKK 100 (approx. $15.24) per person per night</td></tr></table>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6cfce4ad-0829-773b-562f-f8a7ecb2e82f', 2198090, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6cfce4ad-0829-773b-562f-f8a7ecb2e82f', 2198090, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 06:30-10:00 Open</p><table><tr><td>Children 11 years old and under</td><td>DKK 50 (approx. $7.62) per person</td></tr><tr><td>Children 12–17 years old</td><td>DKK 95 (approx. $14.47) per person</td></tr><tr><td>Adult</td><td>DKK 95 (approx. $14.47) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95d8a796-ae4e-c5d5-153e-42a1133ffb78', 2198090, 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95d8a796-ae4e-c5d5-153e-42a1133ffb78', 2198090, 'POLICY', 'pet', 'en', 'policy_content', '<p>Pets are not allowed</p>');
