INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Wakeup Copenhagen - Borgergade');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', 'Wakeup Copenhagen Borgergade');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Borgergade 9, Indre By, 1300 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '770');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('009637d9-36a1-21ac-268c-de8dd657be9f', 2198090, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Wakeup Copenhagen Borgergade ở trung tâm Copenhagen, chỉ cách Phố Strøget 5 phút đi bộ và cách Khu Nyhavn 6 phút đi bộ. Khách sạn này cách Công viên Tivoli 2,3 km và cách Quảng trường Tòa thị chính 1,9 km.</p><p>Hãy tận hưởng những tiện nghi, dịch vụ thư giãn như xe đạp cho thuê hay chỉ đơn giản là ngắm cảnh từ vườn. Những dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí và TV ở khu vực chung.</p><p>Khách có thể dùng bữa tại nhà hàng của Wakeup Copenhagen Borgergade hoặc ghé qua tiệm/cửa hàng đồ ăn nhanh để mua quà vặt và món ăn nhẹ. Đập tan cơn khát với đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 6:30 đến 10:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng, nhận phòng nhanh và trả phòng nhanh.</p><p>Hãy nghỉ tại một trong 770 phòng được trang bị TV LCD. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm được trang bị buồng tắm vòi sen và máy sấy tóc. Tiện nghi phòng có bàn; dịch vụ dọn phòng phục vụ dịch vụ dọn phòng (theo yêu cầu); ngoài ra cũng có thể yêu cầu thêm nôi/giường cho trẻ sơ sinh (phụ phí).</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f7f0377b-7d4e-5de5-8a3e-6ee6f1a20426', 2198090, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f7f0377b-7d4e-5de5-8a3e-6ee6f1a20426', 2198090, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b473b3b9-736e-916a-e5d2-1cd24238e343', 2198090, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b473b3b9-736e-916a-e5d2-1cd24238e343', 2198090, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2908fd25-1271-7426-b709-63c90a2e8740', 2198090, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2908fd25-1271-7426-b709-63c90a2e8740', 2198090, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều có thể bổ sung cũi, nhưng không thể bổ sung giường phụ.</p><p>Phí giường phụ và cũi chưa được bao gồm trong tổng giá và phải được thanh toán tại khách sạn.</p><table><tr><td>Trẻ em 1 tuổi trở xuống</td><td>Thêm cũi: 100 DKK(khoảng 395.481₫) mỗi người mỗi đêm</td></tr></table>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6cfce4ad-0829-773b-562f-f8a7ecb2e82f', 2198090, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6cfce4ad-0829-773b-562f-f8a7ecb2e82f', 2198090, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:00 Đang Mở</p><table><tr><td>Trẻ em 11 tuổi trở xuống</td><td>50 DKK(khoảng 197.741₫) mỗi người</td></tr><tr><td>Trẻ em 12–17 tuổi</td><td>95 DKK(khoảng 375.707₫) mỗi người</td></tr><tr><td>Người lớn</td><td>95 DKK(khoảng 375.707₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95d8a796-ae4e-c5d5-153e-42a1133ffb78', 2198090, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('95d8a796-ae4e-c5d5-153e-42a1133ffb78', 2198090, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Không được phép mang theo thú cưng</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0f2035a7-8d90-2e08-340a-15780a8eb68c', 2198090, 'POLICY', 'ageLimit', 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0f2035a7-8d90-2e08-340a-15780a8eb68c', 2198090, 'POLICY', 'ageLimit', 'vi', 'policy_content', '<p>Khách chính nhận phòng phải từ 18 tuổi trở lên.</p>');
