INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d34f3423-aedc-e105-70cb-5d3c0958239f', 2219141, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Courtyard Houston Westchase');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d34f3423-aedc-e105-70cb-5d3c0958239f', 2219141, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '9975 Westheimer Rd, Houston, Texas, 77042');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d34f3423-aedc-e105-70cb-5d3c0958239f', 2219141, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '126');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d34f3423-aedc-e105-70cb-5d3c0958239f', 2219141, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Stay at Courtyard by Marriott Houston Westchase, located in the heart of Houston’s prestigious Westchase District, just off Westheimer and the Sam Houston Tollway. Our hotel is minutes from Houston’s Energy Corridor and CityCentre, offering vibrant nightlife and top-tier dining. Perfect for business travelers, we’re close to major corporations like Emerson, Phillips 66, Chevron, Deloitte, Siemens, Honeywell, ABB, and more. For leisure guests, we’re conveniently situated between the upscale shopping of The Galleria and the trendy boutiques and restaurants of CityCentre. Start your morning with a fresh Starbucks® coffee from The Bistro, and after a busy day, relax in our serene courtyard or take a refreshing dip in the outdoor pool. Discover the perfect blend of business and leisure at Courtyard Houston Westchase!</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d310871a-b49d-def7-d5f7-2d75d88a3c0c', 2219141, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d310871a-b49d-def7-d5f7-2d75d88a3c0c', 2219141, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2588e4e6-90ad-2909-37d8-ee6b985f846a', 2219141, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2588e4e6-90ad-2909-37d8-ee6b985f846a', 2219141, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children aged 17 and above are welcome at this hotel.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('eccbf225-349c-af13-7efd-af61e2b6221d', 2219141, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('eccbf225-349c-af13-7efd-af61e2b6221d', 2219141, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('21cd33f2-50e4-ff76-8eb6-79ec96273e00', 2219141, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('21cd33f2-50e4-ff76-8eb6-79ec96273e00', 2219141, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: A la carte</p><p>Cuisine: American</p><p>Opening hours: [Mon - Fri] 06:30-09:00 Open [Sat - Sun] 07:00-09:00 Open</p><p>Price for extra breakfasts: Varies based on the food ordered</p><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
