INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d34f3423-aedc-e105-70cb-5d3c0958239f', 2219141, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Courtyard Houston Westchase');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d34f3423-aedc-e105-70cb-5d3c0958239f', 2219141, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '9975 Westheimer Rd, 77042 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d34f3423-aedc-e105-70cb-5d3c0958239f', 2219141, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '126');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d34f3423-aedc-e105-70cb-5d3c0958239f', 2219141, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc ở Houston, cách Khu phức hợp CityCentre 6.5 km, Courtyard Houston Westchase cung cấp chỗ nghỉ có xe đạp miễn phí, chỗ đậu xe riêng, hồ bơi ngoài trời và khu vườn. Ngoài Wi-Fi miễn phí, khách sạn 3 sao này còn cung cấp nhà hàng và quầy bar. Khách sạn cung cấp sân hiên phơi nắng và lễ tân 24/24.</p><p>Phòng khách được trang bị điều hòa, TV màn hình phẳng có truyền hình cáp, tủ lạnh, máy pha cà phê, vòi sen, đồ vệ sinh cá nhân miễn phí và bàn làm việc. Ngoài phòng tắm riêng với bồn tắm và máy sấy tóc, một số căn tại khách sạn cũng có view hồ bơi. Tại Courtyard Houston Westchase, mỗi phòng đều được thiết kế có ga trải giường và khăn tắm.</p><p>Chỗ nghỉ có phục vụ bữa sáng thực đơn à la carte và kiểu Mỹ.</p><p>Courtyard Houston Westchase cách Trung tâm mua sắm Galleria Houston 8.2 km và Công viên Waterwall Park 8.6 km.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d310871a-b49d-def7-d5f7-2d75d88a3c0c', 2219141, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d310871a-b49d-def7-d5f7-2d75d88a3c0c', 2219141, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2588e4e6-90ad-2909-37d8-ee6b985f846a', 2219141, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2588e4e6-90ad-2909-37d8-ee6b985f846a', 2219141, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em 17 tuổi trở lên được chào đón tại khách sạn này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('eccbf225-349c-af13-7efd-af61e2b6221d', 2219141, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('eccbf225-349c-af13-7efd-af61e2b6221d', 2219141, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('21cd33f2-50e4-ff76-8eb6-79ec96273e00', 2219141, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('21cd33f2-50e4-ff76-8eb6-79ec96273e00', 2219141, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Gọi món</p><p>Ẩm thực: Mỹ</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-09:00 Đang Mở [Thứ 7 - CN] 07:00-09:00 Đang Mở</p><p>Giá thêm bữa sáng: Phụ thuộc vào món bạn đặt</p><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a84238f-d9bb-656f-1a0e-96f6c734f130', 2219141, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6a84238f-d9bb-656f-1a0e-96f6c734f130', 2219141, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 150,00 US$ (khoảng 3.893.703₫).</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6e6a57dd-607a-9c3d-45c9-0cca21807263', 2219141, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
