INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('534964bc-62f8-d5d7-ec47-95c5edcac5fb', 2219141, 'POLICY', 'ageLimit', 'vi', 'policy_title', 'Giới hạn độ tuổi');
