INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fa8baba-4fde-c047-fd76-cf0a0a8d07d9', 2225828, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hilton Americas - Houston');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fa8baba-4fde-c047-fd76-cf0a0a8d07d9', 2225828, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '1600 Lamar St, Houston, Texas, 77010');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fa8baba-4fde-c047-fd76-cf0a0a8d07d9', 2225828, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '1200');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fa8baba-4fde-c047-fd76-cf0a0a8d07d9', 2225828, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Daily Mandatory Charge includes: $2.00 plus tax Downtown District Fee paid to Houston First Corporation, a local government corporation.</p><p>Welcome to the Hilton Americas-Houston, located in the heart of downtown Houston, Texas. Enjoy all the luxuries of home plus all the amenities you need, whether you''re traveling for business or pleasure. Our Houston hotel offers the ideal Houston city location, with quick and easy access to a wealth of entertainment options. As of April 2009, our Houston, TX hotel is the first hotel in the state to achieve Green Seal certification through our commitment to the environment.</p><p>The Hilton Americas-Houston features:</p><p>* 1,207 luxurious Houston accommodations including four Presidential suites and 26 one- or two-bedroom suites.</p><p>* Executive floor with private access and complimentary WiFi.</p><p>* Valet parking only</p><p>* WiFi available in guest rooms and throughout the hotel.</p><p>* 1600 Bar Grille, a full-service restaurant located at the lobby level for breakfast, lunch and dinner.</p><p>* In-room dining.</p><p>* Two exceptional bars and lounges including the Lobby Bar.</p><p>* If you are searching for a spa in Houston, our Skyline Spa &amp; Health Club is the perfect choice, with views of the downtown Houston skyline from the 23rd floor of the Hilton Americas-Houston hotel.</p><p>* 75-foot 24th-floor heated indoor infinity lap pool.</p><p>* In-house FedEx Print and Ship Store and business center for Hilton Americas-Houston hotel guests and meeting attendees.</p><p>* Hilton Americas-Houston is a Travel Alternatives Group (TAG) Certified Hotel.</p><p>Only steps away from Houston''s sports &amp; entertainment venues:</p><p>* Toyota Center, home of the NBA Houston Rockets, plus concerts and other entertainment events.</p><p>* Daikin Park, home of the MLB Houston Astros, is only a leisurely, scenic walk away through Discovery Green - Houston''s newest 12-acre urban park.</p><p>* PNC Stadium (formerly BBVA Compass Stadium), Houston Dynamo, a Major League Soccer club.</p><p>* Reliant Stadium, home of the NFL Houston Texans, and Reliant Park, Reliant Center, Reliant Arena &amp; Reliant Astrodome are all quickly and easily reached from our hotel via the MetroRail light rail system.</p><p>Other Houston attractions just minutes from our hotel include Discovery Green Park, the House of Blues, Lucky Strike Bowling, the Bayou City Place entertainment district featuring the Bayou Music Center, and the Theatre District, including the Wortham Center, Alley Theater, Jones Hall, and Hobby Center for the Performing Arts. Our Houston, Texas hotel is convenient to nearby clubs and night spots, and offers an ideal location in the heart of downtown. The hotel is only minutes away from the city''s nationally recognized Museum District and the world renowned Texas Medical Center.</p><p>Hilton Americas-Houston Meeting &amp; Convention Services</p><p>* Our state-of-the-art hotel is the largest convention hotel in Houston, Texas.</p><p>* 91,500 sq. ft. of hotel meeting space, ideal for any size meeting or social event in Houston.</p><p>* 40,000 sq. ft. Grand Ballroom, divisible into 12 rooms: accommodates 3,000 guests banquet style or 3,500 guests theater style.</p><p>* 26,000 sq. ft. Ballroom of the Americas, divisible in to six independent meeting rooms: accommodates 2,500 guests theatre style.</p><p>* Connected to the Houston George R. Brown Convention Center via two convenient indoor skywalks.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecffdcab-e712-57e6-9bd6-17d9506a00b3', 2225828, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
