INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20dc38d3-8713-eaf9-a7a4-dcfa21cb2728', 2225828, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: American, Continental, Gluten-free, Vegan, Vegetarian</p><p>Opening hours: [Mon - Sun] 06:30-10:00 Open</p><table><tr><td>Children 12 years old and under</td><td>$$15.00 per person</td></tr><tr><td>Children 13–17 years old</td><td>$$26.00 per person</td></tr><tr><td>Adult</td><td>$$26.00 per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
