INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fa8baba-4fde-c047-fd76-cf0a0a8d07d9', 2225828, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hilton Americas - Houston');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fa8baba-4fde-c047-fd76-cf0a0a8d07d9', 2225828, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '1600 Lamar St, 77010 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fa8baba-4fde-c047-fd76-cf0a0a8d07d9', 2225828, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '1200');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9fa8baba-4fde-c047-fd76-cf0a0a8d07d9', 2225828, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Houston, Hilton Americas-Houston cách Trung tâm Hội nghị George R. Brown và Trung tâm Toyota vài bước. Khách sạn cách Công viên Daikin 1,2 km và cách Sân vận động Shell Energy 1,4 km.</p><p>Hãy để mình được chăm sóc thật đặc biệt với các dịch vụ massage, trị liệu toàn thân chăm sóc da mặt ngay trong khuôn viên. Đừng bỏ qua cơ hội tận hưởng những dịch vụ, tiện nghi thể thao, giải trí như hồ bơi trong nhà, bồn tắm thủy lực hay trung tâm thể dục phục vụ 24 giờ. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và cửa hàng quà tặng/sạp báo.</p><p>Dùng bữa tại 1600 Bar + Grille, một trong 2 nhà hàng của Khách sạn hoặc nghỉ lại trong phòng và tận hưởng dịch vụ phòng (có giới hạn thời gian). Thức ăn nhẹ cũng có ở quán cà phê. Đập tan cơn khát với đồ uống yêu thích của mình tại 2 quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet các ngày trong tuần từ 6:30 đến 10:00 và cuối tuần (phụ phí) từ 6:30 đến 12:00.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trả phòng nhanh, dịch vụ giặt ủi/giặt khô và quầy tiếp tân phục vụ 24 giờ/ngày. Có kế hoạch tổ chức sự kiện tại Houston? Khách sạn này có khu vực tổ chức rộng 10626 mét vuông, bao gồm trung tâm hội nghị và 38 phòng họp.</p><p>Hãy nghỉ tại một trong 1207 phòng được trang bị Smart TV. Giường được trang bị chăn bông và bộ trải giường bằng vải cotton Ai Cập. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây (phụ phí); trong khi các chương trình truyền hình kỹ thuật số sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng với bồn tắm hoặc buồng tắm vòi sen có đồ dùng nhà tắm miễn phí và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecffdcab-e712-57e6-9bd6-17d9506a00b3', 2225828, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecffdcab-e712-57e6-9bd6-17d9506a00b3', 2225828, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nhận phòng qua ứng dụng</p><p>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú muộn nhất vào điện thoại</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ced11c64-d854-af14-fcbe-69e48930daa3', 2225828, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ced11c64-d854-af14-fcbe-69e48930daa3', 2225828, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff33a6af-f7ee-6b58-c2ec-bcd608f38ae1', 2225828, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff33a6af-f7ee-6b58-c2ec-bcd608f38ae1', 2225828, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20dc38d3-8713-eaf9-a7a4-dcfa21cb2728', 2225828, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20dc38d3-8713-eaf9-a7a4-dcfa21cb2728', 2225828, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Mỹ, Đại lục, Không Gluten, Thuần chay, Chay</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:00 Đang Mở</p><table><tr><td>Trẻ em 12 tuổi trở xuống</td><td>15,00 US$(khoảng 389.370₫) mỗi người</td></tr><tr><td>Trẻ em 13–17 tuổi</td><td>26,00 US$(khoảng 674.909₫) mỗi người</td></tr><tr><td>Người lớn</td><td>26,00 US$(khoảng 674.909₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bf344573-ed82-4c51-53b3-554ac949b4c4', 2225828, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bf344573-ed82-4c51-53b3-554ac949b4c4', 2225828, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng, thẻ ghi nợ và tiền mặt</strong></p>');
