INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca5818c7-7206-f181-060a-c549bfdc8713', 2238156, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '2504 N Loop W, Houston, Texas, 77092');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca5818c7-7206-f181-060a-c549bfdc8713', 2238156, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '197');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca5818c7-7206-f181-060a-c549bfdc8713', 2238156, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located in Houston (Lazybrook/Timbergrove), Heritage Place Houston Brookhollow is within a 15-minute drive of Downtown Aquarium and Daikin Park. This hotel is 9.1 mi (14.7 km) from CityCentre and 9.2 mi (14.8 km) from Toyota Center.</p><p>Take advantage of recreation opportunities including an outdoor pool and a fitness center. Additional amenities at this hotel include complimentary wireless internet access, gift shops/newsstands, and wedding services.</p><p>Featured amenities include a 24-hour business center, express check-in, and express check-out. Planning an event in Houston? This hotel has 468 square feet (43 square meters) of space consisting of conference space and a meeting room. Free self parking is available onsite.</p><p>Make yourself at home in one of the 197 air-conditioned rooms featuring refrigerators and LCD televisions. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Private bathrooms with shower/tub combinations feature complimentary toiletries and hair dryers. Conveniences include desks and coffee/tea makers, as well as phones with free local calls.</p>');
