INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ca5818c7-7206-f181-060a-c549bfdc8713', 2238156, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại Lazybrook/Timbergrove, Houston, Heritage Place Houston Brookhollow chỉ cách Downtown Aquarium và Công viên Daikin 15 phút lái xe. Khách sạn cách Trung tâm Thương mại CityCentre 14,7 km và cách Trung tâm Toyota 14,8 km.</p><p>Hãy tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm hồ bơi ngoài trời và trung tâm thể dục. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, cửa hàng quà tặng/sạp báo và dịch vụ cưới.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng phục vụ 24 giờ, nhận phòng nhanh và trả phòng nhanh. Có kế hoạch tổ chức sự kiện tại Houston? Khách sạn này có khu vực tổ chức rộng 43 mét vuông, bao gồm khu hội nghị và phòng họp. Có bãi đậu xe tự phục vụ miễn phí trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 197 phòng được trang bị máy điều hòa cùng tủ lạnh và TV LCD. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng với vòi sen/bồn tắm kết hợp có đồ dùng nhà tắm miễn phí và máy sấy tóc. Các tiện nghi phòng bao gồm bàn và dụng cụ pha cà phê/trà, cùng điện thoại với điện thoại nội vùng miễn phí.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27c7bad5-dbde-598c-4452-9d834eb5bc1b', 2238156, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('27c7bad5-dbde-598c-4452-9d834eb5bc1b', 2238156, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('eb999d65-549f-0d5c-5cd2-b265ae154bb0', 2238156, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('eb999d65-549f-0d5c-5cd2-b265ae154bb0', 2238156, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e3ad23e5-4462-c409-ccfb-bb91ba871710', 2238156, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e3ad23e5-4462-c409-ccfb-bb91ba871710', 2238156, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3770e906-983a-25cb-db38-6bcb9a9756de', 2238156, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3770e906-983a-25cb-db38-6bcb9a9756de', 2238156, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Không có bữa sáng.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('136c7b7b-9269-bc5f-a7d7-2b001557b812', 2238156, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('136c7b7b-9269-bc5f-a7d7-2b001557b812', 2238156, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 100,00 US$ (khoảng 2.597.331₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a2397da9-533d-2570-2c58-47c7d83dda8d', 2238156, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a2397da9-533d-2570-2c58-47c7d83dda8d', 2238156, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó, mèo</p><p>Phí: 46,80 US$ (khoảng 1.215.551₫)/thú cưng/lần lưu trú</p>');
