INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45cd4113-901a-2f92-c99d-f5c132fdbc6a', 2281715, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>A stay at Hotel Peyto Gangnam places you in the heart of Seoul, within a 10-minute drive of COEX Convention and Exhibition Center and Bongeunsa Temple. This hotel is 4.4 mi (7.1 km) from Seoul Olympic Stadium and 5.7 mi (9.1 km) from Seoul Land.</p><p>Take advantage of recreation opportunities such as a health club or take in the view from a rooftop terrace and a garden. Additional amenities at this hotel include complimentary wireless internet access, concierge services, and wedding services.</p><p>Enjoy a satisfying meal at CAFE PO:Z serving guests of Hotel Peyto Gangnam. Buffet breakfasts are served on weekdays from 7:00 AM to 10:00 AM for a fee.</p><p>Featured amenities include complimentary wired internet access, a business center, and dry cleaning/laundry services. Event facilities at this hotel consist of conference space and meeting rooms. Limited parking is available onsite.</p><p>Make yourself at home in one of the 186 individually decorated guestrooms, featuring refrigerators and LCD televisions. Complimentary wired and wireless internet access keeps you connected, and cable programming provides entertainment. Bathrooms have hair dryers and slippers. Conveniences include phones, as well as laptop-compatible safes and desks.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bd36ec47-d523-7287-ba91-3a80477c597f', 2281715, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bd36ec47-d523-7287-ba91-3a80477c597f', 2281715, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–24:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2ca1dbf5-065c-a8f0-7c42-eb1cd2a284cb', 2281715, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2ca1dbf5-065c-a8f0-7c42-eb1cd2a284cb', 2281715, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff95aca7-d91c-d822-1db1-060e0a6b655c', 2281715, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff95aca7-d91c-d822-1db1-060e0a6b655c', 2281715, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b3c8855f-3979-a252-1748-d0bfa1834080', 2281715, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b3c8855f-3979-a252-1748-d0bfa1834080', 2281715, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Fri] 07:00-10:00 Open [Sat - Sun] Closed</p><table><tr><td>Children 3 years old and under</td><td>Free</td></tr><tr><td>Children 4–12 years old</td><td>KRW 13,200 (approx. $9.70) per person</td></tr><tr><td>Children 13–17 years old</td><td>KRW 22,000 (approx. $16.16) per person</td></tr><tr><td>Adult</td><td>KRW 22,000 (approx. $16.16) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
