INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45cd4113-901a-2f92-c99d-f5c132fdbc6a', 2281715, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hotel Peyto Gangnam');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45cd4113-901a-2f92-c99d-f5c132fdbc6a', 2281715, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '호텔 페이토 강남');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45cd4113-901a-2f92-c99d-f5c132fdbc6a', 2281715, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '259 Gangnam-daero, Seocho-gu, 06730 Seoul, Hàn Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45cd4113-901a-2f92-c99d-f5c132fdbc6a', 2281715, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '188');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45cd4113-901a-2f92-c99d-f5c132fdbc6a', 2281715, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Seoul, Hotel Peyto Gangnam cách Trung tâm hội nghị và triển lãm COEX và Đền Bongeunsa 10 phút lái xe. Khách sạn cách Sân vận động Olympic Seoul 7,1 km và cách Công viên Giải trí Seoul Land 9,1 km.</p><p>Đừng bỏ qua cơ hội tận hưởng những dịch vụ thư giãn, giải trí như câu lạc bộ sức khỏe hay chỉ đơn giản là ngắm cảnh từ sân thượng và vườn. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và dịch vụ cưới.</p><p>Khách có thể dùng bữa tại CAFE PO:Z của Hotel Peyto Gangnam. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:00 đến 10:00 vào các ngày trong tuần.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm truy cập Internet tốc độ cao (có dây) miễn phí, trung tâm dịch vụ văn phòng và dịch vụ giặt ủi/giặt khô. Khu vực phục vụ hội thảo, sự kiện tại Khách sạn này bao gồm khu hội nghị và phòng họp. Có số chỗ đậu xe có hạn trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 186 phòng trang trí khác biệt với tủ lạnh và TV LCD. Truy cập internet có dây và không dây miễn phí giúp bạn luôn kết nối; và các chương trình truyền hình cáp sẽ mang đến những giây phút giải trí thoải mái. Các phòng tắm có máy sấy tóc và dép đi trong nhà. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật đặt được máy tính xách tay và bàn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bd36ec47-d523-7287-ba91-3a80477c597f', 2281715, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bd36ec47-d523-7287-ba91-3a80477c597f', 2281715, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 24:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2ca1dbf5-065c-a8f0-7c42-eb1cd2a284cb', 2281715, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2ca1dbf5-065c-a8f0-7c42-eb1cd2a284cb', 2281715, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff95aca7-d91c-d822-1db1-060e0a6b655c', 2281715, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ff95aca7-d91c-d822-1db1-060e0a6b655c', 2281715, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b3c8855f-3979-a252-1748-d0bfa1834080', 2281715, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b3c8855f-3979-a252-1748-d0bfa1834080', 2281715, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 07:00-10:00 Đang Mở [Thứ 7 - CN] Đã Đóng</p><table><tr><td>Trẻ em 3 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 4–12 tuổi</td><td>13.200 KRW(khoảng 252.408₫) mỗi người</td></tr><tr><td>Trẻ em 13–17 tuổi</td><td>22.000 KRW(khoảng 420.680₫) mỗi người</td></tr><tr><td>Người lớn</td><td>22.000 KRW(khoảng 420.680₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2780dcde-846b-819e-2d88-870d98efc251', 2281715, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
