INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d6e7ac1d-109d-5401-f469-25681aa8592f', 2546719, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Copenhagen Downtown Hostel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d6e7ac1d-109d-5401-f469-25681aa8592f', 2546719, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Vandkunsten 5, Indre By, 1467 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d6e7ac1d-109d-5401-f469-25681aa8592f', 2546719, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d6e7ac1d-109d-5401-f469-25681aa8592f', 2546719, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '85');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d6e7ac1d-109d-5401-f469-25681aa8592f', 2546719, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Copenhagen Downtown Hostel ở trung tâm Copenhagen, cách Quảng trường Tòa thị chính và Phố Strøget 5 phút đi bộ. Hostel này cách Công viên Tivoli 0,7 km và cách Khu Nyhavn 1,1 km.</p><p>Hãy tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí như hộp đêm và karaoke. Các dịch vụ, tiện ích khác tại Hostel này bao gồm quyền truy cập Internet không dây miễn phí, phòng trò chơi và TV ở khu vực chung.</p><p>Khách có thể dùng bữa tối tại quầy bar/khu lounge, Downtown Bar của Hostel hoặc thưởng thức bữa ăn nhẹ tại quán cà phê. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:30 đến 10:30 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trả phòng nhanh, báo miễn phí ở sảnh và nhân viên thông thạo nhiều ngôn ngữ. Có kế hoạch tổ chức sự kiện tại Copenhagen? Hostel này có khu vực tổ chức rộng 150 mét vuông, bao gồm khu hội nghị.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 85 phòng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Các phòng có phòng tắm với buồng tắm vòi sen. Dịch vụ dọn phòng phục vụ dịch vụ dọn phòng (theo yêu cầu); và khách có thể yêu cầu thêm cả bàn ủi/dụng cụ ủi quần áo.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50a41797-149c-4af5-c334-bee2301535af', 2546719, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50a41797-149c-4af5-c334-bee2301535af', 2546719, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 24:00</strong></p><p>Trả phòng: <strong>06:00–10:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c110ea4b-fe0c-ef27-e6d7-5cbfa31f4cff', 2546719, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c110ea4b-fe0c-ef27-e6d7-5cbfa31f4cff', 2546719, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Cơ sở lưu trú này không nhận khách lưu trú là trẻ em</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7964f58e-7a5e-a37f-2563-d920658c1c0b', 2546719, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7964f58e-7a5e-a37f-2563-d920658c1c0b', 2546719, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('46c0f2fb-62df-a41a-a707-fc027b4d1d36', 2546719, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('46c0f2fb-62df-a41a-a707-fc027b4d1d36', 2546719, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:30-10:30 Đang Mở</p><table><tr><td>Người lớn</td><td>65 DKK(khoảng 257.063₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2958585f-db54-daa7-1590-ad9099ad0c2e', 2546719, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
