INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Nimb Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', 'Nimb');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Bernstorffsgade 5, Indre By, Copenhagen, Hovedstaden, 1577, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '38');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Nimb Hotel, you''ll be centrally located in Copenhagen, steps from Tivoli Gardens and within a 5-minute walk of City Hall Square. This luxury hotel is 0.6 mi (1 km) from Strøget and 1.8 mi (2.8 km) from Copenhagen Zoo.</p><p>Pamper yourself with a visit to the spa, which offers massages, body treatments, and facials. You''re sure to appreciate the recreational amenities, including a 24-hour health club, a steam room, and a seasonal outdoor pool. Additional amenities at this hotel include complimentary wireless internet access, concierge services, and babysitting (surcharge).</p><p>Enjoy French cuisine at Nimb Brasserie, one of the hotel''s 2 restaurants, or stay in and take advantage of the 24-hour room service. Snacks are also available at the coffee shop/cafe. Relax with a refreshing drink from the poolside bar or one of the 2 bars/lounges. Full breakfasts are available daily from 7 AM to 11 AM for a fee.</p><p>Featured amenities include dry cleaning/laundry services, a 24-hour front desk, and multilingual staff. Planning an event in Copenhagen? This hotel has 10764 square feet (1000 square meters) of space consisting of conference space and 15 meeting rooms. A roundtrip airport shuttle is provided for a surcharge (available 24 hours).</p><p>Make yourself at home in one of the 38 individually decorated guestrooms, featuring espresso makers and flat-screen televisions. Your memory foam bed comes with Egyptian cotton sheets. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Bathrooms have designer toiletries and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fe32a1a0-57b8-9bba-441a-9b9eaea2b6fc', 2546720, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fe32a1a0-57b8-9bba-441a-9b9eaea2b6fc', 2546720, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>00:00–12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a2c1d4f3-5c6a-b63f-19b5-34953946c7da', 2546720, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a2c1d4f3-5c6a-b63f-19b5-34953946c7da', 2546720, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3c2fe4ef-0745-e321-8e2f-2ac3b5e9b946', 2546720, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3c2fe4ef-0745-e321-8e2f-2ac3b5e9b946', 2546720, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7a3753d1-eee8-e46e-66b3-59ef7491b1a9', 2546720, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7a3753d1-eee8-e46e-66b3-59ef7491b1a9', 2546720, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Set menu</p><p>Opening hours: [Mon - Sun] 07:00-11:00 Open</p><table><tr><td>Children 17 years old and under</td><td>DKK 395 (approx. $60.18) per person</td></tr><tr><td>Adult</td><td>DKK 395 (approx. $60.18) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7ab86567-c5a4-4917-90cd-054dea121e78', 2546720, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7ab86567-c5a4-4917-90cd-054dea121e78', 2546720, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>No deposit required by the property</strong></p>');
