INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Nimb Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', 'Nimb');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Bernstorffsgade 5, Indre By, 1577 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '38');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4afb8a3-52d4-3911-cd5d-b54fa91bd245', 2546720, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, Nimb Hotel cách Công viên Tivoli vài bước và cách Quảng trường Tòa thị chính 5 phút đi bộ. Khách sạn sang trọng này cách Phố Strøget 1 km và cách Sở thú Copenhagen 2,8 km.</p><p>Hãy để mình được chăm sóc thật đặc biệt khi ghé đến khu spa, với những dịch vụ massage, trị liệu toàn thân và chăm sóc da mặt. Chắc chắn bạn sẽ thích những dịch vụ, tiện nghi thể thao, giải trí, gồm câu lạc bộ sức khỏe phục vụ 24 giờ, phòng xông hơi và hồ bơi ngoài trời phục vụ theo mùa. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và dịch vụ trông trẻ (phụ phí).</p><p>Khách có thể thưởng thức món Pháp tại Nimb Brasserie, một trong 2 nhà hàng ở Khách sạn hoặc nghỉ lại trong phòng và tận hưởng dịch vụ phòng 24 giờ. Thức ăn nhẹ cũng có ở quán cà phê. Thư giãn tạo quầy bar bên hồ bơi hoặc một trong 2 quầy bar/khu lounge với những ly nước mát. Khách có thể dùng bữa sáng đầy đủ (có phụ phí) từ 7:00 đến 11:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm dịch vụ giặt ủi/giặt khô, quầy tiếp tân phục vụ 24 giờ/ngày và nhân viên thông thạo nhiều ngôn ngữ. Có kế hoạch tổ chức sự kiện tại Copenhagen? Khách sạn này có khu vực tổ chức rộng 1000 mét vuông, bao gồm khu hội nghị và 15 phòng họp. Xe đưa đón sân bay phục vụ 24 giờ với phụ phí.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 38 phòng trang trí khác biệt với dụng cụ pha espresso và TV màn hình phẳng. Giường nệm cao su hoạt tính (memory foam) được trang bị bộ trải giường bằng vải cotton Ai Cập. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm có đồ dùng nhà tắm được thiết kế riêng và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fe32a1a0-57b8-9bba-441a-9b9eaea2b6fc', 2546720, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fe32a1a0-57b8-9bba-441a-9b9eaea2b6fc', 2546720, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>00:00–12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a2c1d4f3-5c6a-b63f-19b5-34953946c7da', 2546720, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a2c1d4f3-5c6a-b63f-19b5-34953946c7da', 2546720, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3c2fe4ef-0745-e321-8e2f-2ac3b5e9b946', 2546720, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3c2fe4ef-0745-e321-8e2f-2ac3b5e9b946', 2546720, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7a3753d1-eee8-e46e-66b3-59ef7491b1a9', 2546720, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7a3753d1-eee8-e46e-66b3-59ef7491b1a9', 2546720, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Thực đơn cố định</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-11:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>395 DKK(khoảng 1.562.152₫) mỗi người</td></tr><tr><td>Người lớn</td><td>395 DKK(khoảng 1.562.152₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7ab86567-c5a4-4917-90cd-054dea121e78', 2546720, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7ab86567-c5a4-4917-90cd-054dea121e78', 2546720, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Chỗ nghỉ không yêu cầu đặt cọc</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e9890001-0e7f-20ed-924c-cd28027c3296', 2546720, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e9890001-0e7f-20ed-924c-cd28027c3296', 2546720, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó, mèo</p><p>Phí: 1.100 DKK (khoảng 4.350.296₫)/phòng/lần lưu trú</p>');
