INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6874b1c5-e09b-71c8-6b88-522f71db7e8b', 2551515, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '6115 Will Clayton Pkwy, Houston, Texas, 77338');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6874b1c5-e09b-71c8-6b88-522f71db7e8b', 2551515, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '163');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6874b1c5-e09b-71c8-6b88-522f71db7e8b', 2551515, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Refresh at this Ramada Houston Intercontinental Airport East hotel conveniently located off Interstate 69 near Houston Intercontinental Airport downtown Houston golfing at Tour 18 Golf Course horse racing at Sam Houston Race Track and NASA Space Center. After a day of business or leisure relax at this hotel with complimentary wireless Internet access complimentary airport shuttle service fitness center seasonal outdoor pool and sundeck Ramada Mart convenience store complimentary parking for all sizes of vehicles meeting facilities and business center. Enjoy an onsite meal at Dolphins Restaurant or a cocktail at Dolphan Bar. Guest room amenities include refrigerator and microwave. Suites and smoke-free rooms are also available. There is no charge for children 17 and under with an adult.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('67b57b6c-6c59-cc47-0385-0fd40a69624b', 2551515, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('67b57b6c-6c59-cc47-0385-0fd40a69624b', 2551515, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa536cf-ec09-676e-a44a-fde8ec36234d', 2551515, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa536cf-ec09-676e-a44a-fde8ec36234d', 2551515, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('beab7f63-8978-0930-4f48-e11bc56fece1', 2551515, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('beab7f63-8978-0930-4f48-e11bc56fece1', 2551515, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1cd2be3f-8974-a8cf-540b-13969d775a36', 2551515, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1cd2be3f-8974-a8cf-540b-13969d775a36', 2551515, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:00-10:00 Open</p><table><tr><td>Children 17 years old and under</td><td>$$4.99 per person</td></tr><tr><td>Adult</td><td>$$10.00 per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('210d0787-c832-b351-f548-bb54cf543071', 2551515, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
