INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6874b1c5-e09b-71c8-6b88-522f71db7e8b', 2551515, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Ramada by Wyndham Houston InterContinental Airport East');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6874b1c5-e09b-71c8-6b88-522f71db7e8b', 2551515, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '6115 Will Clayton Pkwy, 77338 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6874b1c5-e09b-71c8-6b88-522f71db7e8b', 2551515, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '163');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6874b1c5-e09b-71c8-6b88-522f71db7e8b', 2551515, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại Humble, Ramada by Wyndham Houston Intercontinental Airport East trong khu mua sắm, cách Trung tâm Hội nghị Humble Civic Center 5 phút lái xe và cách Deerbrook Mall 7 phút lái xe. Khách sạn cách Lake Houston 8,5 km và cách Old MacDonald''s Farm (Công viên thiếu nhi) 9,6 km.</p><p>Hãy nhớ đừng bỏ qua cơ hội tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm trung tâm thể dục phục vụ 24 giờ và hồ bơi ngoài trời phục vụ theo mùa. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, cửa hàng quà tặng/sạp báo và dịch vụ cưới.</p><p>Thưởng thức món ăn kiểu Mỹ tại nhà hàng Dolphin Restaurant có quang cảnh hồ bơi và quầy bar/khu lounge. Các bữa ăn cũng được phục vụ tại quán cà phê. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:00 đến 10:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng phục vụ 24 giờ, trả phòng nhanh và dịch vụ giặt ủi/giặt khô. Có kế hoạch tổ chức sự kiện tại Humble? Khách sạn này có khu vực tổ chức rộng 399 mét vuông, bao gồm trung tâm hội nghị và 4 phòng họp. Xe đưa đón sân bay phục vụ miễn phí 24 giờ.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 170 phòng được trang bị máy điều hòa cùng tủ lạnh và lò vi sóng. Phòng được trang bị TV LED 43-inch với các chương trình truyền hình kỹ thuật số để khách giải trí; vá kết nối internet không dây miễn phí giữ bạn luôn kết nối. Phòng tắm riêng với vòi sen/bồn tắm kết hợp có đồ dùng nhà tắm miễn phí và máy sấy tóc. Tiện nghi phòng bao gồm két bảo mật và bàn; bên cạnh đó dịch vụ dọn phòng cũng phục vụ hàng ngày.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('67b57b6c-6c59-cc47-0385-0fd40a69624b', 2551515, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('67b57b6c-6c59-cc47-0385-0fd40a69624b', 2551515, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa536cf-ec09-676e-a44a-fde8ec36234d', 2551515, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa536cf-ec09-676e-a44a-fde8ec36234d', 2551515, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('beab7f63-8978-0930-4f48-e11bc56fece1', 2551515, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('beab7f63-8978-0930-4f48-e11bc56fece1', 2551515, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1cd2be3f-8974-a8cf-540b-13969d775a36', 2551515, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1cd2be3f-8974-a8cf-540b-13969d775a36', 2551515, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>4,99 US$(khoảng 129.607₫) mỗi người</td></tr><tr><td>Người lớn</td><td>10,00 US$(khoảng 259.733₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('210d0787-c832-b351-f548-bb54cf543071', 2551515, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('210d0787-c832-b351-f548-bb54cf543071', 2551515, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 100,00 US$ (khoảng 2.597.331₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
