INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', 'Andersen Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Helgolandsgade 12, Vesterbro/Kongens Enghave, Copenhagen, Hovedstaden, 1653, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '60');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Andersen Boutique Hotel provides flawless service and all the necessary facilities for visitors.Maintain seamless communication using the complimentary Wi-Fi at hotel. Guests can avail parking facilities at the hotel.During your stay at this fantastic hotel, the attentive front desk personnel can provide you with a range of amenities such as concierge service, luggage storage and safety deposit boxes. In search of city''s top entertainment, seek assistance at the hotel''s ticket service and tours for reservations.At the hotel, utilize the on-site dry cleaning service and laundry service to maintain your beloved travel attire fresh, allowing you to bring fewer clothes. Craving relaxation? Make the most of your stay at the Andersen Boutique Hotel with convenient amenities like room service and daily housekeeping at your disposal.At Andersen Boutique Hotel, every guestroom is provided with convenient amenities and fittings to ensure a comfortable stay.Elevate your experience at hotel with the knowledge that certain rooms are equipped with linen service, ensuring a more pleasant stay for you. Certain rooms boast in-room amusement features such as television and cable TV, offering guests an enjoyable stay.In select rooms within the hotel, bottled water, a coffee or tea maker and mini bar is available to cater to your requirements when desired.In the hotel, certain guest bathrooms come equipped with essential bathroom amenities, such as a hair dryer, toiletries and bathrobes, ensuring a comfortable stay for guests. Begin your day with a scrumptious on-site breakfast available each morning at Andersen Boutique Hotel.Begin your day feeling refreshed and invigorated as you enjoy a delightful cup of quality coffee available at the cafe situated within the hotel. Enjoy an entertaining evening with your fellow travelers at the hotel''s bar.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4517351c-7d6e-2f25-e358-18e348d233e2', 2564763, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4517351c-7d6e-2f25-e358-18e348d233e2', 2564763, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 14:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('639f3eab-3ad6-9c38-9579-ca01d91fa858', 2564763, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('639f3eab-3ad6-9c38-9579-ca01d91fa858', 2564763, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
