INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d096e67f-e5fe-f0a5-b9c0-1ea510553e07', 2564763, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Continental, Gluten-free, Vegetarian</p><table><tr><td>Adult</td><td>DKK 225 (approx. $34.28) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
