INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Andersen Boutique Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', 'Andersen Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Helgolandsgade 12, Vesterbro/Kongens Enghave, 1653 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '60');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ecd1d644-12b6-bf44-24ac-a6106232fde8', 2564763, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc trong quận Vesterbro thời thượng, khách sạn boutique này chỉ cách Ga Trung tâm Copenhagen 200 m. Nơi đây cung cấp các phòng nghỉ được thiết kế theo phong cách hiện đại với TV màn hình LED và Wi-Fi miễn phí.</p><p>Andersen Boutique Hotel cung cấp các phòng đầy phong cách được trang trí bởi công ty thiết kế từng đoạt giải thưởng Designers Guild. Mỗi phòng đều có cửa sổ cách âm, vòi sen và đồ vệ sinh cá nhân hiệu Molton Brown. Toàn bộ các phòng được trang bị minibar, bàn làm việc và két an toàn.</p><p>Rượu mùi Ý, cà phê đặc sản và tuyển chọn các loại trà từ quán trà nổi tiếng Østerlandsk Thehus được cung cấp tại sảnh khách thời thượng. Du khách cũng có thể thư giãn trên sân hiên hoặc thuê xe đạp và khám phá thành phố.</p><p>Các phòng trưng bày, nhà hàng và quán bar của khu Kødbyen (Quận Meatpacking) nổi tiếng nằm cách nơi này 5 phút tản bộ. Công viên Giải trí Tivoli Gardens nằm trong bán kính 7 phút đi bộ từ khách sạn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4517351c-7d6e-2f25-e358-18e348d233e2', 2564763, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4517351c-7d6e-2f25-e358-18e348d233e2', 2564763, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 14:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('639f3eab-3ad6-9c38-9579-ca01d91fa858', 2564763, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('639f3eab-3ad6-9c38-9579-ca01d91fa858', 2564763, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6c6a7e77-05b3-4332-f8f1-1ef26084afe5', 2564763, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6c6a7e77-05b3-4332-f8f1-1ef26084afe5', 2564763, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d096e67f-e5fe-f0a5-b9c0-1ea510553e07', 2564763, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d096e67f-e5fe-f0a5-b9c0-1ea510553e07', 2564763, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Đại lục, Không Gluten, Chay</p><table><tr><td>Người lớn</td><td>225 DKK(khoảng 889.833₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5a78e51d-7c5f-cdb8-6201-ce905733b13e', 2564763, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
