INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('87d71188-9bcf-98bb-2ada-daf6192defdd', 2564763, 'POLICY', 'ageLimit', 'vi', 'policy_title', 'Giới hạn độ tuổi');
