INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'City Hotel Nebo');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Istedgade 6, Vesterbro/Kongens Enghave, Copenhagen, Hovedstaden, 1650, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '88');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located in Copenhagen (Vesterbro), City Hotel Nebo is within a 10-minute walk of Tivoli Gardens and Strøget. This hotel is 0.6 mi (1 km) from Ny Carlsberg Glyptotek and 0.8 mi (1.3 km) from Christiansborg Palace.</p><p>Enjoy recreation amenities such as bicycles to rent or take in the view from a garden. Additional features at this hotel include complimentary wireless internet access, a television in a common area, and tour/ticket assistance.</p><p>Buffet breakfasts are available daily from 6:30 AM to 10:00 AM for a fee.</p><p>Featured amenities include dry cleaning/laundry services, a 24-hour front desk, and luggage storage.</p><p>Stay in one of 84 guestrooms featuring flat-screen televisions. Complimentary wireless internet access keeps you connected, and digital programming is available for your entertainment. Conveniences include safes, and housekeeping is provided daily.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aafc8231-d2fe-8612-36c0-9364e39dbefb', 2564765, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aafc8231-d2fe-8612-36c0-9364e39dbefb', 2564765, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 14:00</strong></p><p>Check-out: <strong>00:30–11:00</strong></p><p>Front desk hours: 24/7</p><p>If you will arrive outside of check-in hours, contact the property 1 day in advance by phone</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5914afb6-48a3-2ab2-9965-ac00a6c31273', 2564765, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5914afb6-48a3-2ab2-9965-ac00a6c31273', 2564765, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc15e52e-b56c-48db-0de6-1506e4e2ece1', 2564765, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc15e52e-b56c-48db-0de6-1506e4e2ece1', 2564765, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a79c8934-fc1f-75a4-517d-c4a3cb43f4da', 2564765, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a79c8934-fc1f-75a4-517d-c4a3cb43f4da', 2564765, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 06:30-10:00 Open</p><table><tr><td>Adult</td><td>DKK 110 (approx. $16.76) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
