INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'City Hotel Nebo');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Istedgade 6, Vesterbro/Kongens Enghave, 1650 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '88');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b265a626-9241-a981-1c3f-9ebaf555eb44', 2564765, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại Vesterbro, Copenhagen, City Hotel Nebo cách Công viên Tivoli và Phố Strøget 10 phút đi bộ. Khách sạn cách Ny Carlsberg Glyptotek 1 km và cách Cung điện Christiansborg 1,3 km.</p><p>Hãy tận hưởng những tiện nghi, dịch vụ thư giãn như xe đạp cho thuê hay chỉ đơn giản là ngắm cảnh từ vườn. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, TV ở khu vực chung và dịch vụ hỗ trợ tour/vé du lịch.</p><p>Khách có thể dùng bữa sáng buffet (có phụ phí) từ 6:30 đến 10:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm dịch vụ giặt ủi/giặt khô, quầy tiếp tân phục vụ 24 giờ/ngày và dịch vụ trông giữ/bảo quản hành lý.</p><p>Hãy nghỉ tại một trong 84 phòng được trang bị TV màn hình phẳng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình kỹ thuật số sẽ mang đến những phút giây giải trí thoải mái. Phòng được trang bị két bảo mật; và dịch vụ dọn phòng phục vụ hàng ngày.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aafc8231-d2fe-8612-36c0-9364e39dbefb', 2564765, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aafc8231-d2fe-8612-36c0-9364e39dbefb', 2564765, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 14:00</strong></p><p>Trả phòng: <strong>00:30–11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn đến chỗ nghỉ ngoài giờ nhận phòng, vui lòng liên lạc với họ qua điện thoại trước một ngày</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5914afb6-48a3-2ab2-9965-ac00a6c31273', 2564765, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5914afb6-48a3-2ab2-9965-ac00a6c31273', 2564765, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc15e52e-b56c-48db-0de6-1506e4e2ece1', 2564765, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dc15e52e-b56c-48db-0de6-1506e4e2ece1', 2564765, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a79c8934-fc1f-75a4-517d-c4a3cb43f4da', 2564765, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a79c8934-fc1f-75a4-517d-c4a3cb43f4da', 2564765, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:00 Đang Mở</p><table><tr><td>Người lớn</td><td>110 DKK(khoảng 435.030₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9138b4e5-c9c4-c433-5d27-1409cec6e4d3', 2564765, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9138b4e5-c9c4-c433-5d27-1409cec6e4d3', 2564765, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Không được phép mang theo thú cưng</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('904accc7-a952-80ef-4317-d4f00013f25f', 2564765, 'POLICY', 'ageLimit', 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('904accc7-a952-80ef-4317-d4f00013f25f', 2564765, 'POLICY', 'ageLimit', 'vi', 'policy_content', '<p>Khách chính nhận phòng phải từ 18 tuổi trở lên.</p>');
