INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05e898ec-9742-707b-d6c4-17f715a8b4d3', 2895354, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hotel Zaza Houston Museum District');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05e898ec-9742-707b-d6c4-17f715a8b4d3', 2895354, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '5701 Main St, Houston, Texas, 77005');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05e898ec-9742-707b-d6c4-17f715a8b4d3', 2895354, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '315');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05e898ec-9742-707b-d6c4-17f715a8b4d3', 2895354, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>A stay at Hotel Zaza Houston Museum District places you in the heart of Houston, within a 15-minute walk of Rice University and Houston Zoo. This luxury hotel is 1.6 mi (2.6 km) from MD Anderson Cancer Center and 3 mi (4.8 km) from Toyota Center.</p><p>Relax at the full-service spa, where you can enjoy massages, body treatments, and facials. You can take advantage of recreational amenities such as an outdoor pool, a sauna, and a 24-hour fitness center. Additional features at this hotel include complimentary wireless internet access, concierge services, and wedding services. Getting to nearby attractions is a breeze with the complimentary area shuttle that operates within 3 miles.</p><p>Enjoy a meal at the restaurant, or stay in and take advantage of the hotel''s room service (during limited hours). Relax with your favorite drink at the bar/lounge or the poolside bar. Cooked-to-order breakfasts are available daily from 6:30 AM to 10:30 AM for a fee.</p><p>Featured amenities include complimentary wired internet access, a 24-hour business center, and dry cleaning/laundry services.</p><p>Make yourself at home in one of the 315 individually decorated guestrooms, featuring minibars and flat-screen televisions. Your pillowtop bed comes with premium bedding. Complimentary wired and wireless internet access keeps you connected, and cable programming provides entertainment. Private bathrooms with bathtubs or showers feature designer toiletries and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a1765be8-8ad4-dd62-d2e0-04b01eee967d', 2895354, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a1765be8-8ad4-dd62-d2e0-04b01eee967d', 2895354, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 16:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p><p>If you plan to arrive after 01:00 in the morning on the day following your check-in date, contact the property in advance</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('10bef8de-e62c-2a57-c77e-4ba006e672e1', 2895354, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('10bef8de-e62c-2a57-c77e-4ba006e672e1', 2895354, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c8ffdd96-4257-fba1-2477-2e688c3525c5', 2895354, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c8ffdd96-4257-fba1-2477-2e688c3525c5', 2895354, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs can be added. Extra bed policies vary according to room type. Please refer to the relevant room type policy.</p><p>Fees for extra beds and cribs are not included in the total and must be paid at the hotel.</p><table><tr><td>Children 2 years old and under</td><td>Extra crib: Free</td></tr></table>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7c4e3323-c320-7ee0-a155-7774831fffaa', 2895354, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7c4e3323-c320-7ee0-a155-7774831fffaa', 2895354, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: A la carte</p><p>Opening hours: [Mon - Sun] 06:30-10:30 Open</p><p>Price for extra breakfasts: Varies based on the food ordered</p><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e34c0398-c847-7caa-c0fd-f33ef2786d6d', 2895354, 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e34c0398-c847-7caa-c0fd-f33ef2786d6d', 2895354, 'POLICY', 'pet', 'en', 'policy_content', '<p>Pets are allowed on request</p><p>Types of pets allowed: dogs, cats</p><p>Fee: $150.00 per room per stay</p>');
