INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05e898ec-9742-707b-d6c4-17f715a8b4d3', 2895354, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hotel Zaza Houston Museum District');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05e898ec-9742-707b-d6c4-17f715a8b4d3', 2895354, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '5701 Main St, 77005 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05e898ec-9742-707b-d6c4-17f715a8b4d3', 2895354, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '315');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('05e898ec-9742-707b-d6c4-17f715a8b4d3', 2895354, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Hotel Zaza Houston Museum District ở trung tâm Houston, chỉ cách Đại học Rice và Sở thú Houston 15 phút đi bộ. Khách sạn sang trọng này cách Viện Ung thư MD Anderson 2,6 km và cách Trung tâm Toyota 4,8 km.</p><p>Hãy thư giãn tại khu spa phục vụ đầy đủ các liệu pháp và tận hưởng các dịch vụ massage, trị liệu toàn thân và chăm sóc da mặt. Đừng bỏ qua cơ hội tận hưởng những dịch vụ, tiện nghi thể thao, giải trí như hồ bơi ngoài trời, phòng tắm hơi hay trung tâm thể dục phục vụ 24 giờ. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và dịch vụ cưới. Những chuyến tham quan các thắng cảnh trong vùng sẽ trở nên dễ dàng hơn bao giờ hết với dịch vụ xe đưa đón phục vụ miễn phí trong phạm vi 3 dặm.</p><p>Khách có thể lựa chọn dùng bữa tại nhà hàng của Khách sạn hoặc nghỉ lại trong phòng và thưởng thức những món ăn ngon với dịch vụ phòng (có giới hạn thời gian). Hãy thư giãn cùng với ly nước giải khát yêu thích của mình tại quầy bar/khu lounge hoặc quầy bar bên hồ bơi. Khách có thể dùng bữa sáng nấu theo yêu cầu (có phụ phí) từ 6:30 đến 10:30 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm truy cập Internet tốc độ cao (có dây) miễn phí, trung tâm dịch vụ văn phòng phục vụ 24 giờ và dịch vụ giặt ủi/giặt khô.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 315 phòng trang trí khác biệt với minibar và TV màn hình phẳng. Giường nệm có lớp đệm bông được trang bị bộ đồ giường cao cấp. Truy cập internet có dây và không dây miễn phí giúp bạn luôn kết nối; và các chương trình truyền hình cáp sẽ mang đến những giây phút giải trí thoải mái. Phòng tắm riêng với bồn tắm hoặc buồng tắm vòi sen có đồ dùng nhà tắm được thiết kế riêng và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a1765be8-8ad4-dd62-d2e0-04b01eee967d', 2895354, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a1765be8-8ad4-dd62-d2e0-04b01eee967d', 2895354, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 16:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn dự định sẽ đến sau 01:00 vào buổi sáng của ngày sau ngày nhận phòng, vui lòng liên hệ trước với cơ sở lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('10bef8de-e62c-2a57-c77e-4ba006e672e1', 2895354, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('10bef8de-e62c-2a57-c77e-4ba006e672e1', 2895354, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c8ffdd96-4257-fba1-2477-2e688c3525c5', 2895354, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c8ffdd96-4257-fba1-2477-2e688c3525c5', 2895354, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều có thể bổ sung cũi. Chính sách về giường phụ khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</p><p>Phí giường phụ và cũi chưa được bao gồm trong tổng giá và phải được thanh toán tại khách sạn.</p><table><tr><td>Trẻ em 2 tuổi trở xuống</td><td>Thêm cũi: Miễn phí</td></tr></table>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7c4e3323-c320-7ee0-a155-7774831fffaa', 2895354, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7c4e3323-c320-7ee0-a155-7774831fffaa', 2895354, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Gọi món</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:30 Đang Mở</p><p>Giá thêm bữa sáng: Phụ thuộc vào món bạn đặt</p><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e34c0398-c847-7caa-c0fd-f33ef2786d6d', 2895354, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e34c0398-c847-7caa-c0fd-f33ef2786d6d', 2895354, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó, mèo</p><p>Phí: 150,00 US$ (khoảng 3.895.997₫)/phòng/lần lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8084a917-9d30-9e4b-b306-6143e6441de5', 2895354, 'POLICY', 'serviceAnimal', 'vi', 'policy_title', 'Động vật hỗ trợ');
