INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Savoy Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Vesterbrogade 34, Vesterbro/Kongens Enghave, Copenhagen, Hovedstaden, 1620, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '66');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Savoy Hotel, you''ll be centrally located in Copenhagen, a short 8-minute walk from Tivoli Gardens and 11 minutes by foot from City Hall Square. This hotel is 0.9 mi (1.5 km) from Christiansborg Palace and 1 mi (1.6 km) from Strøget.</p><p>Enjoy recreation amenities such as bicycles to rent or take in the view from a garden. Additional amenities at this hotel include complimentary wireless internet access, concierge services, and a television in a common area.</p><p>Satisfy your appetite at the hotel''s coffee shop/cafe, or stay in and take advantage of the room service (during limited hours). Quench your thirst with your favorite drink at the bar/lounge. To-go breakfasts are served on weekdays from 7:00 AM to 11:00 AM and on weekends from 7:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include a business center, express check-out, and a 24-hour front desk.</p><p>Stay in one of 66 guestrooms featuring Smart televisions. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Bathrooms have complimentary toiletries and hair dryers. Conveniences include blackout drapes/curtains, and housekeeping is provided once per stay.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5c1bb6ef-0a36-f345-7013-6c38fe0c8a29', 3064270, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5c1bb6ef-0a36-f345-7013-6c38fe0c8a29', 3064270, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>00:00–11:00</strong></p><p>Front desk hours: 24/7</p><p>Self check-in: Contact the property for instructions on how to obtain the card/keys</p><p>The property will provide check-in details after booking</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45501adf-c485-6a5f-48a6-bad15d578fcb', 3064270, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45501adf-c485-6a5f-48a6-bad15d578fcb', 3064270, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
