INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd4b54a5-e42f-ab02-48e5-858f1b3e8d27', 3064270, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs and extra beds cannot be added.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15e58c4e-a017-e1ca-53a5-271ca451c97d', 3064270, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15e58c4e-a017-e1ca-53a5-271ca451c97d', 3064270, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Boxed/packaged food</p><p>Cuisine: Continental</p><table><tr><td>Children 17 years old and under</td><td>DKK 200 (approx. $30.47) per person</td></tr><tr><td>Adult</td><td>DKK 200 (approx. $30.47) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
