INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Savoy Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Vesterbrogade 34, Vesterbro/Kongens Enghave, 1620 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '66');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('42924caa-f438-4516-0c89-7290c66e6cd9', 3064270, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, Savoy Hotel chỉ cách Công viên Tivoli 8 phút đi bộ và Quảng trường Tòa thị chính 11 phút đi bộ. Khách sạn cách Cung điện Christiansborg 1,5 km và cách Phố Strøget 1,6 km.</p><p>Hãy tận hưởng những tiện nghi, dịch vụ thư giãn như xe đạp cho thuê hay chỉ đơn giản là ngắm cảnh từ vườn. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và TV ở khu vực chung.</p><p>Khách có thể dùng bữa tại quán cà phê của Khách sạn hoặc thưởng thức những món ăn ngon tại phòng với dịch vụ phòng (có giới hạn thời gian). Đập tan cơn khát với đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng mang đi các ngày trong tuần từ 7:00 đến 11:00 và cuối tuần (phụ phí) từ 7:00 đến 11:00.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng, trả phòng nhanh và quầy tiếp tân phục vụ 24 giờ/ngày.</p><p>Hãy nghỉ tại một trong 66 phòng được trang bị Smart TV. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm có đồ dùng nhà tắm miễn phí và máy sấy tóc. Phòng được trang bị màn/rèm cản sáng; và dịch vụ dọn phòng phục vụ mỗi lần ở.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5c1bb6ef-0a36-f345-7013-6c38fe0c8a29', 3064270, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5c1bb6ef-0a36-f345-7013-6c38fe0c8a29', 3064270, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>00:00–11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Tự nhận phòng: Liên lạc với chỗ nghỉ để được hướng dẫn cách lấy thẻ/chìa khóa</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45501adf-c485-6a5f-48a6-bad15d578fcb', 3064270, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45501adf-c485-6a5f-48a6-bad15d578fcb', 3064270, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd4b54a5-e42f-ab02-48e5-858f1b3e8d27', 3064270, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('dd4b54a5-e42f-ab02-48e5-858f1b3e8d27', 3064270, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15e58c4e-a017-e1ca-53a5-271ca451c97d', 3064270, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15e58c4e-a017-e1ca-53a5-271ca451c97d', 3064270, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Đồ ăn đóng hộp/gói</p><p>Ẩm thực: Đại lục</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>200 DKK(khoảng 790.963₫) mỗi người</td></tr><tr><td>Người lớn</td><td>200 DKK(khoảng 790.963₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e9ef298d-977e-5ad9-3bf5-3a9930fdf43a', 3064270, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
