INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('646b4f17-51e9-7c87-a94b-1e41e12cda24', 5482039, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Club Quarters Hotel in Houston');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('646b4f17-51e9-7c87-a94b-1e41e12cda24', 5482039, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '1085 Rusk St, Houston, Texas, 77002');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('646b4f17-51e9-7c87-a94b-1e41e12cda24', 5482039, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '306');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('646b4f17-51e9-7c87-a94b-1e41e12cda24', 5482039, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Never is the term melting pot better applied than to the city of Houston. Thanks to its incredible cultural diversity this city offers a taste of the world in the heart of Texas as you will discover in our Downtown neighborhood. Walk through the doors of our historic facade and you will find bright contemporary rooms with all the comforts you need. Step outside and you will be greeted by a city that is confident it can offer something new even for the most seasoned Houston visitor.</p><p>Complimentary high-speed Wi-Fi</p><p>Apple Wallet and Google Wallet for access to room and hotel spaces</p><p>Self-check-in kiosks</p><p>Guest Request Closets providing amenities needed during your stay</p><p>Hydration Stations with complimentary bottled water</p><p>Fitness Room with Peloton bikes</p><p>Laundry facilities</p><p>Club Living Room - seating; workspaces; wireless printing; complimentary coffee</p><p>Off-site parking</p><p>Meeting and event space</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4e977762-c11a-fa52-5252-9d01614cfb05', 5482039, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4e977762-c11a-fa52-5252-9d01614cfb05', 5482039, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p><p>If you will arrive outside of check-in hours, contact the property in advance</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('11ef77e4-b0d2-3dd3-74c6-d51af19899ed', 5482039, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('11ef77e4-b0d2-3dd3-74c6-d51af19899ed', 5482039, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
