INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('646b4f17-51e9-7c87-a94b-1e41e12cda24', 5482039, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Club Quarters Hotel in Houston');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('646b4f17-51e9-7c87-a94b-1e41e12cda24', 5482039, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '1085 Rusk St, 77002 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('646b4f17-51e9-7c87-a94b-1e41e12cda24', 5482039, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '306');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('646b4f17-51e9-7c87-a94b-1e41e12cda24', 5482039, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Club Quarters Hotel Downtown, Houston ở trung tâm Houston, chỉ cách Công viên Daikin và Trung tâm Hội nghị George R. Brown 15 phút đi bộ. Khách sạn này cách Trung tâm Toyota 1,2 km và cách Downtown Aquarium 1 km.</p><p>Đừng bỏ qua cơ hội tận hưởng những dịch vụ thư giãn, giải trí như trung tâm thể dục phục vụ 24 giờ, hay những tiện nghi khác như quyền truy cập Internet không dây miễn phí và dịch vụ tư vấn/hỗ trợ khách. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm TV ở khu vực chung, quyền sử dụng phòng tập thể dục lân cận với giá ưu đãi và phòng đại tiệc.</p><p>Thưởng thức đặc sản vùng tại bistro Table 7 Bistro có quầy bar/khu lounge hoặc nghỉ lại trong phòng và thưởng thức những bữa ăn ngon với dịch vụ phòng (có giới hạn thời gian). Khách có thể dùng bữa sáng đầy đủ các ngày trong tuần từ 7:00 đến 10:00 và cuối tuần (phụ phí) từ 7:30 đến 9:00.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng phục vụ 24 giờ, nhận phòng nhanh và trả phòng nhanh.</p><p>Hãy nghỉ tại một trong 382 phòng được trang bị TV LCD. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình kỹ thuật số sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm được trang bị bồn tắm hoặc buồng tắm vòi sen, máy sấy tóc và bàn chải và kem đánh răng (theo yêu cầu). Tiện nghi phòng bao gồm két bảo mật và bàn; bên cạnh đó dịch vụ dọn phòng cũng phục vụ dịch vụ dọn phòng (theo yêu cầu).</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4e977762-c11a-fa52-5252-9d01614cfb05', 5482039, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4e977762-c11a-fa52-5252-9d01614cfb05', 5482039, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('11ef77e4-b0d2-3dd3-74c6-d51af19899ed', 5482039, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('11ef77e4-b0d2-3dd3-74c6-d51af19899ed', 5482039, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a9be3a6c-5232-1a44-2fe2-58f7a9eed22a', 5482039, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a9be3a6c-5232-1a44-2fe2-58f7a9eed22a', 5482039, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('26ec393d-af02-a6fa-81a3-785cc184dcca', 5482039, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('26ec393d-af02-a6fa-81a3-785cc184dcca', 5482039, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Thực đơn cố định</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 07:00-10:00 Đang Mở [Thứ 7 - CN] 07:30-09:00 Đang Mở</p><table><tr><td>Người lớn</td><td>17,00 US$(khoảng 441.546₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d073d199-869d-b70f-9520-7523c3972517', 5482039, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d073d199-869d-b70f-9520-7523c3972517', 5482039, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 50,00 US$ (khoảng 1.298.666₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('da2afd48-6c8b-b85d-4c82-aa11f9daaa24', 5482039, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
