INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('02e36a33-35be-aa83-1f72-927293467eb3', 6155961, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '1777 Walker St, Houston, Texas, 77010');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('02e36a33-35be-aa83-1f72-927293467eb3', 6155961, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '1001');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('02e36a33-35be-aa83-1f72-927293467eb3', 6155961, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Where sophistication meets Southern hospitality, this newly refreshed architectural gem blends exceptional service and modern style for business and leisure travelers alike. As a premier city center Houston hotel, we offer more than 150,000 square feet of stacked, refreshed event space, including grand ballrooms, meeting rooms, a rooftop terrace, and a pavilion. Connected directly to the George R. Brown Convention Center, our property is a leading Houston Convention Center hotel. Recharge in spacious, redesigned guest rooms and suites with panoramic city views and world-class amenities. As a standout downtown Houston hotel, we feature a rooftop Texas lazy river and infinity pool, plus Pure Spa Houston and an expansive fitness center. Enjoy exceptional dining at Biggio''s Sports Bar and Xochi by Hugo Ortega, then explore nearby attractions including Discovery Green, Daikin Park, and Toyota Center.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('04f73358-8a43-7a4e-98c4-335d19437644', 6155961, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('04f73358-8a43-7a4e-98c4-335d19437644', 6155961, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 16:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p><p>If you plan to arrive after 16:00 on your check-in day, contact the property in advance.At the same time, please provide your check-in time</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ad751ea9-abb6-78bb-6117-e29af179bc6b', 6155961, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ad751ea9-abb6-78bb-6117-e29af179bc6b', 6155961, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bb39a91d-8ac9-aac1-6ef0-227e1d2705c6', 6155961, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bb39a91d-8ac9-aac1-6ef0-227e1d2705c6', 6155961, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d1a3fd1a-b932-b760-4262-21f4d6f1bd3e', 6155961, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d1a3fd1a-b932-b760-4262-21f4d6f1bd3e', 6155961, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 06:30-11:00 Open</p><table><tr><td>Adult</td><td>$$26.00 per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('949f96d1-6b76-764a-af92-d95b2db41112', 6155961, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('949f96d1-6b76-764a-af92-d95b2db41112', 6155961, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>The deposit is determined based on the duration of your stay. The charge is $100.00 per night.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards and debit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment on the day of check-out.</strong></p>');
