INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('02e36a33-35be-aa83-1f72-927293467eb3', 6155961, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Marriott Marquis Houston');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('02e36a33-35be-aa83-1f72-927293467eb3', 6155961, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '1777 Walker St, 77010 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('02e36a33-35be-aa83-1f72-927293467eb3', 6155961, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '1001');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('02e36a33-35be-aa83-1f72-927293467eb3', 6155961, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Houston, Marriott Marquis Houston cách Công viên Discovery Green vài bước và cách Công viên Daikin 10 phút đi bộ. Khách sạn spa này cách Trung tâm Toyota 0,7 km và cách Trung tâm Hội nghị George R. Brown 1 km.</p><p>Hãy để mình được chăm sóc thật đặc biệt khi ghé đến khu spa, với những dịch vụ massage, trị liệu toàn thân và chăm sóc da mặt. Chắc chắn bạn sẽ yêu thích những dịch vụ, tiện nghi thể thao, giải trí, bao gồm 2 hồ bơi ngoài trời, dòng sông lười và trung tâm thể dục. Khách sạn này còn có quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và cửa hàng quà tặng/sạp báo.</p><p>Khách có thể thưởng thức món ăn kiểu Mỹ tại Biggio''s, một trong 4 nhà hàng ở Khách sạn hoặc nghỉ lại trong phòng và tận hưởng dịch vụ phòng 24 giờ. Thức ăn nhẹ cũng có ở quán cà phê. Thư giãn tạo quầy bar bên hồ bơi hoặc một trong 2 quầy bar/khu lounge với những ly nước mát. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 6:30 đến 11:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng, nhận phòng nhanh và trả phòng nhanh. Khách sạn này có 52 phòng họp để phục vụ các chương trình hội thảo, sự kiện.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 1000 phòng được trang bị tủ lạnh và TV LED. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây (phụ phí); trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng với buồng tắm vòi sen có đồ dùng nhà tắm miễn phí và máy sấy tóc. Các tiện nghi phòng bao gồm két bảo mật và bàn, cùng điện thoại với điện thoại nội vùng miễn phí.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('04f73358-8a43-7a4e-98c4-335d19437644', 6155961, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('04f73358-8a43-7a4e-98c4-335d19437644', 6155961, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 16:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn dự định sẽ đến sau 16:00 vào ngày nhận phòng, vui lòng liên hệ trước với cơ sở lưu trú.Đồng thời, vui lòng cung cấp giờ nhận phòng của bạn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ad751ea9-abb6-78bb-6117-e29af179bc6b', 6155961, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ad751ea9-abb6-78bb-6117-e29af179bc6b', 6155961, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bb39a91d-8ac9-aac1-6ef0-227e1d2705c6', 6155961, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bb39a91d-8ac9-aac1-6ef0-227e1d2705c6', 6155961, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d1a3fd1a-b932-b760-4262-21f4d6f1bd3e', 6155961, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d1a3fd1a-b932-b760-4262-21f4d6f1bd3e', 6155961, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-11:00 Đang Mở</p><table><tr><td>Người lớn</td><td>26,00 US$(khoảng 674.909₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('949f96d1-6b76-764a-af92-d95b2db41112', 6155961, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('949f96d1-6b76-764a-af92-d95b2db41112', 6155961, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khoản tiền cọc được tính dựa trên độ dài lưu trú của bạn. Mức phí là 100,00 US$ (khoảng 2.595.802₫)/đêm.</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng và thẻ ghi nợ</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Vào ngày trả phòng.</strong></p>');
