INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hilton Garden Inn Hong Kong Mongkok');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '香港旺角希爾頓花園酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'No.2 Soy Street, Mongkok, Kowloon, Yau Tsim Mong District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '258');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Hilton Garden Inn Hong Kong Mongkok provides business and leisure guests upscale, enjoy our summer season rooftop pool with affordable accommodations and modern amenities for an experience that is simply on another level. Our brand goal to make each guest stay better and brighter.</p><p>Hotel is just a 7-minute walk from the Mongkok or Yaumatei MTR station, and about a 10-minute drive to the West Kowloon High-Speed Rail Station. It is located near popular dining options and renowned tourist attractions are within close proximity, such as the Ladies Market, known for selling souvenirs, the Goldfish Market, often referred to as the "Aquarium of the City," and Sneaker Street, renowned for its limited edition sneakers.</p><p>Our signature pillar-less Grand Ballroom has floor-to-ceiling panoramic windows with natural sunlight flowing during the event. The four meters high ceiling and the complimentary built in LED screens are our guests all-time favorites.</p><p>Dine on a selection of Western and Chinese dishes at our on-site restaurant Eagle’s Garden, open for all day dining. Let''s stay and embark on a nostalgic journey to Hong Kong now!</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d6607fd-e040-fd48-5c31-3cec74e6bb62', 6371974, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d6607fd-e040-fd48-5c31-3cec74e6bb62', 6371974, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('97003d08-7db5-bed7-0594-6f5cd023f260', 6371974, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('97003d08-7db5-bed7-0594-6f5cd023f260', 6371974, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Children between 0 and 11 years old can stay for free if no extra bed is needed.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('866352d1-eb03-c9b4-aebd-8f878b5246f6', 6371974, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('866352d1-eb03-c9b4-aebd-8f878b5246f6', 6371974, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs and extra beds cannot be added.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b9a92656-910a-23e8-8273-9c52ab26efeb', 6371974, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b9a92656-910a-23e8-8273-9c52ab26efeb', 6371974, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 06:30-10:00 Open</p><table><tr><td>Children 3 years old and under</td><td>Free</td></tr><tr><td>Children 4–17 years old</td><td>HK$218.00 (approx. $27.79) per person</td></tr><tr><td>Adult</td><td>HK$218.00 (approx. $27.79) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ef01bcb9-a170-72f8-217f-3582ee5e0bfb', 6371974, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ef01bcb9-a170-72f8-217f-3582ee5e0bfb', 6371974, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of HK$1,000.00 (approx. $127.49) is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts cash and credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment .</strong></p>');
