INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hilton Garden Inn Hong Kong Mongkok');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '香港旺角希爾頓花園酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'No.2 Soy Street, Mongkok, Kowloon, Yau Tsim Mong District, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '258');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('50d4bf92-b7b8-8512-93ea-4330e7878f57', 6371974, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Hilton Garden Inn Hong Kong Mongkok provides business and leisure guests upscale, enjoy our summer season rooftop pool with affordable accommodations and modern amenities for an experience that is simply on another level. Our brand goal to make each guest stay better and brighter.</p><p>Hotel is just a 7-minute walk from the Mongkok or Yaumatei MTR station, and about a 10-minute drive to the West Kowloon High-Speed Rail Station. It is located near popular dining options and renowned tourist attractions are within close proximity, such as the Ladies Market, known for selling souvenirs, the Goldfish Market, often referred to as the "Aquarium of the City," and Sneaker Street, renowned for its limited edition sneakers.</p><p>Our signature pillar-less Grand Ballroom has floor-to-ceiling panoramic windows with natural sunlight flowing during the event. The four meters high ceiling and the complimentary built in LED screens are our guests all-time favorites.</p><p>Dine on a selection of Western and Chinese dishes at our on-site restaurant Eagle’s Garden, open for all day dining. Let''s stay and embark on a nostalgic journey to Hong Kong now!</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d6607fd-e040-fd48-5c31-3cec74e6bb62', 6371974, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d6607fd-e040-fd48-5c31-3cec74e6bb62', 6371974, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('97003d08-7db5-bed7-0594-6f5cd023f260', 6371974, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('97003d08-7db5-bed7-0594-6f5cd023f260', 6371974, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 11 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('866352d1-eb03-c9b4-aebd-8f878b5246f6', 6371974, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('866352d1-eb03-c9b4-aebd-8f878b5246f6', 6371974, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b9a92656-910a-23e8-8273-9c52ab26efeb', 6371974, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b9a92656-910a-23e8-8273-9c52ab26efeb', 6371974, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:00 Đang Mở</p><table><tr><td>Trẻ em 3 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 4–17 tuổi</td><td>218,00 HK$(khoảng 721.441₫) mỗi người</td></tr><tr><td>Người lớn</td><td>218,00 HK$(khoảng 721.441₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ef01bcb9-a170-72f8-217f-3582ee5e0bfb', 6371974, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ef01bcb9-a170-72f8-217f-3582ee5e0bfb', 6371974, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 1.000,00 HK$ (khoảng 3.309.362₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận tiền mặt và thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu .</strong></p>');
