INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hertz Hotel by onyu stay');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '호텔 헤르츠');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '44 Donhwamun-ro 11-gil, Jongno-gu, Seoul, 03133, South Korea');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '43');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located in Seoul (Jongno-gu), HERTZ Hotel is within a 15-minute walk of Gwangjang Market and Gyeongbokgung Palace. This hotel is 0.8 mi (1.3 km) from Bukchon Hanok Village and 1 mi (1.7 km) from Myeongdong Street.</p><p>The front desk is staffed during limited hours.</p><p>Make yourself at home in one of the 44 guestrooms. Complimentary wireless internet access is available to keep you connected. Bathrooms have bathtubs or showers and slippers. Conveniences include complimentary bottled water, and housekeeping is provided on request.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0dee82e5-7660-02f6-ef6f-758b13c8a10e', 7019255, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0dee82e5-7660-02f6-ef6f-758b13c8a10e', 7019255, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 16:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: [Mon-Sun]09:00–23:00</p><p>The host or staff will greet you upon arrival</p><p>Self check-in: Contact the property for instructions on how to obtain the card/keys</p><p>The property will provide check-in details after booking</p><p>If you plan to arrive after 23:00 on your check-in day, contact the property in advance by email/phone</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('96ef553e-16f3-b0b4-b092-451c9e224fde', 7019255, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('96ef553e-16f3-b0b4-b092-451c9e224fde', 7019255, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
