INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hertz Hotel by onyu stay');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '호텔 헤르츠');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '44 Donhwamun-ro 11-gil, Jongno-gu, 03133 Seoul, Hàn Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '43');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e44f4bdf-b411-d03b-5abf-5f76081983fe', 7019255, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>HERTZ Hotel ở Jongno-gu, Seoul, cách Chợ Gwangjang và Cung điện Gyeongbokgung 15 phút đi bộ. Khách sạn này cách Làng Bukchon Hanok 1,3 km và cách Khu mua sắm Myeongdong Street 1,7 km.</p><p>Nhân viên lễ tân chỉ phục vụ trong thời gian nhất định.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 44 phòng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Các phòng tắm được trang bị bồn tắm hoặc buồng tắm vòi sen và dép đi trong nhà. Phòng được trang bị nước đóng chai miễn phí; và dịch vụ dọn phòng phục vụ dịch vụ dọn phòng (theo yêu cầu).</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0dee82e5-7660-02f6-ef6f-758b13c8a10e', 7019255, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0dee82e5-7660-02f6-ef6f-758b13c8a10e', 7019255, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 16:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: [Thứ 2-CN]09:00–23:00</p><p>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</p><p>Tự nhận phòng: Liên lạc với chỗ nghỉ để được hướng dẫn cách lấy thẻ/chìa khóa</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p><p>Nếu bạn dự định sẽ đến sau 23:00 vào ngày nhận phòng, vui lòng liên hệ trước với cơ sở lưu trú qua email/điện thoại</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('96ef553e-16f3-b0b4-b092-451c9e224fde', 7019255, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('96ef553e-16f3-b0b4-b092-451c9e224fde', 7019255, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5d84971d-a47b-14f4-9627-5d84877a92aa', 7019255, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
