INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', 'a&o Hostel København Nørrebro');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Tagensvej 135, 137, Norrebro, Copenhagen, Hovedstaden, 2200, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '167');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at a&amp;o Copenhagen Norrebro - Hostel in Copenhagen (Nørrebro), you''ll be within a 10-minute drive of Nyhavn and Tivoli Gardens. This hostel is 2.6 mi (4.2 km) from City Hall Square and 2.6 mi (4.2 km) from Copenhagen Zoo.</p><p>Make use of convenient amenities such as complimentary wireless internet access, a television in a common area, and tour/ticket assistance. This hostel also features a vending machine and bike storage.</p><p>Grab a bite from the snack bar/deli serving guests of a&amp;o Copenhagen Norrebro - Hostel. Quench your thirst with your favorite drink at the bar/lounge. Buffet breakfasts are served on weekdays from 7:00 AM to 10:00 AM and on weekends from 7:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include express check-out, a 24-hour front desk, and multilingual staff. Self parking (subject to charges) is available onsite.</p><p>Stay in one of 167 guestrooms featuring flat-screen televisions. Complimentary wireless internet access is available to keep you connected. Bathrooms have showers and hair dryers. Conveniences include blackout drapes/curtains, and housekeeping is provided daily.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '11954766');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2eafb791-99c6-c0cc-a484-60ec7879f663', 7021883, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
