INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Tagensvej 135, 137, Norrebro, 2200 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '167');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Khi lưu trú tại a&amp;o Copenhagen Nørrebro, bạn sẽ có vị trí hoàn hảo để khám phá Norrebro.</p><p>Tại nhà nghỉ thanh niên này, bạn sẽ có quyền truy cập vào sân chơi và máy bán hàng tự động. Cơ sở lưu trú này cũng cung cấp nơi chứa hành lý.</p><p>Chỗ nghỉ có sẵn bãi đậu xe .</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 7021883, 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '11954766');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2eafb791-99c6-c0cc-a484-60ec7879f663', 7021883, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2eafb791-99c6-c0cc-a484-60ec7879f663', 7021883, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 10:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nhận phòng qua ứng dụng</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f9f943f0-d438-1c28-4e3e-bf3770a3f28d', 7021883, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f9f943f0-d438-1c28-4e3e-bf3770a3f28d', 7021883, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5571cf7c-356a-44bb-fb8e-880dc2bb7049', 7021883, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5571cf7c-356a-44bb-fb8e-880dc2bb7049', 7021883, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ea13e5b8-06b1-b631-e6da-3bb41af55ab9', 7021883, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ea13e5b8-06b1-b631-e6da-3bb41af55ab9', 7021883, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Đại lục, Không Gluten, Halal, Thuần chay, Chay</p><p>Giờ mở cửa: [Thứ 7 - CN] 07:00-11:00 Đang Mở [Thứ 2 - Thứ 6] 07:00-10:00 Đang Mở</p><table><tr><td>Trẻ em 6 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 7–17 tuổi</td><td>48,5 DKK(khoảng 191.730₫) mỗi người</td></tr><tr><td>Người lớn</td><td>97 DKK(khoảng 383.459₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('580dd488-0e77-a247-2d93-fc5c9b8e262e', 7021883, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('580dd488-0e77-a247-2d93-fc5c9b8e262e', 7021883, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Chỗ nghỉ không yêu cầu đặt cọc</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('44b7f1b4-3066-87e2-267c-d740e6dd0142', 7021883, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('44b7f1b4-3066-87e2-267c-d740e6dd0142', 7021883, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: 115 DKK (khoảng 454.617₫)/thú cưng/ngày</p>');
