INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a84c0b8-fbde-c19d-0ce3-7c0f213e0ba1', 9128639, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Haven Inn & Suites Downtown Houston.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a84c0b8-fbde-c19d-0ce3-7c0f213e0ba1', 9128639, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '5004 North Fwy, Houston, Texas, 77022');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a84c0b8-fbde-c19d-0ce3-7c0f213e0ba1', 9128639, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '34');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a84c0b8-fbde-c19d-0ce3-7c0f213e0ba1', 9128639, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Haven Inn &amp; Suites Downtown Houston, you''ll be centrally located in Houston, within a 15-minute drive of Daikin Park and George R. Brown Convention Center. This motel is 8 mi (12.9 km) from Toyota Center and 10.6 mi (17.1 km) from Rice University.</p><p>Make use of convenient amenities such as complimentary wireless internet access, a reception hall, and a vending machine.</p><p>A complimentary full breakfast is served daily from 6:30 AM to 9:30 AM.</p><p>Featured amenities include complimentary wired internet access, a 24-hour front desk, and laundry facilities. Free self parking is available onsite.</p><p>Make yourself at home in one of the 34 air-conditioned rooms featuring refrigerators and microwaves. Wired and wireless internet access is complimentary, while 49-inch flat-screen televisions with cable programming provide entertainment. Private bathrooms with bathtubs or showers feature complimentary toiletries and hair dryers. Conveniences include phones, as well as desks and irons/ironing boards.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c03b6cd1-9a9e-514c-8c3b-64ff4c725bfb', 9128639, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c03b6cd1-9a9e-514c-8c3b-64ff4c725bfb', 9128639, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>14:00–23:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b0d7a03-935e-d18f-0c7d-0ce45942cfea', 9128639, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b0d7a03-935e-d18f-0c7d-0ce45942cfea', 9128639, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b24e86a6-a550-04f3-ab7c-4cb6396a7c75', 9128639, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b24e86a6-a550-04f3-ab7c-4cb6396a7c75', 9128639, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs and extra beds cannot be added.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c463856f-351e-bc35-a71e-01830784f934', 9128639, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c463856f-351e-bc35-a71e-01830784f934', 9128639, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Cuisine: Full English/Irish</p><p>Opening hours: [Mon - Sun] 06:30-09:30 Open</p><p>Price for extra breakfasts: Contact hotel for details</p><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
