INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a84c0b8-fbde-c19d-0ce3-7c0f213e0ba1', 9128639, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Haven Inn & Suites Downtown Houston.');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a84c0b8-fbde-c19d-0ce3-7c0f213e0ba1', 9128639, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '5004 North Fwy, 77022 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a84c0b8-fbde-c19d-0ce3-7c0f213e0ba1', 9128639, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '34');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8a84c0b8-fbde-c19d-0ce3-7c0f213e0ba1', 9128639, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Haven Inn &amp; Suites Downtown Houston ở trung tâm Houston, chỉ cách Công viên Daikin và Trung tâm Hội nghị George R. Brown 15 phút lái xe. Motel này cách Trung tâm Toyota 12,9 km và cách Đại học Rice 17,1 km.</p><p>Hãy tận hưởng những dịch vụ, tiện ích như quyền truy cập Internet không dây miễn phí, sảnh tiếp tân và máy bán hàng tự động.</p><p>Khách có thể dùng bữa sáng đầy đủ miễn phí hàng ngày từ 6:30 đến 9:30.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm truy cập Internet tốc độ cao (có dây) miễn phí, quầy tiếp tân phục vụ 24 giờ/ngày và trang thiết bị giặt ủi. Có bãi đậu xe tự phục vụ miễn phí trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 34 phòng được trang bị máy điều hòa cùng tủ lạnh và lò vi sóng. Miễn phí truy cập internet có dây lẫn không dây; trong khi đó, các phòng cũng được trang bị TV màn hình phẳng 49-inch với các chương trình truyền hình cáp cho khách giải trí. Phòng tắm riêng với bồn tắm hoặc buồng tắm vòi sen có đồ dùng nhà tắm miễn phí và máy sấy tóc. Tiện nghi phòng bao gồm điện thoại, cùng bàn và bàn ủi/dụng cụ ủi quần áo.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c03b6cd1-9a9e-514c-8c3b-64ff4c725bfb', 9128639, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c03b6cd1-9a9e-514c-8c3b-64ff4c725bfb', 9128639, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>14:00 – 23:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b0d7a03-935e-d18f-0c7d-0ce45942cfea', 9128639, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3b0d7a03-935e-d18f-0c7d-0ce45942cfea', 9128639, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b24e86a6-a550-04f3-ab7c-4cb6396a7c75', 9128639, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b24e86a6-a550-04f3-ab7c-4cb6396a7c75', 9128639, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c463856f-351e-bc35-a71e-01830784f934', 9128639, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c463856f-351e-bc35-a71e-01830784f934', 9128639, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Ẩm thực: Bữa đầy đủ kiểu Anh/Ai-len</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-09:30 Đang Mở</p><p>Giá thêm bữa sáng: Liên hệ với khách sạn để biết thêm chi tiết</p><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('64ce02a5-1722-f1db-666a-3bec6eac2917', 9128639, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
