INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20de8218-749b-6f36-16f4-ad85b4ba1269', 9443394, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'La Colombe d''Or Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20de8218-749b-6f36-16f4-ad85b4ba1269', 9443394, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '3410 Montrose Blvd, Houston, Texas, 77006');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20de8218-749b-6f36-16f4-ad85b4ba1269', 9443394, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '32');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20de8218-749b-6f36-16f4-ad85b4ba1269', 9443394, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located in Houston (Montrose), La Colombe d''Or Hotel is within a 5-minute walk of University of St. Thomas and within 3 minutes by car from Rice University. This luxury hotel is 2.6 mi (4.2 km) from Toyota Center and 2.8 mi (4.5 km) from MD Anderson Cancer Center.</p><p>Be sure to enjoy recreational amenities including an outdoor pool and a 24-hour fitness center. Additional amenities at this Beaux Arts hotel include complimentary wireless internet access, concierge services, and an arcade/game room.</p><p>Enjoy a meal at Tonight &amp; Tomorrow, or stay in and take advantage of the hotel''s 24-hour room service. Relax with your favorite drink at the bar/lounge or the poolside bar. Full breakfasts are available daily from 7:00 AM to 10:30 AM for a fee.</p><p>Featured amenities include a 24-hour business center, dry cleaning/laundry services, and a 24-hour front desk.</p><p>Make yourself at home in one of the 32 air-conditioned rooms featuring minibars and LED televisions. Complimentary wireless internet access keeps you connected, and digital programming is available for your entertainment. Bathrooms have deep soaking bathtubs and rainfall showerheads. Conveniences include safes and desks, as well as phones with free local calls.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c17493c-8813-028d-3058-0ce1498e1cf0', 9443394, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c17493c-8813-028d-3058-0ce1498e1cf0', 9443394, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p><p>If you will arrive outside of check-in hours, contact the property in advance</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2fd71a85-25a7-4351-58e1-b11afa2c5918', 9443394, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2fd71a85-25a7-4351-58e1-b11afa2c5918', 9443394, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
