INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1fea7112-711c-dce8-de19-cbe1ca7ef079', 9443394, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Set menu</p><p>Opening hours: [Mon - Sun] 07:00-10:30 Open</p><table><tr><td>Adult</td><td>$$30.00 per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
