INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20de8218-749b-6f36-16f4-ad85b4ba1269', 9443394, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'La Colombe d''Or Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20de8218-749b-6f36-16f4-ad85b4ba1269', 9443394, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '3410 Montrose Blvd, 77006 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20de8218-749b-6f36-16f4-ad85b4ba1269', 9443394, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '32');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('20de8218-749b-6f36-16f4-ad85b4ba1269', 9443394, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại Montrose, Houston, La Colombe d''Or Hotel cách Đại học St. Thomas 5 phút đi bộ và cách Đại học Rice 3 phút đi xe. Khách sạn sang trọng này cách Trung tâm Toyota 4,2 km và cách Viện Ung thư MD Anderson 4,5 km.</p><p>Hãy nhớ đừng bỏ qua cơ hội tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm hồ bơi ngoài trời và trung tâm thể dục phục vụ 24 giờ. Các tiện ích, dịch vụ khác tại Khách sạn phong cách kiến trúc Beaux Arts này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và phòng trò chơi.</p><p>Khách có thể lựa chọn dùng bữa tại Tonight &amp; Tomorrow của Khách sạn hoặc nghỉ lại trong phòng và thưởng thức những món ăn ngon với dịch vụ phòng 24 giờ. Hãy thư giãn cùng với ly nước giải khát yêu thích của mình tại quầy bar/khu lounge hoặc quầy bar bên hồ bơi. Khách có thể dùng bữa sáng đầy đủ (có phụ phí) từ 7:00 đến 10:30 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng phục vụ 24 giờ, dịch vụ giặt ủi/giặt khô và quầy tiếp tân phục vụ 24 giờ/ngày.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 32 phòng được trang bị máy điều hòa cùng minibar và TV LED. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình kỹ thuật số sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm được trang bị bồn tắm và vòi sen phun mưa. Các tiện nghi phòng bao gồm két bảo mật và bàn, cùng điện thoại với điện thoại nội vùng miễn phí.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c17493c-8813-028d-3058-0ce1498e1cf0', 9443394, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c17493c-8813-028d-3058-0ce1498e1cf0', 9443394, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2fd71a85-25a7-4351-58e1-b11afa2c5918', 9443394, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2fd71a85-25a7-4351-58e1-b11afa2c5918', 9443394, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8db6a9f-7e4c-6d3e-5db2-1b326b32e453', 9443394, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8db6a9f-7e4c-6d3e-5db2-1b326b32e453', 9443394, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1fea7112-711c-dce8-de19-cbe1ca7ef079', 9443394, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1fea7112-711c-dce8-de19-cbe1ca7ef079', 9443394, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Thực đơn cố định</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:30 Đang Mở</p><table><tr><td>Người lớn</td><td>30,00 US$(khoảng 778.741₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4492ca9-18f7-b9d9-48df-cd916e8b5e07', 9443394, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4492ca9-18f7-b9d9-48df-cd916e8b5e07', 9443394, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('19144a4c-31d5-5100-b26a-f73e396710aa', 9443394, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('19144a4c-31d5-5100-b26a-f73e396710aa', 9443394, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: 250,00 US$ (khoảng 6.489.506₫)/phòng/lần lưu trú</p>');
