INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('734f0226-2ac8-bbc0-4b2a-b89d8afa2903', 10577710, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Houston Towers, Downtown Med Ctr, NRG, Adults Only');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('734f0226-2ac8-bbc0-4b2a-b89d8afa2903', 10577710, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '2309 Wichita Street, Houston, Texas, 77004');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('734f0226-2ac8-bbc0-4b2a-b89d8afa2903', 10577710, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '8');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('734f0226-2ac8-bbc0-4b2a-b89d8afa2903', 10577710, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located in Houston (Southeast Houston), Houston Towers Inn Downtown Museum District Med. Ctr NRG - Adults Only is within a 5-minute drive of Rice University and University of Houston. This guesthouse is 1.8 mi (2.9 km) from Houston Zoo and 2.3 mi (3.6 km) from George R. Brown Convention Center.</p><p>Enjoy recreation amenities such as an outdoor pool or take in the view from a terrace. This Victorian guesthouse also features complimentary wireless internet access, wedding services, and a fireplace in the lobby.</p><p>Grab a bite from the snack bar/deli serving guests of Houston Towers Inn Downtown Museum District Med. Ctr NRG - Adults Only. A complimentary self-serve breakfast is served daily from 4:00 AM to 4:30 AM.</p><p>Featured amenities include express check-out, luggage storage, and a library. Planning an event in Houston? This guesthouse has 11 square feet (0 square meters) of space consisting of conference space and a meeting room. Free self parking is available onsite.</p><p>Make yourself at home in one of the 7 air-conditioned rooms featuring flat-screen televisions. Your pillowtop bed comes with down comforters and premium bedding. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Private bathrooms have complimentary toiletries and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('01c8c4a6-c139-f140-41e2-62fdb71c77b5', 10577710, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
