INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('734f0226-2ac8-bbc0-4b2a-b89d8afa2903', 10577710, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '2309 Wichita Street, 77004 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('734f0226-2ac8-bbc0-4b2a-b89d8afa2903', 10577710, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '8');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('734f0226-2ac8-bbc0-4b2a-b89d8afa2903', 10577710, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại Đông Nam Houston, Houston, Houston Towers Inn Downtown Museum District Med. Ctr NRG - Adults Only cách Đại học Rice và Đại học Houston 5 phút lái xe. Nhà khách cách Sở thú Houston 2,9 km và cách Trung tâm Hội nghị George R. Brown 3,6 km.</p><p>Hãy tận hưởng những tiện nghi, dịch vụ thư giãn như hồ bơi ngoài trời hay chỉ đơn giản là ngắm cảnh từ sân thượng/sân hiên. Nhà khách phong cách kiến trúc thời Victoria này còn có quyền truy cập Internet không dây miễn phí, dịch vụ cưới và lò sưởi ở sảnh.</p><p>Khách có thể tìm thấy nhiều quà vặt và món ăn nhẹ tại tiệm/cửa hàng đồ ăn nhanh của Houston Towers Inn Downtown Museum District Med. Ctr NRG - Adults Only. Khách có thể dùng bữa sáng tự phục vụ miễn phí hàng ngày từ 4:00 đến 4:30.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trả phòng nhanh, dịch vụ trông giữ/bảo quản hành lý và thư viện. Có kế hoạch tổ chức sự kiện tại Houston? Nhà khách này có khu vực tổ chức rộng 0 mét vuông, bao gồm khu hội nghị và phòng họp. Có bãi đậu xe tự phục vụ miễn phí trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 7 phòng được trang bị máy điều hòa và TV màn hình phẳng. Giường nệm có lớp đệm bông đi cùng chăn bông và bộ đồ giường cao cấp. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng có đồ dùng nhà tắm miễn phí và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('01c8c4a6-c139-f140-41e2-62fdb71c77b5', 10577710, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('01c8c4a6-c139-f140-41e2-62fdb71c77b5', 10577710, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>16:00 – 19:00</strong></p><p>Trả phòng: <strong>01:00–11:00</strong></p><p>Giờ làm việc của quầy lễ tân: [Thứ 2-CN]10:00–19:00</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38e82c9c-ad03-bf8d-aa71-f7e9ca03ac41', 10577710, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('38e82c9c-ad03-bf8d-aa71-f7e9ca03ac41', 10577710, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Cơ sở lưu trú này không nhận khách lưu trú là trẻ em</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a4c32513-66b6-53e2-df32-3954a65037a9', 10577710, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a4c32513-66b6-53e2-df32-3954a65037a9', 10577710, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('570aaea6-e04b-e520-0fa7-f31becf3f92d', 10577710, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('570aaea6-e04b-e520-0fa7-f31becf3f92d', 10577710, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 04:00-04:30 Đang Mở</p><table><tr><td>Người lớn</td><td>Miễn phí</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('00a048e9-ff3c-e41d-64b5-921ec1e44020', 10577710, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('00a048e9-ff3c-e41d-64b5-921ec1e44020', 10577710, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 100,00 US$ (khoảng 2.595.802₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
