INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8cf59877-49a9-7f24-ccd2-8b36cb295cd6', 11127939, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'The Laura Hotel, Houston Downtown, Autograph Collection');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8cf59877-49a9-7f24-ccd2-8b36cb295cd6', 11127939, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '1070 Dallas St, Houston, Texas, 77002');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8cf59877-49a9-7f24-ccd2-8b36cb295cd6', 11127939, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '223');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8cf59877-49a9-7f24-ccd2-8b36cb295cd6', 11127939, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Feel charmed by The Laura Hotel, Houston Downtown, Autograph Collection. Our renowned hotel in Houston, TX, offers synergistic experiences in the city center, making it an ideal hotel in the Houston Central Business District for business and leisure travelers alike. Singular touches such as an Art Deco Lobby Bar pair masterfully with sensory views from a rooftop pool. Our prestigious address is minutes from The Shops at Houston Center, Toyota Center, Jones Hall for the Performing Arts, and the Theater District. Guests seeking a downtown Houston, TX hotel appreciate our proximity to the George R. Brown Convention Center and six on-site event rooms. Our pet-friendly hotel in downtown Houston is a minimalist''s daydream, distinguished by lofty heights and natural light. Enjoy a modern fitness center, Hull &amp; Oak restaurant, and thoughtfully designed guest rooms with custom bedding, premium linens, and marble bathrooms.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0f164cbc-9af8-d3c6-29ad-bcb2013368da', 11127939, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0f164cbc-9af8-d3c6-29ad-bcb2013368da', 11127939, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–03:00 the next day</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p><p>Check in via app</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9f9b3a65-8e05-0326-d1de-57d4a0240b83', 11127939, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9f9b3a65-8e05-0326-d1de-57d4a0240b83', 11127939, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('095300cd-43c0-5185-6adb-dc1dcca48ce0', 11127939, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('095300cd-43c0-5185-6adb-dc1dcca48ce0', 11127939, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('68e7a705-d422-936f-a0d8-71007a768059', 11127939, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('68e7a705-d422-936f-a0d8-71007a768059', 11127939, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: A la carte</p><p>Opening hours: [Mon - Fri] 06:30-10:00 Open [Sat - Sun] 07:00-11:00 Open</p><p>Price for extra breakfasts: Varies based on the food ordered</p><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
