INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80792929-de45-5165-abb2-88c3a03e5387', 21843360, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'The Post Oak Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80792929-de45-5165-abb2-88c3a03e5387', 21843360, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '1600 W Loop S, Houston, Texas, 77027');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80792929-de45-5165-abb2-88c3a03e5387', 21843360, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '270');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80792929-de45-5165-abb2-88c3a03e5387', 21843360, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at The Post Oak Hotel at Uptown Houston in Houston (The Galleria), you''ll be a 2-minute drive from Westheimer Road and 8 minutes from Rice University. This luxury hotel is 7.2 mi (11.5 km) from MD Anderson Cancer Center and 8.5 mi (13.6 km) from Toyota Center.</p><p>Relax at the full-service spa, where you can enjoy massages, body treatments, and facials. If you''re looking for recreational opportunities, you''ll find an outdoor pool, a steam room, and a 24-hour fitness center. This hotel also features complimentary wireless internet access, concierge services, and a hair salon. Guests can catch a ride to nearby destinations on the complimentary area shuttle.</p><p>Grab a bite at Mastros Steakhouse, one of the hotel''s 4 restaurants, or stay in and take advantage of the 24-hour room service. Snacks are also available at the coffee shop/cafe. Unwind at the end of the day with a drink at the bar/lounge or the poolside bar. Full breakfasts are available daily from 6:30 AM to 10:30 AM for a fee.</p><p>Featured amenities include a 24-hour business center, complimentary newspapers in the lobby, and dry cleaning/laundry services. Event facilities at this hotel consist of a conference center and meeting rooms.</p><p>Make yourself at home in one of the 250 air-conditioned rooms featuring minibars and espresso makers. Flat-screen televisions with satellite programming provide entertainment, while complimentary wireless internet access keeps you connected. Private bathrooms with separate bathtubs and showers feature designer toiletries and hair dryers. Conveniences include safes and desks, and housekeeping is provided daily.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b984d418-d322-af6a-0a21-5e0b019c333f', 21843360, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b984d418-d322-af6a-0a21-5e0b019c333f', 21843360, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 16:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12f980dd-07ac-5038-e8e0-a09fb29372fc', 21843360, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12f980dd-07ac-5038-e8e0-a09fb29372fc', 21843360, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b0f3f453-5d12-63db-cce5-cf5e2ac27d8a', 21843360, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b0f3f453-5d12-63db-cce5-cf5e2ac27d8a', 21843360, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45682508-7f6b-094c-1963-1d8a0b1fb75f', 21843360, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45682508-7f6b-094c-1963-1d8a0b1fb75f', 21843360, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Set menu</p><p>Opening hours: [Mon - Sun] 06:30-10:30 Open</p><table><tr><td>Adult</td><td>$$20.00 per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
