INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80792929-de45-5165-abb2-88c3a03e5387', 21843360, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '270');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('80792929-de45-5165-abb2-88c3a03e5387', 21843360, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Nằm cách trung tâm thương mại The Galleria ở Houston 1,6 km, The Post Oak Hotel có hồ bơi ngoài trời và trung tâm thể dục. Khách sạn 5 sao này cũng có quầy bar và các phòng máy lạnh với phòng tắm riêng. Bức tường nước cách khách sạn 1,7 km và Vườn bách thảo và Trung tâm thiên nhiên Houston cách khách sạn 1,9 km.</p><p>Tại The Post Oak Hotel, tất cả các phòng đều được trang bị bàn làm việc và khu vực ghế ngồi. Tất cả các phòng đều có phòng tắm lát đá cẩm thạch, quầy bar cao cấp và máy pha cà phê Nespresso.</p><p>Tại chỗ nghỉ, du khách sẽ tìm thấy một nhà hàng phục vụ ẩm thực Mỹ.</p><p>Khách sạn Post Oak còn cung cấp trung tâm dịch vụ doanh nhân và du khách có thể đọc báo tại khách sạn. Đội ngũ nhân viên lễ tân có thể nói tiếng Tây Ban Nha và tiếng Anh và sẵn sàng hỗ trợ bạn 24/7.</p><p>Công viên Tưởng niệm cách The Post Oak Hotel 2,2 km. Sân bay gần nhất là Sân bay William P. Hobby, cách chỗ nghỉ 21 km.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b984d418-d322-af6a-0a21-5e0b019c333f', 21843360, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b984d418-d322-af6a-0a21-5e0b019c333f', 21843360, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 16:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12f980dd-07ac-5038-e8e0-a09fb29372fc', 21843360, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12f980dd-07ac-5038-e8e0-a09fb29372fc', 21843360, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b0f3f453-5d12-63db-cce5-cf5e2ac27d8a', 21843360, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b0f3f453-5d12-63db-cce5-cf5e2ac27d8a', 21843360, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45682508-7f6b-094c-1963-1d8a0b1fb75f', 21843360, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('45682508-7f6b-094c-1963-1d8a0b1fb75f', 21843360, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Thực đơn cố định</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:30 Đang Mở</p><table><tr><td>Người lớn</td><td>20,00 US$(khoảng 519.160₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('912189b7-b8d1-fb9b-d7d0-eac00fc081ce', 21843360, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('912189b7-b8d1-fb9b-d7d0-eac00fc081ce', 21843360, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng</p><p>Loại thú cưng được phép mang theo: chó, mèo</p>');
