INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', 'CABINN Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Arni Magnussons Gade 1, Vesterbro/Kongens Enghave, Copenhagen, Hovedstaden, 1577, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '1202');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at CABINN Copenhagen, you''ll be centrally located in Copenhagen, within a 5-minute drive of Tivoli Gardens and City Hall Square. This hotel is 1.7 mi (2.7 km) from Nyhavn and 1.1 mi (1.8 km) from Strøget.</p><p>Be sure to enjoy recreational amenities including a fitness center and bicycles to rent. This hotel also features complimentary wireless internet access, a banquet hall, and a vending machine.</p><p>Grab a bite from the snack bar/deli serving guests of CABINN Copenhagen. Continental breakfasts are served on weekdays from 6:30 AM to 10:00 AM and on weekends from 7:30 AM to 10:30 AM for a fee.</p><p>Featured amenities include a 24-hour front desk, luggage storage, and laundry facilities. Self parking (subject to charges) is available onsite.</p><p>Stay in one of 1202 guestrooms featuring flat-screen televisions. Complimentary wireless internet access is available to keep you connected. Bathrooms with showers are provided. Conveniences include desks and coffee/tea makers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b5767f52-844f-96a2-9124-a244747f40c7', 36649443, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b5767f52-844f-96a2-9124-a244747f40c7', 36649443, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–24:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1302ebee-e240-db74-149f-7317ed772917', 36649443, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1302ebee-e240-db74-149f-7317ed772917', 36649443, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b9cbefaf-0bf4-044a-0ddd-9df0d12a1005', 36649443, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
