INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c6379dfc-6439-f11d-30d5-2fce51e1b479', 36649443, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Cuisine: Continental</p><p>Opening hours: [Mon - Fri] 06:30-10:00 Open [Sat - Sun] 07:30-10:30 Open</p><table><tr><td>Adult</td><td>Contact property</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
