INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Cabinn Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', 'CABINN Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Arni Magnussons Gade 1, Vesterbro/Kongens Enghave, 1577 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '1202');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6335a537-e076-d6db-8c35-9e494a986975', 36649443, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>CABINN Copenhagen ở trung tâm Copenhagen, cách Công viên Tivoli và Quảng trường Tòa thị chính 5 phút lái xe. Khách sạn này cách Khu Nyhavn 2,7 km và cách Phố Strøget 1,8 km.</p><p>Hãy nhớ đừng bỏ qua cơ hội tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm trung tâm thể dục và xe đạp cho thuê. Khách sạn này còn có quyền truy cập Internet không dây miễn phí, phòng đại tiệc và máy bán hàng tự động.</p><p>Khách có thể tìm thấy nhiều quà vặt và món ăn nhẹ tại tiệm/cửa hàng đồ ăn nhanh của CABINN Copenhagen. Khách có thể dùng bữa sáng kiểu Âu các ngày trong tuần từ 6:30 đến 10:00 và cuối tuần (phụ phí) từ 7:30 đến 10:30.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm quầy tiếp tân phục vụ 24 giờ/ngày, dịch vụ trông giữ/bảo quản hành lý và trang thiết bị giặt ủi. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ tại một trong 1202 phòng được trang bị TV màn hình phẳng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Các phòng có phòng tắm với buồng tắm vòi sen. Tiện nghi phòng bao gồm bàn và dụng cụ pha cà phê/trà.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b5767f52-844f-96a2-9124-a244747f40c7', 36649443, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b5767f52-844f-96a2-9124-a244747f40c7', 36649443, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 24:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1302ebee-e240-db74-149f-7317ed772917', 36649443, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1302ebee-e240-db74-149f-7317ed772917', 36649443, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b9cbefaf-0bf4-044a-0ddd-9df0d12a1005', 36649443, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b9cbefaf-0bf4-044a-0ddd-9df0d12a1005', 36649443, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c6379dfc-6439-f11d-30d5-2fce51e1b479', 36649443, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c6379dfc-6439-f11d-30d5-2fce51e1b479', 36649443, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Ẩm thực: Đại lục</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:00 Đang Mở [Thứ 7 - CN] 07:30-10:30 Đang Mở</p><table><tr><td>Người lớn</td><td>Liên hệ khách sạn</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8336fa2-c9bf-b154-6813-f8d51b0606c7', 36649443, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f8336fa2-c9bf-b154-6813-f8d51b0606c7', 36649443, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Chỗ nghỉ không yêu cầu đặt cọc</strong></p>');
