INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d8a1697-fce3-87e2-432f-aa7fa807338f', 45811113, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Tietgensgade 35, 39, Vesterbro/Kongens Enghave, Copenhagen, Hovedstaden, 1704, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d8a1697-fce3-87e2-432f-aa7fa807338f', 45811113, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d8a1697-fce3-87e2-432f-aa7fa807338f', 45811113, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '390');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d8a1697-fce3-87e2-432f-aa7fa807338f', 45811113, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Indulge yourself in a wealth of experiences at Villa Copenhagen. Honoring the ethos of the old charming Europe expressed in our building of history allowing the past presence and future to come together in an inspiring and playful ambience. We promise our visitors locals and overseas visitors alike a journey of magical experiences for all senses. 390 unique rooms and suites designed in a Scandinavian luxury style - an international event and meeting place with 2300 square meters - a heated rooftop pool and a gym. Situated right in the heart of Copenhagen right next to the central train station and only 15 minutes from CPH Airport Villa Copenhagen has a unique and ideal location with major attractions within walking distance.</p><p>To view the cleanliness policy for this property please visit the property page listed on Preferredhotels.com.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('638a954c-cd38-9fc5-5c60-5c2b2e6fbb49', 45811113, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
