INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d8a1697-fce3-87e2-432f-aa7fa807338f', 45811113, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Villa Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d8a1697-fce3-87e2-432f-aa7fa807338f', 45811113, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Tietgensgade 35, 39, Vesterbro/Kongens Enghave, 1704 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d8a1697-fce3-87e2-432f-aa7fa807338f', 45811113, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d8a1697-fce3-87e2-432f-aa7fa807338f', 45811113, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '390');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8d8a1697-fce3-87e2-432f-aa7fa807338f', 45811113, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, Villa Copenhagen, cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút đi bộ. Khách sạn sang trọng này cách Phố Strøget 0,8 km và cách Vườn Bách thảo 2 km.</p><p>Hãy nhớ đừng bỏ qua cơ hội tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm hồ bơi ngoài trời, phòng tắm hơi và trung tâm thể dục phục vụ 24 giờ. Khách sạn này còn có quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và khu mua sắm trong khuôn viên.</p><p>Khách có thể thưởng thức những món ăn ngon tại Public hoặc dùng bữa tại 2 tiệm cà phê/quán cà phê. Khách sạn này còn cung cấp dịch vụ phòng 24 giờ. Thư giãn tạo quầy bar bên hồ bơi hoặc một trong 2 quầy bar/khu lounge với những ly nước mát.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng phục vụ 24 giờ, nhận phòng nhanh và trả phòng nhanh. Có kế hoạch tổ chức sự kiện tại Copenhagen? Khách sạn này có khu vực tổ chức rộng 2300 mét vuông, bao gồm khu hội nghị và 8 phòng họp.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 390 phòng được trang bị máy điều hòa cùng minibar và Smart TV. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Các phòng tắm được trang bị buồng tắm vòi sen với vòi sen phun mưa và đồ dùng nhà tắm miễn phí. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật đặt được máy tính xách tay và dụng cụ pha cà phê/trà.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('638a954c-cd38-9fc5-5c60-5c2b2e6fbb49', 45811113, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('638a954c-cd38-9fc5-5c60-5c2b2e6fbb49', 45811113, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 22:00</strong></p><p>Trả phòng: <strong>04:00–12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Quầy tự nhận phòng</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a33f59a6-e78f-7ebb-2e1b-a85ac2a59821', 45811113, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a33f59a6-e78f-7ebb-2e1b-a85ac2a59821', 45811113, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c7c1f7b-b2df-dc3c-59ef-e5f79f5aeaff', 45811113, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('9c7c1f7b-b2df-dc3c-59ef-e5f79f5aeaff', 45811113, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e1dc514c-390b-0572-8bb4-4d71dfab274f', 45811113, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e1dc514c-390b-0572-8bb4-4d71dfab274f', 45811113, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Ẩm thực: Chay</p><table><tr><td>Người lớn</td><td>Liên hệ khách sạn</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fea6b251-7fd5-9bfe-580e-99cb17ec9e44', 45811113, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fea6b251-7fd5-9bfe-580e-99cb17ec9e44', 45811113, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ ghi nợ và thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Vào ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1f315b3a-0fd6-e5df-9ffb-b6abd7ec706a', 45811113, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1f315b3a-0fd6-e5df-9ffb-b6abd7ec706a', 45811113, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: 500 DKK (khoảng 1.977.407₫)/thú cưng/lần lưu trú</p>');
