INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3e253bfc-9ac3-9b38-0cfd-5c915234aa11', 64190198, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
