INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('63a471a2-6f88-c26a-b9a9-48d3584a3117', 64190198, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Comwell Copenhagen Portside Dolce by Wyndham');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('63a471a2-6f88-c26a-b9a9-48d3584a3117', 64190198, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Alexandriagade 1, Osterbro, 2150 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('63a471a2-6f88-c26a-b9a9-48d3584a3117', 64190198, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('63a471a2-6f88-c26a-b9a9-48d3584a3117', 64190198, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '483');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('63a471a2-6f88-c26a-b9a9-48d3584a3117', 64190198, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Khi lưu trú tại Comwell Copenhagen Portside Dolce by Wyndham, bạn sẽ có vị trí hoàn hảo để khám phá Osterbro.</p><p>phòng gym cung cấp một nơi để khách rèn luyện sức khỏe.</p><p>Cơ sở lưu trú này có nhà hàng. Trong thời gian lưu trú, hãy tự thưởng cho mình dịch vụ phòng đồ ăn từ nhà hàng trong nhà. Kết thúc ngày nghỉ của bạn bằng đồ uống tại bar.</p><p>Tại khách sạn này, bạn sẽ có quyền truy cập vào vườn. Thuộc tính này cũng cung cấp nơi chứa hành lý, giặt khô và dịch vụ giặt là.</p><p>Chỗ đỗ xe có sẵn tại chỗ nghỉ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3e253bfc-9ac3-9b38-0cfd-5c915234aa11', 64190198, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3e253bfc-9ac3-9b38-0cfd-5c915234aa11', 64190198, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 24:00</strong></p><p>Trả phòng: <strong>01:00–11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d5ad6f56-c3b8-857e-df07-ddc3351caa39', 64190198, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d5ad6f56-c3b8-857e-df07-ddc3351caa39', 64190198, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('34779e86-2fe5-7d22-89d3-0226c2d28475', 64190198, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('34779e86-2fe5-7d22-89d3-0226c2d28475', 64190198, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75265bae-38b8-04ab-45d1-021c81274f6e', 64190198, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('75265bae-38b8-04ab-45d1-021c81274f6e', 64190198, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:00 Đang Mở</p><table><tr><td>Trẻ em 11 tuổi trở xuống</td><td>97,5 DKK(khoảng 385.594₫) mỗi người</td></tr><tr><td>Trẻ em 12–17 tuổi</td><td>195 DKK(khoảng 771.189₫) mỗi người</td></tr><tr><td>Người lớn</td><td>195 DKK(khoảng 771.189₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5d659872-3764-2fc0-bd00-d2b3aae61607', 64190198, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5d659872-3764-2fc0-bd00-d2b3aae61607', 64190198, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: 250 DKK (khoảng 988.704₫)/phòng/ngày</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c4364877-d352-69f1-3f95-004dfaa42b59', 64190198, 'POLICY', 'serviceAnimal', 'vi', 'policy_title', 'Động vật hỗ trợ');
