INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa0d58c-2a06-62b9-7c41-187005a5359e', 72560169, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Blossom Hotel Houston, Curio Collection by Hilton');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa0d58c-2a06-62b9-7c41-187005a5359e', 72560169, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '7118 Bertner Ave, Houston, Texas, 77030');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa0d58c-2a06-62b9-7c41-187005a5359e', 72560169, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '267');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa0d58c-2a06-62b9-7c41-187005a5359e', 72560169, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Blossom Hotel Houston sits just minutes from MD Anderson Cancer Center and the Texas Medical Center offering an ideal location for medical visits business travel and leisure stays. Positioned near the Museum District and Hermann Park the hotel blends contemporary boutique style with full-service comfort. The 16-story property features 267 guestrooms and suites with free in-room WiFi smart TVs premium bedding refreshment centers luxury bath amenities and plush bathrobes.</p><p>Dining includes Blossom Reserve with American and Asian influenced menus throughout the day and Plum Skybar and Lounge a rooftop venue serving cocktails and light bites with skyline views. Guests can enjoy a 24-hour Peloton equipped fitness center and a rooftop pool and lounge for relaxation between appointments or meetings.</p><p>The hotel offers approximately 9755 square feet of flexible meeting and event space including a ballroom and multiple breakout rooms suited for conferences and receptions. Surrounding activities include exploring the Museum District strolling through Hermann Park and attending events at NRG Stadium.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('961a1e19-bd0f-e428-f4e9-1c1993b27f02', 72560169, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('961a1e19-bd0f-e428-f4e9-1c1993b27f02', 72560169, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>16:00–03:00 the next day</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b468a27e-a044-8755-5342-ed7739e4e9c5', 72560169, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b468a27e-a044-8755-5342-ed7739e4e9c5', 72560169, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15a14eec-fa3a-9450-f1e2-da4ee4218030', 72560169, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15a14eec-fa3a-9450-f1e2-da4ee4218030', 72560169, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a78b05a5-1273-0498-94ce-a2f5f595e336', 72560169, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a78b05a5-1273-0498-94ce-a2f5f595e336', 72560169, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: American</p><p>Opening hours: [Mon - Sun] 07:00-11:00 Open</p><table><tr><td>Children 17 years old and under</td><td>$$40.00 per person</td></tr><tr><td>Adult</td><td>$$40.00 per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bf028192-34c5-d64d-3789-378591bfdd3c', 72560169, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bf028192-34c5-d64d-3789-378591bfdd3c', 72560169, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of $100.00 is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment within 7 days after check-out.</strong></p>');
