INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa0d58c-2a06-62b9-7c41-187005a5359e', 72560169, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Blossom Hotel Houston, Curio Collection by Hilton');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa0d58c-2a06-62b9-7c41-187005a5359e', 72560169, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '7118 Bertner Ave, 77030 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa0d58c-2a06-62b9-7c41-187005a5359e', 72560169, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '267');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6fa0d58c-2a06-62b9-7c41-187005a5359e', 72560169, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc ở Houston, cách Sân vận động NRG Park 2.2 km, Blossom Hotel Houston, Curio Collection by Hilton cung cấp chỗ nghỉ có hồ bơi ngoài trời, chỗ đậu xe riêng, trung tâm thể dục và phòng chờ chung. Chỗ nghỉ này có các tiện nghi như nhà hàng, dịch vụ phòng và quầy lễ tân 24 giờ, cùng với Wi-Fi miễn phí. Chỗ nghỉ này cung cấp dịch vụ văn phòng, dịch vụ tiền sảnh và phòng giữ hành lý cho khách.</p><p>Phòng khách tại khách sạn có điều hòa và bàn làm việc.</p><p>Khách tại Blossom Hotel Houston, Curio Collection by Hilton có thể thưởng thức bữa sáng thực đơn à la carte.</p><p>Chỗ nghỉ có sân hiên.</p><p>Blossom Hotel Houston, Curio Collection by Hilton cách Vườn thú Houston 2.7 km và Sân vận động NRG 2.8 km.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('961a1e19-bd0f-e428-f4e9-1c1993b27f02', 72560169, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('961a1e19-bd0f-e428-f4e9-1c1993b27f02', 72560169, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>16:00 – 03:00 ngày hôm sau</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b468a27e-a044-8755-5342-ed7739e4e9c5', 72560169, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b468a27e-a044-8755-5342-ed7739e4e9c5', 72560169, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15a14eec-fa3a-9450-f1e2-da4ee4218030', 72560169, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('15a14eec-fa3a-9450-f1e2-da4ee4218030', 72560169, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a78b05a5-1273-0498-94ce-a2f5f595e336', 72560169, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a78b05a5-1273-0498-94ce-a2f5f595e336', 72560169, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Mỹ</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-11:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>40,00 US$(khoảng 1.038.321₫) mỗi người</td></tr><tr><td>Người lớn</td><td>40,00 US$(khoảng 1.038.321₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bf028192-34c5-d64d-3789-378591bfdd3c', 72560169, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bf028192-34c5-d64d-3789-378591bfdd3c', 72560169, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 100,00 US$ (khoảng 2.595.802₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bf4fcf06-ad8f-df17-6622-58b890a4f4c4', 72560169, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
