INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77107ee8-b31e-e814-c189-e3fd76aaccf8', 76325348, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'NH Collection Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77107ee8-b31e-e814-c189-e3fd76aaccf8', 76325348, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Strandgade 7, Indre By, 1401 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77107ee8-b31e-e814-c189-e3fd76aaccf8', 76325348, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77107ee8-b31e-e814-c189-e3fd76aaccf8', 76325348, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '394');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77107ee8-b31e-e814-c189-e3fd76aaccf8', 76325348, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>NH Collection Copenhagen ở Trung tâm Copenhagen, Copenhagen, cách Phố Strøget và Khu Nyhavn 15 phút đi bộ. Khách sạn sang trọng này cách Công viên Tivoli 1,8 km và cách Quảng trường Tòa thị chính 1,4 km.</p><p>Hãy tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí như trung tâm thể dục và xe đạp cho thuê. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, phòng đại tiệc và chỗ để xe đạp.</p><p>Khách có thể thưởng thức đặc sản địa phương tại Plates hoặc chọn dùng bữa tại một trong nhiều khu ẩm thực của Khách sạn, bao gồm 2 nhà hàng và quán cà phê. Đập tan cơn khát với đồ uống yêu thích của mình tại 2 quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 6:30 đến 10:00 vào các ngày trong tuần.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm dịch vụ giặt ủi/giặt khô, quầy tiếp tân phục vụ 24 giờ/ngày và nhân viên thông thạo nhiều ngôn ngữ.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 394 phòng được trang bị minibar và TV màn hình phẳng. Các kênh truyền hình vệ tinh sẽ giúp bạn có những giây phút giải trí thoải mái. Phòng tắm riêng với buồng tắm vòi sen có vòi sen phun mưa và máy sấy tóc. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật và bàn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77107ee8-b31e-e814-c189-e3fd76aaccf8', 76325348, 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '23438123');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d811cec0-f6a4-15f6-4aee-907ef39cc1ae', 76325348, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d811cec0-f6a4-15f6-4aee-907ef39cc1ae', 76325348, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 24:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('daee135d-db85-a2e5-e05b-8677472a71ec', 76325348, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('daee135d-db85-a2e5-e05b-8677472a71ec', 76325348, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('633ea54a-b5f5-4ebb-611a-e7feb0df7763', 76325348, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('633ea54a-b5f5-4ebb-611a-e7feb0df7763', 76325348, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5cf0022c-5c3a-d519-f919-d576f03cfea3', 76325348, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5cf0022c-5c3a-d519-f919-d576f03cfea3', 76325348, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Đại lục, Không Gluten, Thuần chay, Chay</p><table><tr><td>Người lớn</td><td>272,61 DKK(khoảng 1.077.679₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fd15c9cc-383f-3dd2-c295-8d1f4a9186c6', 76325348, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
