INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d79a0d84-f311-dc7a-1cc0-223a904b5840', 76325348, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó, mèo</p><p>Phí: 260 DKK (khoảng 1.027.829₫)/thú cưng/đêm</p>');
