INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hillwood House Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '山林舍酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '17-19 Hillwood Road, Tsim Sha Tsui, Yau Tsim Mong District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '82');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Inspired by the theme of Dawn and Dusk, Hillwood House aims to provide a cozy and homey environment to both locals and travellers. Hillwood Road, located in Tsim Sha Tsui within close proximity to some of Hong Kong’s most talked-about attractions, and yet has its own unique sense of seclusion and characteristic is what sets us apart.</p><p>The contrast of the light and dark tones together with the spherical design elements throughout the hotel in different rooms allows us to transcend beyond the hustle-and-bustle of Hong Kong, and to really loosen up ourselves with ease. The chic built-in furnishing and colours definitely add to the holiday mood of the travellers and brighten up any dull normal day for the locals as they seek for peace and tranquility.</p><p>We put our guests’ comfort, hygiene, and privacy at our foremost by ensuring that we implement the most efficient automated check-in and out system, housekeeping and front desk services.</p>');
