INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hillwood House Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '山林舍酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '17-19 Hillwood Road, Tsim Sha Tsui, Yau Tsim Mong District, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '82');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('192db63a-92d4-6b4f-1d88-c421022b9019', 78456935, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Inspired by the theme of Dawn and Dusk, Hillwood House aims to provide a cozy and homey environment to both locals and travellers. Hillwood Road, located in Tsim Sha Tsui within close proximity to some of Hong Kong’s most talked-about attractions, and yet has its own unique sense of seclusion and characteristic is what sets us apart.</p><p>The contrast of the light and dark tones together with the spherical design elements throughout the hotel in different rooms allows us to transcend beyond the hustle-and-bustle of Hong Kong, and to really loosen up ourselves with ease. The chic built-in furnishing and colours definitely add to the holiday mood of the travellers and brighten up any dull normal day for the locals as they seek for peace and tranquility.</p><p>We put our guests’ comfort, hygiene, and privacy at our foremost by ensuring that we implement the most efficient automated check-in and out system, housekeeping and front desk services.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e21e0949-379d-bb4c-4539-2677b9affede', 78456935, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e21e0949-379d-bb4c-4539-2677b9affede', 78456935, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('54a398db-5b07-eff2-197b-2b43d8648042', 78456935, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('54a398db-5b07-eff2-197b-2b43d8648042', 78456935, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1ac4185a-c4b4-3289-0f90-b2900a977f2b', 78456935, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
