INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 83194466, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Bernstorffsgade 27, Indre By, Copenhagen, Hovedstaden, 1577, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 83194466, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 83194466, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '433');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 83194466, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>A stay at Next House Copenhagen - Hostel places you in the heart of Copenhagen, within a 15-minute walk of Tivoli Gardens and City Hall Square. This hostel is 0.6 mi (1 km) from Strøget and 1.4 mi (2.2 km) from Nyhavn.</p><p>Be sure to enjoy recreational amenities including a fitness center and bicycles to rent. Additional features at this hostel include complimentary wireless internet access, an arcade/game room, and a fireplace in the lobby.</p><p>You can enjoy a meal at Next EATERY serving the guests of Next House Copenhagen - Hostel, or stop in at the snack bar/deli. Need to unwind? Take a break with a tasty beverage at one of the 4 bars/lounges. Buffet breakfasts are available daily from 7:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include express check-in, express check-out, and a 24-hour front desk.</p><p>Make yourself at home in one of the 433 guestrooms. Complimentary wireless internet access is available to keep you connected. Bathrooms have showers and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 83194466, 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '23984102');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5fad0da6-dca0-dbd7-186b-3af140529af3', 83194466, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5fad0da6-dca0-dbd7-186b-3af140529af3', 83194466, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7eb9526d-d29f-2d6a-7a1a-ee904f79ab13', 83194466, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7eb9526d-d29f-2d6a-7a1a-ee904f79ab13', 83194466, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
