INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('53fc808e-48e9-73fa-ca9d-1369a7d4c354', 83194466, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:00-11:00 Open</p><table><tr><td>Children 17 years old and under</td><td>DKK 69 (approx. $10.50) per person</td></tr><tr><td>Adult</td><td>DKK 69 (approx. $10.50) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
