INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '麗豪航天城酒店（富豪酒店集團旗下）');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '8 Airport Expo Boulevard, Islands District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '1208');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Situated in SKYCITY of Hong Kong International Airport, Regala Skycity Hotel is directly connected to AsiaWorld-Expo and 11 SKIES, a captivating retail, dining, and entertainment destination. With easy access to Hong Kong-Zhuhai-Macao Bridge and Tuen Mun-Chek Lap Kok Link, the hotel provides unrivalled connectivity to the Greater Bay Area and Macau via land, and to the rest of the world via air.</p><p>The hotel offers 1,208 guestrooms with comfortable and affordable luxury facilities and services that is ideal for MICE, weddings, social gatherings, staycations, as well as individual business and leisure travels. Each of the three restaurants with bars offer an array of exciting gastronomy experience curated by the passionate and dynamic team.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8e625f67-ca46-2661-8ee1-8c649b146780', 92764015, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8e625f67-ca46-2661-8ee1-8c649b146780', 92764015, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('52e7a609-41ab-20a5-5a16-37ac1975fa69', 92764015, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('52e7a609-41ab-20a5-5a16-37ac1975fa69', 92764015, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Children between 0 and 11 years old can stay for free if no extra bed is needed.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('609078dd-5890-3a24-f9b7-dc1ff5a3a580', 92764015, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('609078dd-5890-3a24-f9b7-dc1ff5a3a580', 92764015, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5ca6866d-cd37-9c62-c057-524d49bd8e66', 92764015, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5ca6866d-cd37-9c62-c057-524d49bd8e66', 92764015, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:00-11:00 Open</p><table><tr><td>Children 17 years old and under</td><td>HK$185.00 (approx. $23.59) per person</td></tr><tr><td>Adult</td><td>HK$185.00 (approx. $23.59) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('be23c705-7ac3-354b-fa92-5e5860b2f4f7', 92764015, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('be23c705-7ac3-354b-fa92-5e5860b2f4f7', 92764015, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>The deposit is determined based on the number of rooms you book. The charge is HK$500.00 (approx. $63.74) per room.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards and cash</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1ce00be3-093a-3e3b-0a45-770fe1b8dae7', 92764015, 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
