INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8ee4399f-469f-b627-cf59-be6e4c0d2c4b', 92764015, 'POLICY', 'ageLimit', 'en', 'policy_title', 'Age Requirements');
