INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Regala Skycity Hotel by Regal Hotels');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '麗豪航天城酒店（富豪酒店集團旗下）');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '8 Airport Expo Boulevard, Islands District, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '1208');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3fa663ae-550d-c43c-9c9a-afe8d9135745', 92764015, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Situated in SKYCITY of Hong Kong International Airport, Regala Skycity Hotel is directly connected to AsiaWorld-Expo and 11 SKIES, a captivating retail, dining, and entertainment destination. With easy access to Hong Kong-Zhuhai-Macao Bridge and Tuen Mun-Chek Lap Kok Link, the hotel provides unrivalled connectivity to the Greater Bay Area and Macau via land, and to the rest of the world via air.</p><p>The hotel offers 1,208 guestrooms with comfortable and affordable luxury facilities and services that is ideal for MICE, weddings, social gatherings, staycations, as well as individual business and leisure travels. Each of the three restaurants with bars offer an array of exciting gastronomy experience curated by the passionate and dynamic team.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8e625f67-ca46-2661-8ee1-8c649b146780', 92764015, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8e625f67-ca46-2661-8ee1-8c649b146780', 92764015, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('52e7a609-41ab-20a5-5a16-37ac1975fa69', 92764015, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('52e7a609-41ab-20a5-5a16-37ac1975fa69', 92764015, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 11 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('609078dd-5890-3a24-f9b7-dc1ff5a3a580', 92764015, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('609078dd-5890-3a24-f9b7-dc1ff5a3a580', 92764015, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5ca6866d-cd37-9c62-c057-524d49bd8e66', 92764015, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5ca6866d-cd37-9c62-c057-524d49bd8e66', 92764015, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-11:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>185,00 HK$(khoảng 612.232₫) mỗi người</td></tr><tr><td>Người lớn</td><td>185,00 HK$(khoảng 612.232₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('be23c705-7ac3-354b-fa92-5e5860b2f4f7', 92764015, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('be23c705-7ac3-354b-fa92-5e5860b2f4f7', 92764015, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khoản tiền cọc được tính dựa trên số lượng phòng bạn đặt. Mức phí là 500,00 HK$ (khoảng 1.654.681₫)/phòng.</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng và tiền mặt</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1ce00be3-093a-3e3b-0a45-770fe1b8dae7', 92764015, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
