INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '合和酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '15 Kennedy Road, Wan Chai District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '1000');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Surrounded by the enchanting hillside greenery and facing the stunning view of Victoria Harbour.</p><p>Home to the largest park in Wan Chai, hotel will provide meetings and convention space, various dining and recreational facilities, including Wan Chai’s largest lifestyle mall, Hopewell Mall. Connected to Kennedy Road, Queen’s Road East and Lee Tung Avenue, we offer a perfect location of your business meetings, conferences and special occasions with our versatile ballrooms and function spaces accessible via the expansive pick-up &amp; drop-off area for all vehicles. Hopewell Hotel strives to create a sense of warmth and a homey, soul-healing experience to every guest, rooms are spacious, uncluttered and decorated in wooden and earthy tone. Ideal for both business trips or family vacations, our expansive suites and guests rooms provide all the space you could need for your stay. From Deluxe Room to Suite, each room exudes elegance and grace, complemented with modern amenities. From contemporary, fully-furnished rooms to vibrant, interesting neighbourhoods, we are here to create "Memorable Moments" for our guests.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d74de9a8-c146-f5c4-bdf6-9c4289a3d5d6', 120038931, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d74de9a8-c146-f5c4-bdf6-9c4289a3d5d6', 120038931, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p><p>Self check-in kiosk</p><p>The property will provide check-in details after booking</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3cf8cf1a-964e-fe6c-8dd8-e82ba08dfe32', 120038931, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3cf8cf1a-964e-fe6c-8dd8-e82ba08dfe32', 120038931, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Children between 0 and 12 years old can stay for free if no extra bed is needed.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6b8f6cd0-cd00-96ed-5d71-a1e5e3b849cf', 120038931, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6b8f6cd0-cd00-96ed-5d71-a1e5e3b849cf', 120038931, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
