INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6f6d94aa-6dcb-643d-156d-3eb2b8252b17', 120038931, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Western</p><p>Opening hours: [Mon - Fri] 07:00-10:00 Open [Sat - Sun] 07:00-10:30 Open</p><table><tr><td>Children 2 years old and under</td><td>Free</td></tr><tr><td>Children 3–12 years old</td><td>HK$165.00 (approx. $21.04) per person</td></tr><tr><td>Children 13–17 years old</td><td>HK$220.00 (approx. $28.05) per person</td></tr><tr><td>Adult</td><td>HK$220.00 (approx. $28.05) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df325a96-794e-2c85-4ce9-69abc928d339', 120038931, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df325a96-794e-2c85-4ce9-69abc928d339', 120038931, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>The deposit is determined based on the duration of your stay. The charge is HK$1,000.00 (approx. $127.49) per night.</strong></p><p>Deposit Payment Methods: <strong>This property accepts cash and credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment within 14 days after check-out.</strong></p>');
