INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hopewell Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '合和酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '15 Kennedy Road, Loan Tử, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '1000');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b82c12c4-e6c4-77a5-8dd1-408292d78f03', 120038931, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Surrounded by the enchanting hillside greenery and facing the stunning view of Victoria Harbour.</p><p>Home to the largest park in Wan Chai, hotel will provide meetings and convention space, various dining and recreational facilities, including Wan Chai’s largest lifestyle mall, Hopewell Mall. Connected to Kennedy Road, Queen’s Road East and Lee Tung Avenue, we offer a perfect location of your business meetings, conferences and special occasions with our versatile ballrooms and function spaces accessible via the expansive pick-up &amp; drop-off area for all vehicles. Hopewell Hotel strives to create a sense of warmth and a homey, soul-healing experience to every guest, rooms are spacious, uncluttered and decorated in wooden and earthy tone. Ideal for both business trips or family vacations, our expansive suites and guests rooms provide all the space you could need for your stay. From Deluxe Room to Suite, each room exudes elegance and grace, complemented with modern amenities. From contemporary, fully-furnished rooms to vibrant, interesting neighbourhoods, we are here to create "Memorable Moments" for our guests.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d74de9a8-c146-f5c4-bdf6-9c4289a3d5d6', 120038931, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d74de9a8-c146-f5c4-bdf6-9c4289a3d5d6', 120038931, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Quầy tự nhận phòng</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3cf8cf1a-964e-fe6c-8dd8-e82ba08dfe32', 120038931, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3cf8cf1a-964e-fe6c-8dd8-e82ba08dfe32', 120038931, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 12 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6b8f6cd0-cd00-96ed-5d71-a1e5e3b849cf', 120038931, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6b8f6cd0-cd00-96ed-5d71-a1e5e3b849cf', 120038931, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6f6d94aa-6dcb-643d-156d-3eb2b8252b17', 120038931, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6f6d94aa-6dcb-643d-156d-3eb2b8252b17', 120038931, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Tây phương</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 07:00-10:00 Đang Mở [Thứ 7 - CN] 07:00-10:30 Đang Mở</p><table><tr><td>Trẻ em 2 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 3–12 tuổi</td><td>165,00 HK$(khoảng 546.360₫) mỗi người</td></tr><tr><td>Trẻ em 13–17 tuổi</td><td>220,00 HK$(khoảng 728.480₫) mỗi người</td></tr><tr><td>Người lớn</td><td>220,00 HK$(khoảng 728.480₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df325a96-794e-2c85-4ce9-69abc928d339', 120038931, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('df325a96-794e-2c85-4ce9-69abc928d339', 120038931, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khoản tiền cọc được tính dựa trên độ dài lưu trú của bạn. Mức phí là 1.000,00 HK$ (khoảng 3.309.362₫)/đêm.</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận tiền mặt và thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 14 ngày sau ngày trả phòng.</strong></p>');
