INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('58fba819-5e13-d216-27dc-01c9c2f07ac5', 120231211, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Urbanslow');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('58fba819-5e13-d216-27dc-01c9c2f07ac5', 120231211, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '어반슬로우');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('58fba819-5e13-d216-27dc-01c9c2f07ac5', 120231211, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '9 Seogang-ro 20-gil, Mapo-gu, Seoul, 04100, South Korea');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('58fba819-5e13-d216-27dc-01c9c2f07ac5', 120231211, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '25');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('58fba819-5e13-d216-27dc-01c9c2f07ac5', 120231211, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Urbanslow offers top-notch services and amenities, ensuring guests experience utmost comfort. Share your photos and respond to emails at your convenience, thanks to the free Wi-Fi internet access offered by motel. Taxi offerings at the motel enhance the ease of discovering Seoul.Reception services such as express check-in or check-out and luggage storage are available to accommodate your requirements. Traveling with minimal luggage is achievable at Urbanslow due to the motel''s laundry service ensuring your garments stay fresh. Room amenities feature daily housekeeping, allowing you to unwind and make the most of your visit. The motel maintains a completely smoke-free zone, providing a breathable atmosphere.Smoking is limited to specified smoking zones. Each accommodation at Urbanslow is thoughtfully created and adorned to provide visitors with a comfortable, home-like atmosphere.In certain rooms, the motel offers blackout curtains and air conditioning for guest convenience and satisfaction. At Urbanslow, the uniquely tailored rooms provide a configuration choice resembling a balcony or terrace. In select rooms, guests at the motel can enjoy top-notch in-room entertainment with television, in-room video streaming and cable TV available for their convenience.Rest assured, in a few chosen rooms, you will find the convenience of a refrigerator and bottled water at your disposal.Understanding the significance of bathroom facilities in enhancing visitor contentment, motel offers a hair dryer, toiletries and towels within a few chosen chambers. Should you be particularly discerning in your dining choices, you will surely appreciate having access to the on-site shared kitchen provided at this location.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4c04736-b2ac-1f92-6258-4b6edd5757c0', 120231211, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
