INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb41122-93c8-b649-0645-70b5c602079d', 122417658, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'gagahouse Chungmu');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb41122-93c8-b649-0645-70b5c602079d', 122417658, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '가가하우스 충무');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb41122-93c8-b649-0645-70b5c602079d', 122417658, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '27, Chungmu-ro 2-gil, Jung-gu, Seoul, South Korea');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb41122-93c8-b649-0645-70b5c602079d', 122417658, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '19');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb41122-93c8-b649-0645-70b5c602079d', 122417658, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located in the heart of Seoul, our guesthouse near Chungmuro Station offers the perfect base for travelers exploring the city. With convenient access to both Subway Line 3 and Line 4, you''re just a 5-minute walk from Chungmuro Station, making it easy to reach popular destinations such as Myeongdong, Dongdaemun, and Namsan.</p><p>Our guesthouse features modern and clean interiors, providing a comfortable and relaxing atmosphere for your stay. Each room is equipped with free Wi-Fi, air conditioning, and a private bathroom. The cozy ambiance will make you feel at home, while our friendly staff is dedicated to making your stay in Seoul truly memorable.</p><p>The surrounding area is filled with various restaurants, cafes, and shopping spots, adding to the convenience of your stay. If you''re looking for a quiet and safe environment in the bustling city, our guesthouse is the ideal choice. Experience the best of Seoul with us!</p><p>Please note that our building does not have an elevator.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12deb08a-0bb0-fb3e-e319-3cb37d2639d7', 122417658, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12deb08a-0bb0-fb3e-e319-3cb37d2639d7', 122417658, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–23:00</strong></p><p>Check-out: <strong>00:00–11:00</strong></p><p>Self check-in: Contact the property for the access code</p><p>The property will provide check-in details after booking</p><p>If you plan to arrive after 00:00 on your check-in day, please contact the property by email at least 1 day in advance.At the same time, please provide your check-in time</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c21132ba-a03a-50e2-e81f-59e94edcdbdd', 122417658, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c21132ba-a03a-50e2-e81f-59e94edcdbdd', 122417658, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children aged 1 and above are welcome at this hotel.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
