INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb41122-93c8-b649-0645-70b5c602079d', 122417658, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '27, Chungmu-ro 2-gil, Jung-gu, Seoul, Hàn Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb41122-93c8-b649-0645-70b5c602079d', 122417658, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '19');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6eb41122-93c8-b649-0645-70b5c602079d', 122417658, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Khi lưu trú tại gagahouse Chungmu, bạn sẽ có vị trí hoàn hảo để khám phá Jung-gu.</p><p>Thuộc tính này cũng cung cấp miễn phí nơi chứa hành lý và dịch vụ giặt là (tại chỗ nghỉ).</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12deb08a-0bb0-fb3e-e319-3cb37d2639d7', 122417658, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('12deb08a-0bb0-fb3e-e319-3cb37d2639d7', 122417658, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 23:00</strong></p><p>Trả phòng: <strong>00:00–11:00</strong></p><p>Tự nhận phòng: Liên lạc với chỗ nghỉ để biết mã vào phòng</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p><p>Nếu theo kế hoạch, bạn sẽ đến sau 00:00 vào ngày nhận phòng, vui lòng liên hệ với cơ sở lưu trú qua email trước ít nhất một ngày.Đồng thời, vui lòng cung cấp giờ nhận phòng của bạn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c21132ba-a03a-50e2-e81f-59e94edcdbdd', 122417658, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c21132ba-a03a-50e2-e81f-59e94edcdbdd', 122417658, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em 1 tuổi trở lên được chào đón tại khách sạn này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
