INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'stay sai');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '스테이사이');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '12-5 Jong-ro 31-gil, Jongno-gu, Seoul, 03129, South Korea');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '20');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located just a 3-minute walk from Jongno 5-ga Station, Stay SAI offers the perfect base for exploring Seoul. With easy access to Seoul Station and the airport limousine bus, it’s ideal for travelers looking for both comfort and convenience. Right across the street, you’ll find the lively Gwangjang Market, filled with authentic Korean street food and local culture. Major attractions such as Dongdaemun Shopping District, Heunginjimun Gate, Bukchon Hanok Village, Namsan Tower, Myeongdong, and the National Museum of Korea are all within easy reach. Each room is equipped with air conditioning and Korean-style floor heating (Ondol) for year-round comfort. Enjoy a good night’s sleep on our custom-made premium mattress with hotel-quality bedding. Basic amenities and essentials are provided for your convenience, along with complimentary Wi-Fi throughout the property. In our shared lounge, you can also experience a fun part of Korean culture — try six different kinds of “K-Ramen” for free, prepared easily using our ramen machine! Stay SAI is a cozy, stylish space where Seoul’s energy meets warm hospitality. Make yourself at home and create unforgettable memories in the heart of the city.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7774ca5b-7374-c460-6ebd-8c53294f7eca', 125386420, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7774ca5b-7374-c460-6ebd-8c53294f7eca', 125386420, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–23:30</strong></p><p>Check-out: <strong>01:30–11:00</strong></p><p>Self check-in kiosk</p><p>The property will provide check-in details after booking</p><p>To check-in, contact the property in advance.At the same time, please provide your check-in time</p>');
