INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'stay sai');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '스테이사이');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '12-5 Jong-ro 31-gil, Jongno-gu, 03129 Seoul, Hàn Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '20');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('4d31679c-87be-6807-c896-9fdf8b9c8e93', 125386420, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại Jongno-gu, Seoul, Stay SAI này cách Chợ Gwangjang vài bước và cách Trung tâm Thương mại Dongdaemun Market Mall 11 phút đi bộ. Hostel cách Cổng Heunginjimun 1 km và cách Làng Bukchon Hanok 2,4 km.</p><p>Hãy tận hưởng những dịch vụ, tiện ích, bao gồm quyền truy cập Internet không dây miễn phí và phòng sinh hoạt chung.</p><p>Khách có thể dùng bữa tại nhà hàng của Stay SAI hoặc ghé qua tiệm/cửa hàng đồ ăn nhanh để mua quà vặt và món ăn nhẹ. Hòa mình cùng đám đông tại tiệc chiêu đãi miễn phí được tổ chức hàng ngày. Thư giãn sau một ngày dài bên cạnh ly đồ uống yêu thích tại quầy bar/khu lounge.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm nhận phòng nhanh, dịch vụ trông giữ/bảo quản hành lý và phục vụ cà phê tại khu vực chung.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 20 phòng được trang bị máy điều hòa cùng sàn nhà có sưởi. Giường nệm cao su hoạt tính (memory foam) được trang bị bộ đồ giường cao cấp. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Tiện nghi phòng bao gồm tủ lạnh và lò vi sóng; bên cạnh đó dịch vụ dọn phòng cũng phục vụ dịch vụ dọn phòng (theo yêu cầu).</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7774ca5b-7374-c460-6ebd-8c53294f7eca', 125386420, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7774ca5b-7374-c460-6ebd-8c53294f7eca', 125386420, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 23:30</strong></p><p>Trả phòng: <strong>01:30–11:00</strong></p><p>Quầy tự nhận phòng</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p><p>Để nhận phòng, vui lòng liên hệ trước với cơ sở lưu trú.Đồng thời, vui lòng cung cấp giờ nhận phòng của bạn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a8a94d85-5cbd-a031-7cb1-4bc4a8ff29d6', 125386420, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a8a94d85-5cbd-a031-7cb1-4bc4a8ff29d6', 125386420, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1f0f389e-3a5c-f447-cab0-98e9ce8b969b', 125386420, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('1f0f389e-3a5c-f447-cab0-98e9ce8b969b', 125386420, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
