INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cbe8b202-226b-fe45-487d-452c800efa20', 126449817, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Great care is taken to ensure guests experience comfort through top-notch services and amenities.Remain linked during your visit by utilizing the complimentary internet access available.Crafted for coziness, every guestroom provides an array of features, guaranteeing a tranquil night''s sleep while maintaining the level of comfort.For a more enjoyable stay, select rooms at hotel are equipped with linen service, blackout curtains and air conditioning. For certain chosen rooms, guests can enjoy in-room amusement like television and cable TV as a part of their stay. Rest assured that your hydration needs will be met, as some guestrooms are equipped with a refrigerator, a coffee or tea maker, bottled water, instant coffee and instant tea.L Hostel Jonggak offers a hair dryer and toiletries in the restrooms of specific accommodations. Do you possess exceptional culinary skills? Prepare your meals personally within the hotel at its shared kitchen.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0cf99aba-23c4-4c6f-f81a-eea67972eb40', 126449817, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0cf99aba-23c4-4c6f-f81a-eea67972eb40', 126449817, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: [Mon-Sun]08:00–21:00</p><p>The host or staff will greet you upon arrival</p><p>Self check-in kiosk</p><p>The property will provide check-in details after booking</p>');
