INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cbe8b202-226b-fe45-487d-452c800efa20', 126449817, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'L hostel');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cbe8b202-226b-fe45-487d-452c800efa20', 126449817, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '엘호스텔');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cbe8b202-226b-fe45-487d-452c800efa20', 126449817, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '6-7FL, 19, Jong-ro 14-gil, Jongno-gu, Jongno-gu, 03190 Seoul, Hàn Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cbe8b202-226b-fe45-487d-452c800efa20', 126449817, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '28');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cbe8b202-226b-fe45-487d-452c800efa20', 126449817, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>L hostel cung cấp Wi-Fi miễn phí ở toàn bộ chỗ nghỉ và các phòng điều hòa ở Seoul. Du khách có thể thưởng thức đồ uống tại bar thức ăn nhẹ.</p><p>Phòng khách ở khách sạn được trang bị TV màn hình phẳng. Ngoài phòng tắm riêng, vòi sen và đồ vệ sinh cá nhân miễn phí, các phòng tại L hostel đều có view thành phố. Tại chỗ nghỉ, mỗi phòng đều được thiết kế có ga trải giường và khăn tắm.</p><p>Sân bay Quốc tế Gimpo cách 19 km.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0cf99aba-23c4-4c6f-f81a-eea67972eb40', 126449817, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0cf99aba-23c4-4c6f-f81a-eea67972eb40', 126449817, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: [Thứ 2-CN]08:00–21:00</p><p>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</p><p>Quầy tự nhận phòng</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('33d5efdf-fe00-e2ae-af98-b756dad29b55', 126449817, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
