INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('949f6ca9-ddb4-2680-3760-336353900a9a', 126449817, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
