INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('83c6d379-4cf0-13c4-d17d-fbcd79d9109e', 127170193, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'D STAY HOSTEL dongdaemun');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('83c6d379-4cf0-13c4-d17d-fbcd79d9109e', 127170193, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '디 스테이 호스텔 동대문');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('83c6d379-4cf0-13c4-d17d-fbcd79d9109e', 127170193, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '20 Jong-ro 46-gil, Jongno-gu, Seoul, 03119, South Korea');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('83c6d379-4cf0-13c4-d17d-fbcd79d9109e', 127170193, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '29');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('83c6d379-4cf0-13c4-d17d-fbcd79d9109e', 127170193, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>D Stay Hostel Dongdaemun, located in Seoul, is just a 1-minute walk from Dongdaemun Station and 3 minutes from Dongdaemun Market. Within a 1 km radius of the hostel, you''ll find famous attractions like Bangsan Market, and at 2 km, you can visit Jongmyo.</p><p>Enjoy a beautiful view of Dongdaemun from the 6th-floor rooftop garden.</p><p>The hostel offers essential amenities and services, including free wired internet and easy check-in. Each of the 29 air-conditioned rooms is equipped with a smart TV for your comfort. You can also prepare your meals in the shared kitchen, where free Korean ramen is provided. The memory foam beds come with high-quality bedding, ensuring a restful stay. The bathrooms are equipped with a shower and a hairdryer.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77ea0dda-1313-cc54-ff71-451a0b78d0dc', 127170193, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77ea0dda-1313-cc54-ff71-451a0b78d0dc', 127170193, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: [Mon-Sun]08:00–02:00 the next day</p><p>The host or staff will greet you upon arrival</p><p>Self check-in kiosk</p><p>The property will provide check-in details after booking</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3a6d2121-2e68-e6a5-3a0b-5d1fb8b20662', 127170193, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3a6d2121-2e68-e6a5-3a0b-5d1fb8b20662', 127170193, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children aged 3 and above are welcome at this hotel.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
