INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('83c6d379-4cf0-13c4-d17d-fbcd79d9109e', 127170193, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Nằm ở Jongno-gu, Seoul với phòng chờ chung và sân hiên, D Stay Hostel Dongdaemun cung cấp chỗ nghỉ có Wi-Fi miễn phí. Chỗ nghỉ này cung cấp bếp chung, dịch vụ tiền sảnh và phòng giữ hành lý cho khách.</p><p>Tại hostel, các phòng đều có bàn làm việc, TV màn hình phẳng, phòng tắm riêng, ga trải giường và khăn tắm. Tất cả các phòng đều có tủ lạnh.</p><p>Sân bay Quốc tế Gimpo cách 21 km.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77ea0dda-1313-cc54-ff71-451a0b78d0dc', 127170193, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('77ea0dda-1313-cc54-ff71-451a0b78d0dc', 127170193, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: [Thứ 2-CN]08:00–02:00 ngày hôm sau</p><p>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</p><p>Quầy tự nhận phòng</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3a6d2121-2e68-e6a5-3a0b-5d1fb8b20662', 127170193, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('3a6d2121-2e68-e6a5-3a0b-5d1fb8b20662', 127170193, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em 3 tuổi trở lên được chào đón tại khách sạn này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bd934383-711b-e644-4a44-cda0d451deed', 127170193, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
