INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4cf71b3-8543-461f-b7a0-ec985797b672', 129369266, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', 'ໂຮງແຮມສະຖານພັກຜ່ອນ ເຊຶ່ງທ່ອງ (ສາຂາໃຈກາງ ຖະໜົນສີສະຫວ່າງວົງ - ເມືອງເກົ່າຫຼວງພະບາງ)');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4cf71b3-8543-461f-b7a0-ec985797b672', 129369266, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'V4VQ+X83, Ban Vat Nong, Kounxoa Road, Luang Prabang, Luang Prabang Province, 06000, Laos');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4cf71b3-8543-461f-b7a0-ec985797b672', 129369266, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '20');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4cf71b3-8543-461f-b7a0-ec985797b672', 129369266, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Xiengthong Sanctuary Hotel | Healing Haven in Luang Prabang''s Cultural Heart</p><p>Perched at the soul of the UNESCO Heritage Quarter – epicenter of Vientiane Street, mere steps from the millennium-old Wat Xiengthong. Our Haussmann architectural frame cradles Lanna Dynasty teak artistry, while 20 sanctuaries with natural latex mattresses and European white goose down bedding let you embrace heritage dreams by the Mekong.</p><p>‧ Sacred Locale: V4VQ+X83, Ban Vat Nong, Kounxoa Road</p><p>‧ Dawn Alms Ritual: Witness monks'' alms procession at 5:30am before our gates</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('10dc4088-e422-5bad-dc1d-36ac5c981bb6', 129369266, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('10dc4088-e422-5bad-dc1d-36ac5c981bb6', 129369266, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 14:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p><p>The host or staff will greet you upon arrival</p><p>The property will provide check-in details after booking</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('100bbeb9-7a58-61e0-e0f7-3b3f6990e2ba', 129369266, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
