INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4cf71b3-8543-461f-b7a0-ec985797b672', 129369266, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', 'ໂຮງແຮມສະຖານພັກຜ່ອນ ເຊຶ່ງທ່ອງ (ສາຂາໃຈກາງ ຖະໜົນສີສະຫວ່າງວົງ - ເມືອງເກົ່າຫຼວງພະບາງ)');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4cf71b3-8543-461f-b7a0-ec985797b672', 129369266, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'V4VQ+X83, Ban Vat Nong, Kounxoa Road, 06000 Luang Prabang, Louangphabang (tỉnh), Lào');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4cf71b3-8543-461f-b7a0-ec985797b672', 129369266, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '20');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f4cf71b3-8543-461f-b7a0-ec985797b672', 129369266, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại Luang Prabang, Xieng Thong Retreat Hotel (Luang Prabang Old Town - Central Sisavangvong Road Branch) là cơ sở tuyệt vời để khám phá thành phố.</p><p>Dùng bữa tại nhà hàng nhà hàng trong nhà phục vụ các món ăn Quốc tế. Trong thời gian rảnh rỗi, hãy nhâm nhi đồ uống tại bar hoặc nâng cao giác quan của bạn với cà phê tại cà phê.</p><p>Tại khách sạn này, bạn cũng sẽ tìm thấy các cơ sở bao gồm vườn và phòng trà. Thuộc tính này cũng cung cấp đổi tiền, miễn phí nơi chứa hành lý và dịch vụ giặt là (tại chỗ nghỉ).</p><p>Chỗ đỗ xe có sẵn tại chỗ nghỉ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('10dc4088-e422-5bad-dc1d-36ac5c981bb6', 129369266, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('10dc4088-e422-5bad-dc1d-36ac5c981bb6', 129369266, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 14:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('100bbeb9-7a58-61e0-e0f7-3b3f6990e2ba', 129369266, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('100bbeb9-7a58-61e0-e0f7-3b3f6990e2ba', 129369266, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 17 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6c883821-04d5-09c0-86cd-87499dd532ea', 129369266, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('6c883821-04d5-09c0-86cd-87499dd532ea', 129369266, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae2cc1de-180d-22db-33af-7a1fe8a40e77', 129369266, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('ae2cc1de-180d-22db-33af-7a1fe8a40e77', 129369266, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Thực đơn cố định</p><p>Ẩm thực: Tây phương, Trung Quốc</p><p>Giờ mở cửa: [Thứ 2 - CN] 08:00-10:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi</td><td>Miễn phí</td></tr><tr><td>Người lớn</td><td>3,00 US$(khoảng 77.892₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('512b5f24-eaa9-c2ae-b899-a02bc5dec1ff', 129369266, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
