INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Kimpton TSIM SHA TSUI HONG KONG by IHG');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', '香港尖沙咀金普頓酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '11 Middle Rd, Yau Tsim Mong District, Hong Kong, China');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '495');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Enter Kimpton Tsim Sha Tsui, where modern interpretations of local heritage intertwine with multicultural cues. This metropolitan escape along the Hong Kong harbor sparks cultural and human connections for guests to immerse themselves. Extraordinary luxuries can be found on every floor – from the lobby to the dining room, the 50th-story rooftop pool to the spacious wellness center – before retreating to an elegant harbor view room.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aa3b5ebb-fab4-51d6-2951-c2634ebdb6e8', 130238078, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aa3b5ebb-fab4-51d6-2951-c2634ebdb6e8', 130238078, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p><p>The property will provide check-in details after booking</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('60058861-94bb-d250-79a4-dd1b59cea9cd', 130238078, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('60058861-94bb-d250-79a4-dd1b59cea9cd', 130238078, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Children between 0 and 11 years old can stay for free if no extra bed is needed.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cf4d52d9-a20b-0569-b2ad-6b2320253ca7', 130238078, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cf4d52d9-a20b-0569-b2ad-6b2320253ca7', 130238078, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8c4bf0b3-29d5-35dd-7892-3f63e8bda341', 130238078, 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8c4bf0b3-29d5-35dd-7892-3f63e8bda341', 130238078, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Western, Chinese</p><p>Opening hours: [Mon - Sun] 06:30-10:30 Open</p><table><tr><td>Children 5 years old and under</td><td>Free</td></tr><tr><td>Children 6–11 years old</td><td>HK$209.00 (approx. $26.65) per person</td></tr><tr><td>Children 12–17 years old</td><td>HK$418.00 (approx. $53.29) per person</td></tr><tr><td>Adult</td><td>HK$418.00 (approx. $53.29) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fb6d9a4a-2ede-ca7d-00d4-2dc9fa1c79b4', 130238078, 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fb6d9a4a-2ede-ca7d-00d4-2dc9fa1c79b4', 130238078, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>The deposit is determined based on the duration of your stay. The charge is HK$2,000.00 (approx. $254.98) per night.</strong></p><p>Deposit Payment Methods: <strong>This property accepts cash and credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment within 14 days after check-out.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f440047b-7f20-20b5-4b25-9c6353a1a6be', 130238078, 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f440047b-7f20-20b5-4b25-9c6353a1a6be', 130238078, 'POLICY', 'pet', 'en', 'policy_content', '<p>Pets are allowed on request</p><p>Types of pets allowed: dogs, cats</p>');
