INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Kimpton TSIM SHA TSUI HONG KONG by IHG');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', '香港尖沙咀金普頓酒店');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '11 Middle Rd, Yau Tsim Mong District, Hồng Kông, Trung Quốc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'CN');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '495');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('90e9e627-2e78-fa3c-1ef9-25218c51fd64', 130238078, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Enter Kimpton Tsim Sha Tsui, where modern interpretations of local heritage intertwine with multicultural cues. This metropolitan escape along the Hong Kong harbor sparks cultural and human connections for guests to immerse themselves. Extraordinary luxuries can be found on every floor – from the lobby to the dining room, the 50th-story rooftop pool to the spacious wellness center – before retreating to an elegant harbor view room.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aa3b5ebb-fab4-51d6-2951-c2634ebdb6e8', 130238078, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('aa3b5ebb-fab4-51d6-2951-c2634ebdb6e8', 130238078, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('60058861-94bb-d250-79a4-dd1b59cea9cd', 130238078, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('60058861-94bb-d250-79a4-dd1b59cea9cd', 130238078, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Trẻ từ 0 đến 11 tuổi được lưu trú miễn phí nếu không sử dụng giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cf4d52d9-a20b-0569-b2ad-6b2320253ca7', 130238078, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('cf4d52d9-a20b-0569-b2ad-6b2320253ca7', 130238078, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8c4bf0b3-29d5-35dd-7892-3f63e8bda341', 130238078, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('8c4bf0b3-29d5-35dd-7892-3f63e8bda341', 130238078, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Ẩm thực: Tây phương, Trung Quốc</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:30 Đang Mở</p><table><tr><td>Trẻ em 5 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 6–11 tuổi</td><td>209,00 HK$(khoảng 692.056₫) mỗi người</td></tr><tr><td>Trẻ em 12–17 tuổi</td><td>418,00 HK$(khoảng 1.384.113₫) mỗi người</td></tr><tr><td>Người lớn</td><td>418,00 HK$(khoảng 1.384.113₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fb6d9a4a-2ede-ca7d-00d4-2dc9fa1c79b4', 130238078, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('fb6d9a4a-2ede-ca7d-00d4-2dc9fa1c79b4', 130238078, 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khoản tiền cọc được tính dựa trên độ dài lưu trú của bạn. Mức phí là 2.000,00 HK$ (khoảng 6.622.549₫)/đêm.</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận tiền mặt và thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 14 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f440047b-7f20-20b5-4b25-9c6353a1a6be', 130238078, 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f440047b-7f20-20b5-4b25-9c6353a1a6be', 130238078, 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó, mèo</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('5dd27655-613f-6a9b-1a4e-ee264f36cb26', 130238078, 'POLICY', 'serviceAnimal', 'vi', 'policy_title', 'Động vật hỗ trợ');
