INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hotel Frihavnen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Århusgade 124B, Osterbro, Copenhagen, Hovedstaden, 2150, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '28');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Hotel Frihavnen in Copenhagen (Nordhavn), you''ll be a 5-minute drive from Strøget and 7 minutes from Tivoli Gardens. This hotel is 2.6 mi (4.2 km) from Nyhavn and 3.1 mi (5 km) from City Hall Square.</p><p>Take advantage of recreation opportunities such as bicycles to rent, or other amenities including complimentary wireless internet access and concierge services.</p><p>Continental breakfasts are available daily from 7:00 AM to 10:00 AM for a fee.</p><p>Featured amenities include multilingual staff, luggage storage, and an elevator.</p><p>Make yourself at home in one of the 28 air-conditioned guestrooms. Complimentary wireless internet access is available to keep you connected. Private bathrooms with showers feature complimentary toiletries and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('85c1bd66-7c89-40d1-0b00-3c91500c5c40', 131793034, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('85c1bd66-7c89-40d1-0b00-3c91500c5c40', 131793034, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–22:00</strong></p><p>Check-out: <strong>07:00–12:00</strong></p><p>Front desk hours: [Mon-Sun]06:00–21:00</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc40b954-efa9-37d0-016f-c2136f35a29f', 131793034, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc40b954-efa9-37d0-016f-c2136f35a29f', 131793034, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73963c75-b1ae-484a-1d94-ee8b2d3e77a8', 131793034, 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73963c75-b1ae-484a-1d94-ee8b2d3e77a8', 131793034, 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
