INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0f583e48-670f-cf9a-5712-8d462adfee88', 131793034, 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Cuisine: Continental</p><p>Opening hours: [Mon - Sun] 07:00-10:00 Open</p><table><tr><td>Children 17 years old and under</td><td>DKK 350 (approx. $53.32) per person</td></tr><tr><td>Adult</td><td>Contact property</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
