INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Hotel Frihavnen');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Århusgade 124B, Osterbro, 2150 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '28');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('48584a31-715e-f14b-b211-518a9c85488d', 131793034, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Hotel Frihavnen ở Nordhavn, Copenhagen, cách Phố Strøget 5 phút lái xe và cách Công viên Tivoli 7 phút lái xe. Khách sạn này cách Khu Nyhavn 4,2 km và cách Quảng trường Tòa thị chính 5 km.</p><p>Đừng bỏ qua cơ hội tận hưởng những dịch vụ thư giãn, giải trí như xe đạp cho thuê, hay những tiện nghi khác như quyền truy cập Internet không dây miễn phí và dịch vụ tư vấn/hỗ trợ khách.</p><p>Khách có thể dùng bữa sáng kiểu Âu (có phụ phí) từ 7:00 đến 10:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm nhân viên thông thạo nhiều ngôn ngữ, dịch vụ trông giữ/bảo quản hành lý và thang máy.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 28 phòng được trang bị máy điều hòa. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Phòng tắm riêng với buồng tắm vòi sen có đồ dùng nhà tắm miễn phí và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('85c1bd66-7c89-40d1-0b00-3c91500c5c40', 131793034, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('85c1bd66-7c89-40d1-0b00-3c91500c5c40', 131793034, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>15:00 – 22:00</strong></p><p>Trả phòng: <strong>07:00–12:00</strong></p><p>Giờ làm việc của quầy lễ tân: [Thứ 2-CN]06:00–21:00</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc40b954-efa9-37d0-016f-c2136f35a29f', 131793034, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('bc40b954-efa9-37d0-016f-c2136f35a29f', 131793034, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73963c75-b1ae-484a-1d94-ee8b2d3e77a8', 131793034, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('73963c75-b1ae-484a-1d94-ee8b2d3e77a8', 131793034, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0f583e48-670f-cf9a-5712-8d462adfee88', 131793034, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('0f583e48-670f-cf9a-5712-8d462adfee88', 131793034, 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Ẩm thực: Đại lục</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>350 DKK(khoảng 1.384.185₫) mỗi người</td></tr><tr><td>Người lớn</td><td>Liên hệ khách sạn</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('a0553d15-e252-9769-bbe7-f54f954ffe1c', 131793034, 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
