INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2297907c-682e-15b5-6aae-05307c68f627', 133678007, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Studio 6 Houston, TX – Pearland/Medical Center');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2297907c-682e-15b5-6aae-05307c68f627', 133678007, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '14150 Fayridge Dr, Houston, Texas, 77048');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2297907c-682e-15b5-6aae-05307c68f627', 133678007, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '8');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2297907c-682e-15b5-6aae-05307c68f627', 133678007, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Studio 6 Houston, TX – Pearland/Medical Center in Houston (Southeast Houston), you''ll be within a 15-minute drive of Reliant Park and Houston Methodist Hospital. This hotel is 9.5 mi (15.4 km) from University of Houston and 12.6 mi (20.3 km) from Reliant Stadium.</p><p>Make use of convenient amenities, which include complimentary wireless internet access and a vending machine.</p><p>Grab a bite from the snack bar/deli serving guests of Studio 6 Houston, TX – Pearland/Medical Center.</p><p>Featured amenities include a 24-hour front desk, laundry facilities, and an elevator. Free self parking is available onsite.</p><p>Make yourself at home in one of the 48 air-conditioned rooms featuring kitchenettes with refrigerators and microwaves. Flat-screen televisions with cable programming provide entertainment, while complimentary wireless internet access keeps you connected. Conveniences include phones, as well as desks and coffee/tea makers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4c076ba-dd3a-4461-5862-e768dd37976a', 133678007, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4c076ba-dd3a-4461-5862-e768dd37976a', 133678007, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7fa5879f-dbaf-ba68-acbf-34eb4a8c254e', 133678007, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('7fa5879f-dbaf-ba68-acbf-34eb4a8c254e', 133678007, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children aged 17 and above are welcome at this hotel.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
