INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('41204945-99b5-3679-daab-81e7c365fa43', 133678007, 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of $50.00 is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards</strong></p><p>Deposit Refund: <strong>Within 7 days after check-out</strong></p>');
