INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2297907c-682e-15b5-6aae-05307c68f627', 133678007, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Studio 6 Houston, TX – Pearland/Medical Center');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2297907c-682e-15b5-6aae-05307c68f627', 133678007, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '14150 Fayridge Dr, 77048 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2297907c-682e-15b5-6aae-05307c68f627', 133678007, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '8');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('2297907c-682e-15b5-6aae-05307c68f627', 133678007, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Studio 6 Houston, TX – Pearland/Medical Center ở Đông Nam Houston, Houston, cách Khu liên hợp Thể thao NRG Park và Bệnh viện Houston Methodist 15 phút lái xe. Khách sạn này cách Đại học Houston 15,4 km và cách Sân vận động NRG 20,3 km.</p><p>Hãy tận hưởng những dịch vụ, tiện ích, bao gồm quyền truy cập Internet không dây miễn phí và máy bán hàng tự động.</p><p>Khách có thể tìm thấy nhiều quà vặt và món ăn nhẹ tại tiệm/cửa hàng đồ ăn nhanh của Studio 6 Houston, TX – Pearland/Medical Center.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm quầy tiếp tân phục vụ 24 giờ/ngày, trang thiết bị giặt ủi và thang máy. Có bãi đậu xe tự phục vụ miễn phí trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 48 phòng được trang bị máy điều hòa với bếp nhỏ cùng tủ lạnh và lò vi sóng. Khách có thể giải trí với TV màn hình phẳng cùng các chương trình truyền hình cáp; trong khi đó kết nối internet không dây miễn phí giữ bạn luôn kết nối. Tiện nghi phòng bao gồm điện thoại, cùng bàn và dụng cụ pha cà phê/trà.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4c076ba-dd3a-4461-5862-e768dd37976a', 133678007, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('e4c076ba-dd3a-4461-5862-e768dd37976a', 133678007, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
