INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c92a1517-400c-8416-9d94-37722e94439c', 133684273, 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', '5501 La Branch Street, Houston, Texas, 77004');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c92a1517-400c-8416-9d94-37722e94439c', 133684273, 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '51');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c92a1517-400c-8416-9d94-37722e94439c', 133684273, 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located in Houston (South Central Houston), Sentral Forme Houston is within a 15-minute walk of Rice University and Houston Zoo. This luxury aparthotel is 2.1 mi (3.4 km) from MD Anderson Cancer Center and 3 mi (4.8 km) from Toyota Center.</p><p>Don''t miss out on the many recreational opportunities, including an outdoor pool, a hot tub, and a 24-hour fitness center.</p><p>Featured amenities include express check-in, a 24-hour front desk, and an elevator. Self parking (subject to charges) is available onsite.</p><p>Make yourself at home in one of the 33 air-conditioned rooms featuring kitchens with full-sized refrigerators/freezers and ovens. 55-inch Smart televisions are provided, with digital programming available. Conveniences include separate sitting areas and microwaves.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f466ca08-a78b-8ea8-b274-1bc989e75d9e', 133684273, 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f466ca08-a78b-8ea8-b274-1bc989e75d9e', 133684273, 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>00:00–16:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('26902821-ee9e-ae85-e164-0f41a2a899e8', 133684273, 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('26902821-ee9e-ae85-e164-0f41a2a899e8', 133684273, 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
