INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c92a1517-400c-8416-9d94-37722e94439c', 133684273, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Sentral Forme Houston');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c92a1517-400c-8416-9d94-37722e94439c', 133684273, 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', '5501 La Branch Street, 77004 Houston, Texas, Hoa Kỳ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c92a1517-400c-8416-9d94-37722e94439c', 133684273, 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '51');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('c92a1517-400c-8416-9d94-37722e94439c', 133684273, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Sentral Forme Houston ở South Central Houston, Houston, cách Đại học Rice và Sở thú Houston 15 phút đi bộ. Khách sạn căn hộ sang trọng này cách Viện Ung thư MD Anderson 3,4 km và cách Trung tâm Toyota 4,8 km.</p><p>Đừng bỏ qua những dịch vụ, tiện nghi thể thao, giải trí tuyệt vời, bao gồm hồ bơi ngoài trời, bồn tắm thủy lực và trung tâm thể dục phục vụ 24 giờ.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm nhận phòng nhanh, quầy tiếp tân phục vụ 24 giờ/ngày và thang máy. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 33 phòng được trang bị máy điều hòa với bếp cùng tủ lạnh/tủ đông cỡ lớn và lò nướng. Các phòng được trang bị Smart TV 55-inch cùng các chương trình truyền hình kỹ thuật số. Tiện nghi phòng bao gồm khu tiếp khách tách biệt và lò vi sóng.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f466ca08-a78b-8ea8-b274-1bc989e75d9e', 133684273, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('f466ca08-a78b-8ea8-b274-1bc989e75d9e', 133684273, 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>00:00 – 16:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('26902821-ee9e-ae85-e164-0f41a2a899e8', 133684273, 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('26902821-ee9e-ae85-e164-0f41a2a899e8', 133684273, 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d80273a8-f454-ddd5-a777-b09da905bbc1', 133684273, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('d80273a8-f454-ddd5-a777-b09da905bbc1', 133684273, 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('b636d602-5291-c15e-74ad-bdfe1b33fa10', 133684273, 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
