INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('99b84150-ee5e-525d-c98e-e211785684d1', 135506466, 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>HOTEL SEPT Hongje nằm ở Seodaemun-gu, Seoul. Khách sạn 2 sao này có các phòng được trang bị điều hòa, phòng tắm riêng và Wi-Fi miễn phí. Khách sạn có phòng gia đình.</p><p>Các căn ở khách sạn được trang bị TV màn hình phẳng. Tại HOTEL SEPT Hongje, các phòng đều đi kèm với ga trải giường và khăn tắm.</p><p>Sân bay Quốc tế Gimpo cách 16 km.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (row_uuid, property_id, type, section_type, lang, field, value) VALUES ('55c23b30-284c-dddf-b3ca-22d0ae33394b', 135506466, 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
